INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秋天到来的了，树叶黄了。", "corrected_sentence": "秋天到来了，树叶黄了。", "error_description": "错误：“到来的了”在“了”前多加了“的”。“到来”作谓语时不加“的”，加“的”后“到来”变成定语，后面不能接谓语，不成句。正确形式是“秋天到来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天春节就要到来过，家家户户都很忙。", "corrected_sentence": "明天春节就要到来，家家户户都很忙。", "error_description": "错误：“到来”后多加了“过”。“过”表示曾经的经历，与“就要”所表示的将来不符。正确形式是去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
