INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91116, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "旧时指科举考试中选，特别是考中进士。", "primary_collocate": null, "pronunciation": "jí dì", "ipa": "tɕi˧˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "他在京城参加科举，终于及第了。", "target_word": "及第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的书生都盼着能及第。", "target_word": "及第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥去京城赶考，可惜没有及第。", "target_word": "及第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说儿子在科举中及第，全家都高兴极了。", "target_word": "及第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他及第以后，皇帝让他去当县官。", "target_word": "及第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子很多年没人及第过。", "target_word": "及第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在科举中不但及第了，而且是第一名。", "target_word": "及第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考官读了他的文章，说他一定能及第。", "target_word": "及第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的书生想及第，要先读很多年书。", "target_word": "及第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考了三次科举，第四次才及第。", "target_word": "及第", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "及第了", "label": "体标"}, {"form": "及第过", "label": "体标"}, {"form": "状元及第", "label": "复合"}], "register": "书面", "sense_fingerprint": "旧时科举考试中选，尤指考中进士", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5eb1fb1c-7db6-4494-864a-ef12b168785b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91116, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "及第", "is_correct": true, "explanation": "及第：本题目标词，读作 jí dì，指旧时科举中选。"}, {"text": "基地", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是基地（根据地）。"}, {"text": "寄递", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是寄递（邮寄传递）。"}, {"text": "急待", "is_correct": false, "explanation": "dài（第四声）与 dì（第四声）韵母不同，意思是急切地需要或等待。"}], "explanations": {"及第": "及第：本题目标词，读作 jí dì，指旧时科举中选。", "基地": "jī（第一声）与 jí（第二声）声调不同，意思是基地（根据地）。", "寄递": "jì（第四声）与 jí（第二声）声调不同，意思是寄递（邮寄传递）。", "急待": "dài（第四声）与 dì（第四声）韵母不同，意思是急切地需要或等待。"}, "sentence_index": null, "correct_answer": "及第"}, "level_3": {"options": [{"text": "及第", "is_correct": true, "explanation": "及第：科举中选，与“终于”搭配，符合句意。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：“毕业”用于学校，不用于科举考试。"}, {"text": "退休", "is_correct": false, "explanation": "语义：退休与“参加科举”矛盾，参加考试的人不会退休。"}, {"text": "出发", "is_correct": false, "explanation": "语义：“在京城”说明人已经在京城，“出发”与之矛盾。"}], "explanations": {"及第": "及第：科举中选，与“终于”搭配，符合句意。", "毕业": "搭配：“毕业”用于学校，不用于科举考试。", "退休": "语义：退休与“参加科举”矛盾，参加考试的人不会退休。", "出发": "语义：“在京城”说明人已经在京城，“出发”与之矛盾。"}, "sentence_index": 0, "correct_answer": "及第"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的公司这次投标及第了。", "explanation": "这里应该用〈中标〉。及第只指科举中选，投标中选不说“及第”。"}, {"text": "他在运动会上及第了。", "explanation": "这里应该用〈获奖〉。及第只指科举中选，运动会上获奖不说“及第”。"}, {"text": "他在国家队选拔中及第了。", "explanation": "这里应该用〈入选〉。及第是科举用语，不用于国家队这类一般选拔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a6991f3-ea0c-4ae2-bfd6-d019767f2eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91116, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "及第", "is_correct": true, "explanation": "及第：本题目标词，读作 jí dì，指旧时科举中选。"}, {"text": "基底", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）、dǐ（第三声）与 dì（第四声）声调都不同，意思是基础、底子。"}, {"text": "极力", "is_correct": false, "explanation": "lì（第四声）与 dì（第四声）声母不同，意思是竭尽全力。"}, {"text": "集体", "is_correct": false, "explanation": "jí 相同，tǐ（第三声）与 dì（第四声）声母和声调都不同，意思是团体。"}, {"text": "见地", "is_correct": false, "explanation": "jiàn（第四声）与 jí（第二声）韵母和声调不同，意思是见解。"}], "explanations": {"及第": "及第：本题目标词，读作 jí dì，指旧时科举中选。", "基底": "jī（第一声）与 jí（第二声）、dǐ（第三声）与 dì（第四声）声调都不同，意思是基础、底子。", "极力": "lì（第四声）与 dì（第四声）声母不同，意思是竭尽全力。", "集体": "jí 相同，tǐ（第三声）与 dì（第四声）声母和声调都不同，意思是团体。", "见地": "jiàn（第四声）与 jí（第二声）韵母和声调不同，意思是见解。"}, "sentence_index": null, "correct_answer": "及第"}, "level_3": {"options": [{"text": "及第", "is_correct": true, "explanation": "及第：科举中选，与“不但……而且是第一名”的语境相符。"}, {"text": "落第", "is_correct": false, "explanation": "语义：落第与后面的“第一名”矛盾，考试没有考中不可能是第一名。"}, {"text": "辞职", "is_correct": false, "explanation": "搭配：“辞职”用于工作单位，不用于科举考试。"}, {"text": "退学", "is_correct": false, "explanation": "搭配：“退学”用于学校，不用于科举考试。"}], "explanations": {"及第": "及第：科举中选，与“不但……而且是第一名”的语境相符。", "落第": "语义：落第与后面的“第一名”矛盾，考试没有考中不可能是第一名。", "辞职": "搭配：“辞职”用于工作单位，不用于科举考试。", "退学": "搭配：“退学”用于学校，不用于科举考试。"}, "sentence_index": 6, "correct_answer": "及第"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次数学考试及第了。", "explanation": "这里应该用〈及格〉。及第只指旧时科举中选，学校考试用“及格”。"}, {"text": "他面试及第了。", "explanation": "这里应该用〈通过〉。及第专指科举中选，面试不用“及第”。"}, {"text": "这批产品及第了。", "explanation": "这里应该用〈合格〉。及第只用于人在科举中考中，产品不能说“及第”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a6991f3-ea0c-4ae2-bfd6-d019767f2eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的祖父当年被及第了，做了县令。", "corrected_sentence": "他的祖父当年及第了，做了县令。", "error_description": "错误：在“及第”前加了“被”。“及第”是不及物动词，不能构成被动句。应说“他的祖父当年及第了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a6991f3-ea0c-4ae2-bfd6-d019767f2eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年没及第了，很难过。", "corrected_sentence": "他去年没及第，很难过。", "error_description": "错误：否定句“没及第”后面多加了“了”。“没”与“了”不能同时用在这里，应去掉“了”，说“他去年没及第”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a6991f3-ea0c-4ae2-bfd6-d019767f2eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
