INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91127, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "里面和外面。", "primary_collocate": null, "pronunciation": "lǐ wài", "ipa": "li˨˩˦ waɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他把屋子里外都打扫了。", "target_word": "里外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子里外都很干净。", "target_word": "里外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口里外站满了人。", "target_word": "里外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把车里外洗了一遍。", "target_word": "里外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店里外都有人在排队。", "target_word": "里外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里外种了很多花。", "target_word": "里外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你看看箱子里外有没有水。", "target_word": "里外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋子里外的灯都开着。", "target_word": "里外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服里外都是白色的。", "target_word": "里外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山洞里外一样黑。", "target_word": "里外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "里里外外", "label": "重叠"}], "register": "中性", "sense_fingerprint": "物体或空间的里面和外面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eafbf73-fe6d-4ac7-932f-9a09579e5b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91127, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "里外", "is_correct": true, "explanation": "「里外」指屋子的里面和外面，「都打扫了」说明里外两边都要做，与语境相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：「天空」指天上的空间，不是可以打扫的屋子部分，与「屋子」冲突。"}, {"text": "河流", "is_correct": false, "explanation": "语义：「河流」是自然地理事物，不属于屋子，不能作为打扫的对象。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：「打扫」的对象是空间或物体，「时间」不能被打扫。"}], "explanations": {"里外": "「里外」指屋子的里面和外面，「都打扫了」说明里外两边都要做，与语境相符。", "天空": "语义：「天空」指天上的空间，不是可以打扫的屋子部分，与「屋子」冲突。", "河流": "语义：「河流」是自然地理事物，不属于屋子，不能作为打扫的对象。", "时间": "搭配：「打扫」的对象是空间或物体，「时间」不能被打扫。"}, "sentence_index": 0, "correct_answer": "里外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "钥匙放在抽屉里外。", "explanation": "这里应该用〈里面〉。里外指里面和外面两边，钥匙只在一边时要说里面。"}, {"text": "他把自行车停进了车里外。", "explanation": "这里应该用〈外面〉。里外指两边，自行车只停在车的一侧，要说车外面。"}, {"text": "箱子里外贴着一张标签。", "explanation": "这里应该用〈表面〉。标签只贴在一个面上，要说箱子表面，不说里外。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91127, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "里外", "is_correct": true, "explanation": "「箱子里外」指箱子的里面和外面，与「有没有水」的语境相符。"}, {"text": "大海", "is_correct": false, "explanation": "语义：「大海」不能放进箱子，与「箱子」冲突。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：「有没有水」只用于能盛水的东西，不能用于「性格」。"}, {"text": "邻居", "is_correct": false, "explanation": "语义：「邻居」是人，不是箱子的一部分，与「箱子」冲突。"}], "explanations": {"里外": "「箱子里外」指箱子的里面和外面，与「有没有水」的语境相符。", "大海": "语义：「大海」不能放进箱子，与「箱子」冲突。", "性格": "搭配：「有没有水」只用于能盛水的东西，不能用于「性格」。", "邻居": "语义：「邻居」是人，不是箱子的一部分，与「箱子」冲突。"}, "sentence_index": 6, "correct_answer": "里外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把杯子放在桌子里外。", "explanation": "这里应该用〈上面〉。里外指内外两面，杯子只在桌面一侧，要说桌子上面。"}, {"text": "客人走进了屋子里外。", "explanation": "这里应该用〈里面〉。里外指内外两面，客人只走到屋内一侧，要说屋子里面。"}, {"text": "这个书包里外的价格很便宜。", "explanation": "这里应该去掉〈里外〉，直接说书包的价格。里外指内外两面，价格没有内外之分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91127, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把房间里外了都擦了一遍。", "corrected_sentence": "他把房间里外都擦了一遍。", "error_description": "错误：「里外了」，正确：「里外」。「里外」是方位名词，后面不能直接加「了」，应去掉「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91127, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把厨房里外里外都收拾了一遍。", "corrected_sentence": "妈妈把厨房里里外外都收拾了一遍。", "error_description": "错误：「里外里外」，正确：「里里外外」。表示遍及各处要用重叠形式「里里外外」，「里外」不能整体重复。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
