INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91135, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "围绕是围着一个东西转一圈又一圈。", "primary_collocate": null, "pronunciation": "wéi rào", "ipa": "weɪ˧˥ ɻaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们围绕着大树跑来跑去。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮围绕地球转。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟围绕着花园飞了一圈。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家围绕火堆唱歌跳舞。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗围绕主人跑，很高兴。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂围绕花朵飞来飞去。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们围绕着湖边走了一圈。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子围绕着妈妈玩游戏。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球围绕太阳转一年。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友围绕老师坐成一圈。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "围绕着", "label": "体标"}, {"form": "围绕了", "label": "体标"}, {"form": "围绕过", "label": "体标"}], "register": "中性", "sense_fingerprint": "绕着某个东西转圈、环绕", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf90865-4d6c-41d7-9be1-67a6da867aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91135, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "围绕着", "is_correct": true, "explanation": "正确：“围绕着”表示绕着大树转圈，与后文“跑来跑去”相合。"}, {"text": "修剪着", "is_correct": false, "explanation": "语义：孩子不能一边修剪大树一边跑来跑去，与情境不合。"}, {"text": "背着", "is_correct": false, "explanation": "语义：“背着大树”意为背负大树，与跑来跑去的情境不合。"}, {"text": "追赶着", "is_correct": false, "explanation": "搭配：“追赶”的对象多为人或动物，不说追赶大树。"}], "explanations": {"围绕着": "正确：“围绕着”表示绕着大树转圈，与后文“跑来跑去”相合。", "修剪着": "语义：孩子不能一边修剪大树一边跑来跑去，与情境不合。", "背着": "语义：“背着大树”意为背负大树，与跑来跑去的情境不合。", "追赶着": "搭配：“追赶”的对象多为人或动物，不说追赶大树。"}, "sentence_index": 0, "correct_answer": "围绕着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "士兵围绕了敌人的阵地。", "explanation": "这里应该用〈包围〉。围绕指绕着中心转动，不用于敌人从四面合围。"}, {"text": "孩子们围绕老师站成一排。", "explanation": "这里不宜用〈围绕〉。围绕表示绕成圈，站成一排不是圆形，形状与词义不符。"}, {"text": "小鸟围绕着天空飞向远方。", "explanation": "这里应该用〈飞向〉。围绕指绕着某物转圈，直线飞向远方不能用“围绕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91135, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "围绕着", "is_correct": true, "explanation": "正确：“围绕着”表示绕着湖边走圈，与“走了一圈”相合。"}, {"text": "离开", "is_correct": false, "explanation": "语义：“离开着湖边走了一圈”前后矛盾，离开与绕圈走的情境不合。"}, {"text": "远离", "is_correct": false, "explanation": "语义：“远离着湖边走了一圈”前后矛盾，与绕湖走的情境不合。"}, {"text": "抛弃", "is_correct": false, "explanation": "搭配：“抛弃”的对象多为人或物件，不说抛弃湖边。"}], "explanations": {"围绕着": "正确：“围绕着”表示绕着湖边走圈，与“走了一圈”相合。", "离开": "语义：“离开着湖边走了一圈”前后矛盾，离开与绕圈走的情境不合。", "远离": "语义：“远离着湖边走了一圈”前后矛盾，与绕湖走的情境不合。", "抛弃": "搭配：“抛弃”的对象多为人或物件，不说抛弃湖边。"}, "sentence_index": 6, "correct_answer": "围绕着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他围绕着队伍站到了最前面。", "explanation": "这里应该用〈插〉。围绕指绕着某物转圈，站到队伍前面不是绕圈，应说“插到前面”。"}, {"text": "我们围绕车站学会了游泳。", "explanation": "这里应该删去“围绕”，说“我们学会了游泳”。围绕表示绕着某处转，与“学会游泳”无关。"}, {"text": "他围绕公司的目标吃了午饭。", "explanation": "这里应该用〈在〉。围绕表示以某事为中心，不能表示在某地吃饭，应说“在公司吃午饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91135, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小狗围绕的树跑了一圈。", "corrected_sentence": "小狗围绕着树跑了一圈。", "error_description": "错误：“围绕”后的“着”被换成了“的”。“围绕着”中“着”是体标，表示持续的状态；“的”使“围绕”变成定语，句子不通。正确形式是“围绕着树”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91135, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小鸟围绕过大树飞。", "corrected_sentence": "小鸟围绕着大树飞。", "error_description": "错误：“过”表示曾经的经历，此处描述正在进行的动作，应使用“着”。正确形式是“围绕着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
