INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91136, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "环绕；以某事物为中心。", "primary_collocate": null, "pronunciation": "wéi rào", "ipa": "weɪ˧˥ ɻaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "今天的会议围绕环境问题进行。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章围绕一个问题写。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家围绕这个话题讨论了很久。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事围绕一家人的生活展开。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师围绕今天的课文问了几个问题。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书围绕爱情写成。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的讨论围绕工作展开。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的生活都围绕孩子转。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动围绕健康这个主题进行。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者围绕新政策问了很多问题。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "围绕着", "label": "体标"}, {"form": "围绕了", "label": "体标"}, {"form": "围绕过", "label": "体标"}], "register": "中性", "sense_fingerprint": "以某个问题、话题或人物为中心展开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf90865-4d6c-41d7-9be1-67a6da867aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91136, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "围绕", "is_correct": true, "explanation": "正确：围绕表示以环境问题为中心，与“进行”搭配自然。"}, {"text": "远离", "is_correct": false, "explanation": "语义：“会议远离环境问题进行”前后矛盾，与会议以之为主题的情境不合。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“会议反对环境问题进行”说不通，会议不会“反对”某个问题。"}, {"text": "摆脱", "is_correct": false, "explanation": "搭配：“摆脱”后接困境或束缚，不说会议摆脱问题进行。"}], "explanations": {"围绕": "正确：围绕表示以环境问题为中心，与“进行”搭配自然。", "远离": "语义：“会议远离环境问题进行”前后矛盾，与会议以之为主题的情境不合。", "反对": "语义：“会议反对环境问题进行”说不通，会议不会“反对”某个问题。", "摆脱": "搭配：“摆脱”后接困境或束缚，不说会议摆脱问题进行。"}, "sentence_index": 0, "correct_answer": "围绕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们围绕昨天吃了晚饭。", "explanation": "这里应该删去“围绕”。围绕表示以某事为中心，不能用于表示吃饭的时间，应说“我们昨天吃了晚饭”。"}, {"text": "他围绕那个人去了北京。", "explanation": "这里应该用〈陪同〉。围绕表示以某事为中心，不能表示陪着某人去某地。"}, {"text": "他明天围绕上海出发。", "explanation": "这里应该用〈前往〉。围绕表示以某事为中心，不表示朝某地移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91136, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "围绕", "is_correct": true, "explanation": "正确：围绕表示讨论以工作为中心，与“展开”搭配自然。"}, {"text": "无视", "is_correct": false, "explanation": "语义：“讨论无视工作展开”前后矛盾，与讨论以工作为中心的情境不合。"}, {"text": "驾临", "is_correct": false, "explanation": "语域：“驾临”是敬辞，用于贵宾到访，不适合用来描述讨论的内容。"}, {"text": "驱逐", "is_correct": false, "explanation": "搭配：“驱逐”的对象多为人或势力，不说驱逐工作。"}], "explanations": {"围绕": "正确：围绕表示讨论以工作为中心，与“展开”搭配自然。", "无视": "语义：“讨论无视工作展开”前后矛盾，与讨论以工作为中心的情境不合。", "驾临": "语域：“驾临”是敬辞，用于贵宾到访，不适合用来描述讨论的内容。", "驱逐": "搭配：“驱逐”的对象多为人或势力，不说驱逐工作。"}, "sentence_index": 6, "correct_answer": "围绕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他围绕下午去了医院。", "explanation": "这里应该用〈在〉。围绕表示以某事为中心，不能表示在某个时间去某地，应说“下午去了医院”。"}, {"text": "老师围绕学生去参观。", "explanation": "这里应该用〈带领〉。围绕表示以某事为中心，不能表示带着人去做某事。"}, {"text": "他的朋友围绕北京笑了三年。", "explanation": "这里应删去“围绕”。围绕表示以某事为中心，与“笑”搭配不通，应说“他的朋友在北京笑了三年”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个团队的工作围绕的用户需求展开。", "corrected_sentence": "这个团队的工作围绕用户需求展开。", "error_description": "错误：“围绕”后接“的”构成定语，“围绕的用户需求”不成词组。“围绕”作谓语时应直接带宾语，正确形式是“围绕用户需求展开”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下周的会议围绕过环保问题进行。", "corrected_sentence": "下周的会议围绕环保问题进行。", "error_description": "错误：“围绕”后多加了“过”。“过”表示曾经的经历，与“下周”的将来时间不符。正确形式是去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
