INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91139, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "老师或大人要大家去想一想、查一查的一个问题。", "primary_collocate": null, "pronunciation": "kè tí", "ipa": "kʰɤ˥˩ tʰi˧˥", "syllable_count": 2, "sentences": [{"text": "老师给我们一个课题：家乡的变化。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次的课题是了解一种小动物。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我要完成学校的课题。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和同学一起查资料，做这个课题。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这个课题明天要交。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的课题很有意思，我想了很久。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸给孩子出了一个课题：月亮为什么会圆？", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的课题是怎么种花。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们小组的课题是节约用水。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个课题要去图书馆查一查。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "課題", "label": "繁体"}, {"form": "研究课题", "label": "复合"}], "register": "中性", "sense_fingerprint": "老师或大人让大家想一想、查一查的问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2f35b25-018a-4293-9f33-2ac90622ba3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91139, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "课题", "is_correct": true, "explanation": "正确：“老师给我们一个课题”指老师布置让学生思考或查找的题目。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：“礼物”不是老师布置的题目，与冒号后的“家乡的变化”不合。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：“饮料”不是要思考或查找的问题，语境不符。"}, {"text": "手术", "is_correct": false, "explanation": "搭配：“给”不能与“手术”搭配，应说“做手术”。"}], "explanations": {"课题": "正确：“老师给我们一个课题”指老师布置让学生思考或查找的题目。", "礼物": "语义：“礼物”不是老师布置的题目，与冒号后的“家乡的变化”不合。", "饮料": "语义：“饮料”不是要思考或查找的问题，语境不符。", "手术": "搭配：“给”不能与“手术”搭配，应说“做手术”。"}, "sentence_index": 0, "correct_answer": "课题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师今天布置了课题：背课文。", "explanation": "这里应该用〈作业〉。老师布置要学生完成的练习用“作业”，“课题”指要查找或思考的问题。"}, {"text": "老师给我们发了一个课题：明天放假。", "explanation": "这里应该用〈通知〉。发布放假消息用“通知”，“课题”指要想一想、查一查的问题。"}, {"text": "妈妈今天煮了一个课题。", "explanation": "这里应该用〈汤〉。“煮”的对象应是食物，“课题”不能被煮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91139, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课题", "is_correct": true, "explanation": "正确：“出了一个课题”指给孩子提出需要思考的问题，符合语境。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日不是需要思考的问题，与冒号后的问题不符。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“出”不能与“蛋糕”搭配，应说“做蛋糕”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不是可以提出的问题，语境不符。"}], "explanations": {"课题": "正确：“出了一个课题”指给孩子提出需要思考的问题，符合语境。", "生日": "语义：生日不是需要思考的问题，与冒号后的问题不符。", "蛋糕": "搭配：“出”不能与“蛋糕”搭配，应说“做蛋糕”。", "玩具": "语义：玩具不是可以提出的问题，语境不符。"}, "sentence_index": 6, "correct_answer": "课题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师让我们画一个课题：家乡的变化。", "explanation": "这里应该用〈图画〉。“画”的对象应是图画，“课题”不能被画。"}, {"text": "老师在我的作业本上打了一个课题。", "explanation": "这里应该用〈分数〉。在作业本上打的是“分数”，“课题”指要想一想、查一查的问题。"}, {"text": "妈妈给我买了一个课题。", "explanation": "这里应该用〈玩具〉。买来送人的是“玩具”，“课题”指要想一想、查一查的问题，不能买卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91139, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师说，这根课题下周交。", "corrected_sentence": "老师说，这个课题下周交。", "error_description": "量词错误：课题应用“个”或“项”，“根”用于细长的东西。错误形式为“这根课题”，正确形式为“这个课题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91139, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师今天留了一条课题：画一张地图。", "corrected_sentence": "老师今天留了一个课题：画一张地图。", "error_description": "量词错误：课题应用“个”或“项”，“条”用于细长的物品。错误形式为“一条课题”，正确形式为“一个课题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
