INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91140, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "需要研究或解决的问题；研究的题目。", "primary_collocate": null, "pronunciation": "kè tí", "ipa": "kʰɤ˥˩ tʰi˧˥", "syllable_count": 2, "sentences": [{"text": "这个课题我们研究了三年。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的研究课题是环境污染。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她申请到了一个国家级课题。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个值得研究的课题。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的博士课题和人工智能有关。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项课题得到了学校的支持。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境保护是全世界的重要课题。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这个课题，我们需要很多数据。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家们正在讨论下一个研究课题。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老教授一生只做一个课题。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "課題", "label": "繁体"}, {"form": "研究课题", "label": "复合"}], "register": "中性", "sense_fingerprint": "需要研究或解决的问题、研究题目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2f35b25-018a-4293-9f33-2ac90622ba3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91140, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "课题", "is_correct": true, "explanation": "正确：“这个课题”指需要研究的题目，与“研究了三年”搭配。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭不是需要研究的问题，与“研究了三年”不合。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”是纪念出生的日子，不是需要研究解决的问题，与“研究了三年”不合。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不是需要研究的问题，语境不符。"}], "explanations": {"课题": "正确：“这个课题”指需要研究的题目，与“研究了三年”搭配。", "午饭": "语义：午饭不是需要研究的问题，与“研究了三年”不合。", "生日": "语义：“生日”是纪念出生的日子，不是需要研究解决的问题，与“研究了三年”不合。", "蛋糕": "语义：蛋糕不是需要研究的问题，语境不符。"}, "sentence_index": 0, "correct_answer": "课题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晚会上有很多课题。", "explanation": "这里应该用〈节目〉。晚会上表演的是“节目”，“课题”指需要研究解决的问题。"}, {"text": "我们班的课题都很好吃。", "explanation": "这里应该用〈点心〉。“好吃”形容食物，“课题”不能被吃。"}, {"text": "老师今天给我们布置了一杯课题：写一篇日记。", "explanation": "这里应该用〈个〉。“杯”用于盛装液体的容器，不能用来计量“课题”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课题", "is_correct": true, "explanation": "正确：“重要课题”指需要研究解决的问题，与语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：环境保护不是颜色，“重要的颜色”语义不通。"}, {"text": "食物", "is_correct": false, "explanation": "语义：“食物”不是需要研究解决的问题，语境不符。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“重要”不能修饰“感冒”，“重要的感冒”搭配不当。"}], "explanations": {"课题": "正确：“重要课题”指需要研究解决的问题，与语境相符。", "颜色": "语义：环境保护不是颜色，“重要的颜色”语义不通。", "食物": "语义：“食物”不是需要研究解决的问题，语境不符。", "感冒": "搭配：“重要”不能修饰“感冒”，“重要的感冒”搭配不当。"}, "sentence_index": 6, "correct_answer": "课题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这学期我们学习了很多课题。", "explanation": "这里应该用〈课程〉。学习的科目用“课程”，“课题”指研究的题目。"}, {"text": "孩子们在操场上玩一个课题。", "explanation": "这里应该用〈游戏〉。在操场上玩的是“游戏”，“课题”指需要研究解决的问题。"}, {"text": "早餐桌上有很多课题。", "explanation": "这里应该用〈面包〉。早餐桌上摆的是“面包”，“课题”指需要研究解决的问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们小组正在做一个的新课题。", "corrected_sentence": "我们小组正在做一个新课题。", "error_description": "定语错误：“一个”与“新课题”之间不能加“的”，形容词“新”直接修饰名词即可。错误形式为“一个的新课题”，正确形式为“一个新课题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校为他提供了一条课题。", "corrected_sentence": "学校为他提供了一个课题。", "error_description": "量词错误：课题应用“个”或“项”，“条”用于细长的物品。错误形式为“一条课题”，正确形式为“一个课题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
