INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91152, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一国政府发给本国公民出国旅行、证明其身份和国籍的证件。", "primary_collocate": null, "pronunciation": "hù zhào", "ipa": "xu˥˩ ʈʂɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "出国前，我去公安局办了护照。", "target_word": "护照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的护照上有照片和国籍。", "target_word": "护照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关人员请我给他看护照。", "target_word": "护照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本护照是中国政府发的。", "target_word": "护照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的护照下个月就到期了。", "target_word": "护照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的护照放在桌子上。", "target_word": "护照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场工作人员检查了每个人的护照。", "target_word": "护照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外丢了护照，很着急。", "target_word": "护照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办护照需要两张照片。", "target_word": "护照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想换一本新护照。", "target_word": "护照", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "護照", "label": "繁体"}, {"form": "电子护照", "label": "复合"}, {"form": "护照号码", "label": "复合"}], "register": "中性", "sense_fingerprint": "政府发给公民、证明身份和国籍的出国证件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2f35b25-018a-4293-9f33-2ac90622ba3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "护照", "is_correct": true, "explanation": "正确：“办护照”指办理出国用的证件，符合语境。"}, {"text": "病历", "is_correct": false, "explanation": "语义：公安局办理的是出入境证件，不办理病历。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“办”不能与“作业”搭配，应说“做作业”。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“办”不接“蛋糕”，公安局也不办理食品。"}], "explanations": {"护照": "正确：“办护照”指办理出国用的证件，符合语境。", "病历": "语义：公安局办理的是出入境证件，不办理病历。", "作业": "搭配：“办”不能与“作业”搭配，应说“做作业”。", "蛋糕": "搭配：“办”不接“蛋糕”，公安局也不办理食品。"}, "sentence_index": 0, "correct_answer": "护照"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天出门前都用护照开门。", "explanation": "这里应该用〈钥匙〉。开门用钥匙，护照是出入境证件，不能用来开门。"}, {"text": "他在售票处买了一本护照。", "explanation": "这里应该用〈机票〉。售票处卖的是机票，护照是政府发给公民的出入境证件，不能在售票处买。"}, {"text": "开车上路前要带好护照。", "explanation": "这里应该用〈驾照〉。开车要带驾驶证件，护照是出入境证件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "护照", "is_correct": true, "explanation": "正确：机场检查的是出入境证件，“护照”符合语境。"}, {"text": "作文", "is_correct": false, "explanation": "语义：机场工作人员不检查作文，语境不符。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：机场工作人员不检查乐谱，语境不符。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“检查”不与“性格”搭配，应说“了解”性格。"}], "explanations": {"护照": "正确：机场检查的是出入境证件，“护照”符合语境。", "作文": "语义：机场工作人员不检查作文，语境不符。", "乐谱": "语义：机场工作人员不检查乐谱，语境不符。", "性格": "搭配：“检查”不与“性格”搭配，应说“了解”性格。"}, "sentence_index": 6, "correct_answer": "护照"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "报销时要贴护照。", "explanation": "这里应该用〈发票〉。报销要贴发票，护照是出入境证件，不能用来报销。"}, {"text": "上班要戴护照。", "explanation": "这里应该用〈工作证〉。上班佩戴的是工作证，护照是出国证件。"}, {"text": "他发烧了，就用护照量体温。", "explanation": "这里应该用〈体温计〉。量体温要用体温计，护照是出入境证件，不能用来测量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下周去公安局办了护照。", "corrected_sentence": "我下周去公安局办护照。", "error_description": "时态与“了”冲突：“下周”指将来，动词后的“了”表示已完成，不能共现。错误形式为“办了护照”，正确形式为“办护照”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他上个月换了一只新护照。", "corrected_sentence": "他上个月换了一本新护照。", "error_description": "量词错误：“护照”应用量词“本”，“只”用于成对的物品或动物。错误形式为“一只新护照”，正确形式为“一本新护照”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91163, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正面", "is_correct": true, "explanation": "“正面”指事物好的一边，与“负面”相对，是反义词。"}, {"text": "中心", "is_correct": false, "explanation": "“中心”指中间的位置，与“负面”没有反义关系。"}, {"text": "外观", "is_correct": false, "explanation": "“外观”指事物的外部形状，与“负面”没有反义关系。"}, {"text": "声音", "is_correct": false, "explanation": "“声音”指声响，与“负面”没有反义关系。"}], "correct_answer": "正面", "explanations": {"正面": "“正面”指事物好的一边，与“负面”相对，是反义词。", "中心": "“中心”指中间的位置，与“负面”没有反义关系。", "外观": "“外观”指事物的外部形状，与“负面”没有反义关系。", "声音": "“声音”指声响，与“负面”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91163, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正面", "is_correct": true, "explanation": "“正面”指事物好的一边，与“负面”相对，是反义词。"}, {"text": "外观", "is_correct": false, "explanation": "“外观”指事物的外部形状，与“负面”没有反义关系。"}, {"text": "时间", "is_correct": false, "explanation": "“时间”指时段或时刻，与“负面”没有反义关系。"}, {"text": "方向", "is_correct": false, "explanation": "“方向”指所朝的位置，与“负面”没有反义关系。"}], "correct_answer": "正面", "explanations": {"正面": "“正面”指事物好的一边，与“负面”相对，是反义词。", "外观": "“外观”指事物的外部形状，与“负面”没有反义关系。", "时间": "“时间”指时段或时刻，与“负面”没有反义关系。", "方向": "“方向”指所朝的位置，与“负面”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91163, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不好的那一边。", "primary_collocate": null, "pronunciation": "fù miàn", "ipa": "fu˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "每件事都有正面和负面。", "target_word": "负面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能只看事情的负面。", "target_word": "负面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的负面太多，我不想做。", "target_word": "负面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是只看到生活的负面。", "target_word": "负面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机有很多好处，也有负面。", "target_word": "负面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络的负面，老师已经跟我们说过了。", "target_word": "负面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不喜欢谈工作的负面。", "target_word": "负面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要看到问题的正面和负面。", "target_word": "负面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做的负面是花钱太多。", "target_word": "负面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的一面他不说，只说负面。", "target_word": "负面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "负面影响", "label": "复合"}, {"form": "负面情绪", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情不好的一边，与好的一面相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2f35b25-018a-4293-9f33-2ac90622ba3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91163, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "负面", "is_correct": true, "explanation": "“负面”指事物不好的一边，与“正面”相对，可以和“正面”并列说事情的两面。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不能与“正面”并列说事情的两面。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”指声响，不能与“正面”并列说事情的两面。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”说时间长短，不能与“正面”并列描述事情。"}], "explanations": {"负面": "“负面”指事物不好的一边，与“正面”相对，可以和“正面”并列说事情的两面。", "颜色": "语义：“颜色”指色彩，不能与“正面”并列说事情的两面。", "声音": "语义：“声音”指声响，不能与“正面”并列说事情的两面。", "年龄": "搭配：“年龄”说时间长短，不能与“正面”并列描述事情。"}, "sentence_index": 0, "correct_answer": "负面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张纸的负面写着一行字。", "explanation": "这里应该用〈反面〉。“负面”指事情不好的一边，纸张的背面要用“反面”。"}, {"text": "这块木板的负面很光滑。", "explanation": "这里应该用〈底面〉。“负面”指事情不好的一边，木板的底部要用“底面”，不能说“负面”。"}, {"text": "这面墙的负面贴着一张地图。", "explanation": "这里应该用〈背面〉。墙的后面要用“背面”，“负面”指事情不好的一边。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91163, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "负面", "is_correct": true, "explanation": "“负面”指工作不好的一面，可以谈论。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：“眼睛”是器官，不能作“谈”的对象。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“谈工作的尺寸”不搭，“尺寸”不指工作的内容。"}, {"text": "鞋码", "is_correct": false, "explanation": "语义：“鞋码”指鞋的大小，与谈论工作无关。"}], "explanations": {"负面": "“负面”指工作不好的一面，可以谈论。", "眼睛": "语义：“眼睛”是器官，不能作“谈”的对象。", "尺寸": "搭配：“谈工作的尺寸”不搭，“尺寸”不指工作的内容。", "鞋码": "语义：“鞋码”指鞋的大小，与谈论工作无关。"}, "sentence_index": 6, "correct_answer": "负面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这节电池的负面接触不好。", "explanation": "这里应该用〈负极〉。“负面”指不好的一边，电池的负电极要用“负极”，不能说“负面”。"}, {"text": "她背着很重的心理负面，很少笑。", "explanation": "这里应该用〈负担〉。“负面”指不好的一边，心里的压力要用“负担”。"}, {"text": "这栋楼的负面有一扇小门。", "explanation": "这里应该用〈背面〉。楼房的后面要用“背面”，“负面”指不好的一边。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91163, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事有一块负面，我们要注意。", "corrected_sentence": "这件事有一个负面，我们要注意。", "error_description": "“负面”应用量词“个”，不能用“块”。“块”指成块的实物，抽象的“负面”要用“个”，故把“块”改为“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91163, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个方案有一根负面，大家都知道。", "corrected_sentence": "这个方案有一个负面，大家都知道。", "error_description": "“负面”应用量词“个”，不能用“根”。“根”用于细长的东西，应改为“一个负面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
