INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91170, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91170, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "采取措施处理；应付。", "primary_collocate": null, "pronunciation": "duì fu", "ipa": "tweɪ˥˩ fu", "syllable_count": 2, "sentences": [{"text": "这种虫子很多，我们得想办法对付它们。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对大雨，村民们用沙袋对付洪水。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用新办法对付越来越多的投诉。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太冷了，我穿两件毛衣对付严寒。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这种病要用特别的药来对付。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察准备了很多办法对付小偷。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对付电脑病毒，最好每天更新软件。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在田边挖沟，用来对付野猪。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长安排两个人专门对付对方的前锋。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府出了新规定对付空气污染。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对付了", "label": "体标"}, {"form": "对付过", "label": "体标"}, {"form": "对付不了", "label": "复合"}, {"form": "难对付", "label": "复合"}], "register": "口语", "sense_fingerprint": "采取措施去处理或应付问题、灾害、病害等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4849ac9e-2819-4619-bcd7-af3a75ec75c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91170, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指喜爱、赞赏美好的事物，与“虫子很多，要想办法”的处理语境相反。"}, {"text": "对付", "is_correct": true, "explanation": "“对付”指采取措施应对、处理，与“想办法”搭配，符合虫害的语境。"}, {"text": "戒除", "is_correct": false, "explanation": "搭配：“戒除”只用于习惯、毒瘾等，不能用来指虫子。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”指美化、点缀，不是应对有害的虫子。"}], "explanations": {"欣赏": "语义：“欣赏”指喜爱、赞赏美好的事物，与“虫子很多，要想办法”的处理语境相反。", "对付": "“对付”指采取措施应对、处理，与“想办法”搭配，符合虫害的语境。", "戒除": "搭配：“戒除”只用于习惯、毒瘾等，不能用来指虫子。", "装饰": "语义：“装饰”指美化、点缀，不是应对有害的虫子。"}, "sentence_index": 0, "correct_answer": "对付"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师应该平等地对付每一个学生。", "explanation": "这里应该用〈对待〉。“对付”带有应对、对抗的意味，用于难缠的人或事；平等、尊重地看待学生要用“对待”。"}, {"text": "他悉心对付父母，从不抱怨。", "explanation": "这里应该用〈照顾〉。“对付”带有应对、对抗的意味，不能用来形容悉心照料父母；照料家人要用“照顾”。"}, {"text": "老师悠闲地对付窗外的花香。", "explanation": "这里应该用〈欣赏〉。“对付”表示想办法处理难事或应对问题，不能用于悠闲地看待花香；欣赏美景要用“欣赏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91170, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保护", "is_correct": false, "explanation": "语义：“保护”用于守护有价值的事物，不能用来指病毒。"}, {"text": "对付", "is_correct": true, "explanation": "“对付”指采取措施应对病毒，与“最好每天更新软件”的防护语境吻合。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展品，不能用于电脑病毒。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示迎接、接待，与“更新软件”的防护意思不合。"}], "explanations": {"保护": "语义：“保护”用于守护有价值的事物，不能用来指病毒。", "对付": "“对付”指采取措施应对病毒，与“最好每天更新软件”的防护语境吻合。", "参观": "搭配：“参观”的对象是场所或展品，不能用于电脑病毒。", "欢迎": "语义：“欢迎”表示迎接、接待，与“更新软件”的防护意思不合。"}, "sentence_index": 6, "correct_answer": "对付"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们用最好的饭菜对付远道而来的客人。", "explanation": "这里应该用〈招待〉。“对付”含有对抗、应付的意味，不能用来表示热情地款待客人。"}, {"text": "机场里大家热烈对付远方来的朋友。", "explanation": "这里应该用〈迎接〉。“对付”不表示热烈欢迎，迎接远方来的朋友要用“迎接”。"}, {"text": "我们应该对付老师的耐心教导。", "explanation": "这里应该用〈感谢〉。“对付”表示想办法应对难题，不能用来表示对老师耐心教导的感激；表示感谢要用“感谢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们得把想办法对付这些蚊子。", "corrected_sentence": "我们得想办法对付这些蚊子。", "error_description": "错误：多加了“把”。“把”后面应接受事名词，这里直接接动词短语“想办法对付这些蚊子”，句子不通。正确说法是“我们得想办法对付这些蚊子”，不用“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91170, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民们想办法了对付这些害虫。", "corrected_sentence": "农民们想办法对付这些害虫。", "error_description": "错误：“了”放在了动词“对付”之前。“了”只能跟在动词之后或放在句末，这里语序不通。正确说法是“农民们想办法对付这些害虫”，去掉“了”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
