INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91171, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "和钱、做生意有关的事。", "primary_collocate": null, "pronunciation": "cái jīng", "ipa": "tsʰaɪ˧˥ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "爸爸喜欢看财经新闻，想学做生意。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在手机上看了今天的财经消息。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对财经没有兴趣，只想过简单的生活。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "该网站每天刊登大量财经文章。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想买股票的人要多看财经报道。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友在一家财经公司上班。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "财经节目教我们怎样管钱。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本财经书讲了怎么做小生意。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都收听财经广播。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "财经新闻说，今天股票涨了。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "财经新闻", "label": "复合"}], "register": "书面", "sense_fingerprint": "与金钱和生意有关的事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eafbf73-fe6d-4ac7-932f-9a09579e5b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91171, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "财经", "is_correct": true, "explanation": "「财经新闻」指与钱和做生意有关的新闻，与「爸爸喜欢看」的语境相符。"}, {"text": "拖鞋", "is_correct": false, "explanation": "语义：「拖鞋」是一种鞋，不是新闻的内容，与「新闻」冲突。"}, {"text": "牙齿", "is_correct": false, "explanation": "语义：「牙齿」是人身上的器官，不能作为新闻的题材。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：「看……新闻」要求有内容的题材，「石头新闻」不能成立。"}], "explanations": {"财经": "「财经新闻」指与钱和做生意有关的新闻，与「爸爸喜欢看」的语境相符。", "拖鞋": "语义：「拖鞋」是一种鞋，不是新闻的内容，与「新闻」冲突。", "牙齿": "语义：「牙齿」是人身上的器官，不能作为新闻的题材。", "石头": "搭配：「看……新闻」要求有内容的题材，「石头新闻」不能成立。"}, "sentence_index": 0, "correct_answer": "财经"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子是财经做的。", "explanation": "这里应该用〈木头〉。财经指和钱、做生意有关的事，不能作桌子的材料。"}, {"text": "他的朋友是一名财经。", "explanation": "这里应该用〈医生〉。财经指和钱、做生意有关的事，不指人，不能用「一名」来称呼人。"}, {"text": "我每天都弹财经。", "explanation": "这里应该用〈钢琴〉。财经指和钱、做生意有关的事，不能用「弹」作谓语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91171, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "财经", "is_correct": true, "explanation": "「财经节目」指与钱和做生意有关的节目，「教我们怎样管钱」与之相符。"}, {"text": "河流", "is_correct": false, "explanation": "语义：「河流」是自然地理事物，不能作为节目的内容。"}, {"text": "夜空", "is_correct": false, "explanation": "语义：「夜空」指天空，不能教人管钱，与「节目」冲突。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：「节目」的内容要能教人管钱，「眼睛节目」不成立。"}], "explanations": {"财经": "「财经节目」指与钱和做生意有关的节目，「教我们怎样管钱」与之相符。", "河流": "语义：「河流」是自然地理事物，不能作为节目的内容。", "夜空": "语义：「夜空」指天空，不能教人管钱，与「节目」冲突。", "眼睛": "搭配：「节目」的内容要能教人管钱，「眼睛节目」不成立。"}, "sentence_index": 6, "correct_answer": "财经"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的财经比我高。", "explanation": "这里应该用〈身高〉。财经指和钱、做生意有关的事，不能用来比较人的身高。"}, {"text": "这件衣服的财经很好看。", "explanation": "这里应该用〈颜色〉。财经指和钱、做生意有关的事，不能用来形容衣服好看。"}, {"text": "这家店的财经很快就要开了。", "explanation": "这里应该用〈开业〉。财经不能用作动作的对象，不能说店的财经要开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91171, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她每天在手机上看财经很新闻。", "corrected_sentence": "她每天在手机上看财经新闻。", "error_description": "错误：「财经很新闻」，正确：「财经新闻」。「很」是程度副词，不能插在修饰语「财经」和中心词「新闻」之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91171, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他写了一本财经了书。", "corrected_sentence": "他写了一本财经书。", "error_description": "错误：「财经了书」，正确：「财经书」。「了」表示完成，不能插在修饰语「财经」和中心词「书」之间，应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
