INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91176, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "工作中所得的工资、福利等报酬。", "primary_collocate": null, "pronunciation": "dài yù", "ipa": "tai˥˩ y˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司的待遇很好，大家都愿意去。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了工作，因为新公司待遇更高。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的工资待遇这几年提高了不少。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想问一下，这份工作的待遇怎么样？", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给员工的待遇包括吃住和奖金。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然待遇不高，但他很喜欢这份工作。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的待遇比以前好多了。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看中的是这家公司的待遇。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作三年后，他的待遇提高了一倍。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的待遇才能留住好员工。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种待遇", "label": "量词"}, {"form": "福利待遇", "label": "复合"}, {"form": "工资待遇", "label": "复合"}], "register": "中性", "sense_fingerprint": "工作中的工资、福利等报酬", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5eb1fb1c-7db6-4494-864a-ef12b168785b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91176, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "待遇", "is_correct": true, "explanation": "待遇：本题目标词，读作 dài yù，指工资、福利等报酬。"}, {"text": "带鱼", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是带鱼（一种鱼）。"}, {"text": "地域", "is_correct": false, "explanation": "dài（第四声）与 dì（第四声）韵母不同（ai 与 i），意思是地域（区域）。"}, {"text": "待业", "is_correct": false, "explanation": "yù 与 yè 韵母不同，意思是待业（等待就业）。"}], "explanations": {"待遇": "待遇：本题目标词，读作 dài yù，指工资、福利等报酬。", "带鱼": "yù（第四声）与 yú（第二声）声调不同，意思是带鱼（一种鱼）。", "地域": "dài（第四声）与 dì（第四声）韵母不同（ai 与 i），意思是地域（区域）。", "待业": "yù 与 yè 韵母不同，意思是待业（等待就业）。"}, "sentence_index": null, "correct_answer": "待遇"}, "level_3": {"options": [{"text": "待遇", "is_correct": true, "explanation": "待遇：工作的报酬，与“这家公司的……很好”搭配，符合句意。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”说的是人的性格，不说公司的脾气。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材是人的体型，不能说公司的身材。"}, {"text": "表情", "is_correct": false, "explanation": "语义：公司没有表情，“表情很好”与句子的主语矛盾。"}], "explanations": {"待遇": "待遇：工作的报酬，与“这家公司的……很好”搭配，符合句意。", "脾气": "搭配：“脾气”说的是人的性格，不说公司的脾气。", "身材": "体貌：身材是人的体型，不能说公司的身材。", "表情": "语义：公司没有表情，“表情很好”与句子的主语矛盾。"}, "sentence_index": 0, "correct_answer": "待遇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的待遇很高。", "explanation": "这里应该用〈价格〉。待遇指对待方式或工资福利，衣服的价钱要说“价格”。"}, {"text": "这座山的待遇很高。", "explanation": "这里应该用〈海拔〉。待遇不能用来说山的高低，山的高度要说“海拔”。"}, {"text": "这个房间的待遇很新鲜。", "explanation": "这里应该用〈空气〉。待遇不能用来形容房间是否新鲜，房间的清新要说“空气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a6991f3-ea0c-4ae2-bfd6-d019767f2eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "待遇", "is_correct": true, "explanation": "待遇：工作的报酬，与“医生的……比以前好多了”搭配，符合句意。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁不能用“比以前好多了”来形容医生。"}, {"text": "车票", "is_correct": false, "explanation": "语义：车票不能用“比以前好多了”来形容医生。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“比以前好多了”不能用来形容年龄。"}], "explanations": {"待遇": "待遇：工作的报酬，与“医生的……比以前好多了”搭配，符合句意。", "地铁": "语义：地铁不能用“比以前好多了”来形容医生。", "车票": "语义：车票不能用“比以前好多了”来形容医生。", "年龄": "语义：“比以前好多了”不能用来形容年龄。"}, "sentence_index": 6, "correct_answer": "待遇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头的待遇很硬。", "explanation": "这里应该用〈质地〉。待遇是抽象的对待方式，不能用来形容石头的软硬。"}, {"text": "这台电脑的待遇很大。", "explanation": "这里应该用〈内存〉。待遇不能用来形容电脑的容量，容量要说“内存”。"}, {"text": "这把椅子的待遇很红。", "explanation": "这里应该用〈颜色〉。待遇是抽象的对待方式，不能用来说椅子的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a6991f3-ea0c-4ae2-bfd6-d019767f2eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司待遇得很好，我想去。", "corrected_sentence": "这家公司待遇很好，我想去。", "error_description": "错误：名词“待遇”后面不能用“得”引出程度补语。应说“待遇很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a6991f3-ea0c-4ae2-bfd6-d019767f2eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工作三年后，公司提高了他待遇。", "corrected_sentence": "工作三年后，公司提高了他的待遇。", "error_description": "错误：定语“他”与中心词“待遇”之间漏掉了“的”。正确：他的待遇。定语后要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a6991f3-ea0c-4ae2-bfd6-d019767f2eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
