INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91179, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "急是想马上做完，心里很着急。", "primary_collocate": null, "pronunciation": "jí", "ipa": "tɕi³⁵", "syllable_count": 1, "sentences": [{"text": "别急，时间还早，慢慢来。", "target_word": "急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很急，请你快一点。", "target_word": "急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他急得满头是汗。", "target_word": "急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天考试，可他一点也不急。", "target_word": "急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车还没来，我心里很急。", "target_word": "急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子发烧了，妈妈急坏了。", "target_word": "急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他急着去上班，没吃早饭。", "target_word": "急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你急什么，还有十分钟呢。", "target_word": "急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业还没做完，他急得哭了。", "target_word": "急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别急，我马上就到。", "target_word": "急", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "急了", "label": "体标（变化）"}, {"form": "急着", "label": "体标（持续）"}, {"form": "着急", "label": "复合"}, {"form": "急忙", "label": "复合"}], "register": "口语", "sense_fingerprint": "想马上做成某事而心里不安", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5dc62fb-f015-4a98-8321-fde426f86ecf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91179, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "急", "is_correct": true, "explanation": "正确。jí，第二声，意思是想马上做完、心里着急。"}, {"text": "机", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是机器。"}, {"text": "几", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个。"}, {"text": "季", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是季节。"}, {"text": "击", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是打击。"}], "explanations": {"急": "正确。jí，第二声，意思是想马上做完、心里着急。", "机": "jī（第一声）与 jí（第二声）声调不同，意思是机器。", "几": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个。", "季": "jì（第四声）与 jí（第二声）声调不同，意思是季节。", "击": "jī（第一声）与 jí（第二声）声调不同，意思是打击。"}, "sentence_index": null, "correct_answer": "急"}, "level_3": {"options": [{"text": "急", "is_correct": true, "explanation": "正确。「别急」表示劝对方不要着急，与「时间还早，慢慢来」相呼应。"}, {"text": "慢", "is_correct": false, "explanation": "语义：「别慢」与后句「慢慢来」的劝说意思相矛盾。"}, {"text": "早", "is_correct": false, "explanation": "语义：「别早」不合句意，且与「时间还早」重复。"}, {"text": "甜", "is_correct": false, "explanation": "语义：「别甜」不成句，与「时间还早，慢慢来」无法相配。"}], "explanations": {"急": "正确。「别急」表示劝对方不要着急，与「时间还早，慢慢来」相呼应。", "慢": "语义：「别慢」与后句「慢慢来」的劝说意思相矛盾。", "早": "语义：「别早」不合句意，且与「时间还早」重复。", "甜": "语义：「别甜」不成句，与「时间还早，慢慢来」无法相配。"}, "sentence_index": 0, "correct_answer": "急"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他听到好消息，急得笑个不停。", "explanation": "这里是把〈急〉当成「高兴」来用，但〈急〉表示焦急，不能形容笑个不停的开心；这里应该用〈高兴〉。"}, {"text": "这块布很急，一拉就破。", "explanation": "这里〈急〉不能形容布料，「一拉就破」应该用〈脆〉。"}, {"text": "妈妈看着窗外的雪，急得很温柔。", "explanation": "这里是把〈急〉用来形容平和的神态，但〈急〉表示焦急，两者矛盾；这里应该用〈温和〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91179, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "急", "is_correct": true, "explanation": "正确。jí，第二声，意思是想马上做完、心里着急。"}, {"text": "记", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是记住。"}, {"text": "寄", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是寄送。"}, {"text": "既", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是既然。"}, {"text": "计", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是计划。"}], "explanations": {"急": "正确。jí，第二声，意思是想马上做完、心里着急。", "记": "jì（第四声）与 jí（第二声）声调不同，意思是记住。", "寄": "jì（第四声）与 jí（第二声）声调不同，意思是寄送。", "既": "jì（第四声）与 jí（第二声）声调不同，意思是既然。", "计": "jì（第四声）与 jí（第二声）声调不同，意思是计划。"}, "sentence_index": null, "correct_answer": "急"}, "level_3": {"options": [{"text": "急", "is_correct": true, "explanation": "正确。「急着去上班」表示赶着做某事，与「没吃早饭」的匆忙一致。"}, {"text": "亮", "is_correct": false, "explanation": "语义：「亮」不能修饰去上班的动作，「亮着去上班」句意不通。"}, {"text": "圆", "is_correct": false, "explanation": "语义：「圆」不能修饰去上班的动作，「圆着去上班」句意不通。"}, {"text": "胖", "is_correct": false, "explanation": "搭配：「胖着去上班」不成说法，「胖」不用于这种动作状态。"}], "explanations": {"急": "正确。「急着去上班」表示赶着做某事，与「没吃早饭」的匆忙一致。", "亮": "语义：「亮」不能修饰去上班的动作，「亮着去上班」句意不通。", "圆": "语义：「圆」不能修饰去上班的动作，「圆着去上班」句意不通。", "胖": "搭配：「胖着去上班」不成说法，「胖」不用于这种动作状态。"}, "sentence_index": 6, "correct_answer": "急"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一点也不着急，却急得在沙发上看电视。", "explanation": "这里〈急〉表示心里焦急，与前面毫不慌张的说法矛盾；应该用〈悠闲〉。"}, {"text": "他饿了一整天，急得慢慢地吃着饭。", "explanation": "这里〈急〉表示心里焦急，与后面吃饭的样子矛盾；应该用〈从容〉。"}, {"text": "他躺在床上睡得很香，却急得直打哈欠。", "explanation": "这里〈急〉表示焦急，与前面的睡眠状态矛盾；应该用〈困倦〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91179, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他急不知道怎么办。", "corrected_sentence": "他急得不知道怎么办。", "error_description": "错误：「急」后缺少补语标记「得」。正确：应说「急得……」，表示程度的补语要用「得」连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91179, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他急出门，忘了带钥匙。", "corrected_sentence": "他急着出门，忘了带钥匙。", "error_description": "错误：「急」后漏掉表示持续状态的「着」。正确：应说「急着出门」，「着」表示一边着急一边做某事。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91180, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "慢", "is_correct": true, "explanation": "正确。「慢」与「急」在「速度快」的义项上互为反义。"}, {"text": "懒", "is_correct": false, "explanation": "与「急」的速度义项无反义关系，「懒」指不愿做事。"}, {"text": "高兴", "is_correct": false, "explanation": "与「急」的速度义项无关，「高兴」指心情愉快。"}, {"text": "安静", "is_correct": false, "explanation": "与「急」的速度义项无关，「安静」指没有声音或不吵闹。"}], "correct_answer": "慢", "explanations": {"慢": "正确。「慢」与「急」在「速度快」的义项上互为反义。", "懒": "与「急」的速度义项无反义关系，「懒」指不愿做事。", "高兴": "与「急」的速度义项无关，「高兴」指心情愉快。", "安静": "与「急」的速度义项无关，「安静」指没有声音或不吵闹。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
