INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91180, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "着急；急迫；速度快。", "primary_collocate": null, "pronunciation": "jí", "ipa": "tɕi³⁵", "syllable_count": 1, "sentences": [{"text": "河水很急，孩子不要靠近。", "target_word": "急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一听这个消息，急得直跺脚。", "target_word": "急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下得很急，我们躲进了店里。", "target_word": "急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走得很急，连帽子都掉了。", "target_word": "急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事很急，今天必须做完。", "target_word": "急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话太急，我没听清楚。", "target_word": "急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的水流急，不能游泳。", "target_word": "急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病来得很急，要马上去医院。", "target_word": "急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈听到消息，急得一夜没睡。", "target_word": "急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师等得很急，一直看着手表。", "target_word": "急", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "急了", "label": "体标（变化）"}, {"form": "着急", "label": "复合"}, {"form": "急忙", "label": "复合"}], "register": "口语", "sense_fingerprint": "着急、急迫，或水流风雨等速度很快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5dc62fb-f015-4a98-8321-fde426f86ecf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91180, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "急", "is_correct": true, "explanation": "正确。jí，第二声，意思是速度快或猛烈。"}, {"text": "鸡", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是鸡。"}, {"text": "寂", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是寂静。"}, {"text": "技", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是技能。"}], "explanations": {"急": "正确。jí，第二声，意思是速度快或猛烈。", "鸡": "jī（第一声）与 jí（第二声）声调不同，意思是鸡。", "寂": "jì（第四声）与 jí（第二声）声调不同，意思是寂静。", "技": "jì（第四声）与 jí（第二声）声调不同，意思是技能。"}, "sentence_index": null, "correct_answer": "急"}, "level_3": {"options": [{"text": "急", "is_correct": true, "explanation": "正确。水流湍急，表示速度快，与「不要靠近」的危险语境一致。"}, {"text": "甜", "is_correct": false, "explanation": "语义：水不说甜，「河水很甜」与句意不合。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：水不能说硬，「河水很硬」不成说法。"}, {"text": "薄", "is_correct": false, "explanation": "搭配：水不说薄，「河水很薄」不符合习惯说法。"}], "explanations": {"急": "正确。水流湍急，表示速度快，与「不要靠近」的危险语境一致。", "甜": "语义：水不说甜，「河水很甜」与句意不合。", "硬": "搭配：水不能说硬，「河水很硬」不成说法。", "薄": "搭配：水不说薄，「河水很薄」不符合习惯说法。"}, "sentence_index": 0, "correct_answer": "急"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的成绩进步很急，一个学期就从第十名升到第一名。", "explanation": "这里应该用〈快〉。「进步」这类变化说「快」，「急」多指心里着急或情况紧迫。"}, {"text": "这碗汤很急，喝得我直流汗。", "explanation": "这里〈急〉不能形容汤的温度，应该用〈烫〉。"}, {"text": "这头牛很急，一天能走三十里。", "explanation": "这里〈急〉用来形容牛的速度不够自然；说动物走得快一般用〈快〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91180, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "急", "is_correct": true, "explanation": "正确。jí，第二声，意思是速度快或猛烈。"}, {"text": "己", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是自己。"}, {"text": "击", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是打击。"}, {"text": "忌", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是忌讳。"}], "explanations": {"急": "正确。jí，第二声，意思是速度快或猛烈。", "己": "jǐ（第三声）与 jí（第二声）声调不同，意思是自己。", "击": "jī（第一声）与 jí（第二声）声调不同，意思是打击。", "忌": "jì（第四声）与 jí（第二声）声调不同，意思是忌讳。"}, "sentence_index": null, "correct_answer": "急"}, "level_3": {"options": [{"text": "急", "is_correct": true, "explanation": "正确。「水流急」说明水流湍急，与「不能游泳」的语境一致。"}, {"text": "亮", "is_correct": false, "explanation": "语义：「水流亮」不合句意，与「不能游泳」无关。"}, {"text": "圆", "is_correct": false, "explanation": "搭配：水流不说圆，「水流圆」不成说法。"}, {"text": "短", "is_correct": false, "explanation": "语义：「水流短」不合句意，水流不用长短来描述。"}], "explanations": {"急": "正确。「水流急」说明水流湍急，与「不能游泳」的语境一致。", "亮": "语义：「水流亮」不合句意，与「不能游泳」无关。", "圆": "搭配：水流不说圆，「水流圆」不成说法。", "短": "语义：「水流短」不合句意，水流不用长短来描述。"}, "sentence_index": 6, "correct_answer": "急"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块手表很急，一天总是快十分钟。", "explanation": "〈急〉用于说人的着急或事情的紧迫，不用来描述钟表的走时；这里的错误在于把「急」用到了钟表上。"}, {"text": "这杯茶很急，喝一口就烫嘴。", "explanation": "这里〈急〉不能形容茶的温度，应该用〈烫〉。"}, {"text": "这张桌子很急，一推就倒。", "explanation": "这里〈急〉不能用来形容桌子，应该用〈晃〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跑很急，连鞋都跑掉了。", "corrected_sentence": "他跑得很急，连鞋都跑掉了。", "error_description": "错误：「跑」后缺少补语标记「得」。正确：应说「跑得很急」，表示程度的补语要用「得」连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈急满头大汗。", "corrected_sentence": "妈妈急得满头大汗。", "error_description": "错误：「急」后漏掉补语标记「得」。正确：应说「急得满头大汗」，「得」连接表示程度的补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
