INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91198, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "工厂中悬挂在高处移动、用来吊运重物的起重机。", "primary_collocate": null, "pronunciation": "tiān chē", "ipa": "tʰjɛn˥ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "工人开着天车，把钢板吊了起来。", "target_word": "天车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车间里的天车正在搬一个大机器。", "target_word": "天车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天车挂在车间的高处。", "target_word": "天车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台天车能吊起二十吨重的东西。", "target_word": "天车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是工厂里开天车的师傅。", "target_word": "天车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天车坏了，工人们只好停工。", "target_word": "天车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天车慢慢地把钢管送到了另一头。", "target_word": "天车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅每天都要检查天车。", "target_word": "天车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新买的天车让工厂的工作快了很多。", "target_word": "天车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天车的钢绳上挂着一块大铁板。", "target_word": "天车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}], "register": "中性", "sense_fingerprint": "天车：工厂高处移动的吊运起重机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e70502b-b805-4b8c-a302-573ca6cc38cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91198, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天车", "is_correct": true, "explanation": "天车：工厂高处可移动的吊运起重机，正好符合“开着”且能“吊起钢板”。"}, {"text": "出租车", "is_correct": false, "explanation": "语义：出租车是载客的车，不能在高处吊起钢板。"}, {"text": "自行车", "is_correct": false, "explanation": "搭配：自行车要说“骑”，不说“开着”。"}, {"text": "火车", "is_correct": false, "explanation": "语义：火车在铁路上运送旅客或货物，不会把钢板吊起来。"}], "explanations": {"天车": "天车：工厂高处可移动的吊运起重机，正好符合“开着”且能“吊起钢板”。", "出租车": "语义：出租车是载客的车，不能在高处吊起钢板。", "自行车": "搭配：自行车要说“骑”，不说“开着”。", "火车": "语义：火车在铁路上运送旅客或货物，不会把钢板吊起来。"}, "sentence_index": 0, "correct_answer": "天车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们车间新买了一条天车。", "explanation": "这里应该用〈台〉。天车是机器，量词用“台”；“条”用于细长的东西，不用于机器。"}, {"text": "工地上的天车把水泥板吊到了楼顶。", "explanation": "这里应该用〈吊车〉。天车固定在工厂高处的轨道上，不在工地上移动，工地上要用吊车。"}, {"text": "仓库里的天车把货箱叉到了货架上。", "explanation": "这里应该用〈叉车〉。天车悬挂在高处、沿轨道吊运，不能像叉车那样用货叉从地面叉起货物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91198, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天车", "is_correct": true, "explanation": "天车：可在高处移动、吊运钢管的起重机，能把钢管送到另一头。"}, {"text": "时钟", "is_correct": false, "explanation": "语义：时钟只能显示时间，不能慢慢地搬运钢管。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不能把钢管送到另一头。"}, {"text": "雨伞", "is_correct": false, "explanation": "配价：“送”的主语需要能移动物体，雨伞不能自己把钢管送出去。"}], "explanations": {"天车": "天车：可在高处移动、吊运钢管的起重机，能把钢管送到另一头。", "时钟": "语义：时钟只能显示时间，不能慢慢地搬运钢管。", "钢琴": "语义：钢琴是乐器，不能把钢管送到另一头。", "雨伞": "配价：“送”的主语需要能移动物体，雨伞不能自己把钢管送出去。"}, "sentence_index": 6, "correct_answer": "天车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂的天车把成品送到了三楼。", "explanation": "这里应该用〈货梯〉。天车只能在车间高处沿轨道横向吊运，不能把货物送上楼层。"}, {"text": "山上的天车载着游客往上走。", "explanation": "这里应该用〈缆车〉。天车是工厂里吊运货物的起重机，不载人，也不在山上运行。"}, {"text": "天车把我们送到了十楼。", "explanation": "这里应该用〈电梯〉。天车只吊运货物，不能载人上楼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91198, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们车间里有一只天车。", "corrected_sentence": "我们车间里有一台天车。", "error_description": "“一只天车”错误，应为“一台天车”。天车是机器，量词用“台”，不用动物量词“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91198, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前开了过天车，所以很熟悉这种机器。", "corrected_sentence": "他以前开过天车，所以很熟悉这种机器。", "error_description": "“开了过天车”错误，应为“开过天车”。“了”和“过”不能同时用在同一个动词后，表示有过经历只用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
