INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91200, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "支援；帮助。", "primary_collocate": null, "pronunciation": "yuán zhù", "ipa": "yɛn˧˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "北京派了医生去援助西部的医院。", "target_word": "援助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家一直援助邻国修路。", "target_word": "援助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多企业援助了这个地区一百万元。", "target_word": "援助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家愿意援助我们修学校。", "target_word": "援助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "富裕的地区要援助贫困的地区。", "target_word": "援助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们援助过非洲的几个国家。", "target_word": "援助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东部的省份来援助西部的地区。", "target_word": "援助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济上有困难，政府会援助你们。", "target_word": "援助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多亏邻国援助我们，这个地区才度过了难关。", "target_word": "援助", "complexity_tier": "T3", "furigana": "yuán zhù", "sentence_source": "generated"}, {"text": "两个城市互相援助，一起度过了难关。", "target_word": "援助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "援助了", "label": "体标"}, {"form": "援助过", "label": "体标"}, {"form": "经济援助", "label": "复合"}], "register": "书面", "sense_fingerprint": "国家、组织或地区之间的支援与帮助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5eb1fb1c-7db6-4494-864a-ef12b168785b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91200, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "援助", "is_correct": true, "explanation": "援助（yuán zhù）：国家或组织之间的支援与帮助。"}, {"text": "圆珠", "is_correct": false, "explanation": "声调：圆珠（yuánzhū）与援助（yuán zhù）第二个音节声调不同（第一声与第四声），意思是圆珠（笔）。"}, {"text": "原主", "is_correct": false, "explanation": "声调：原主（yuánzhǔ）与援助（yuán zhù）第二个音节声调不同（第三声与第四声），意思是原来的主人。"}, {"text": "园主", "is_correct": false, "explanation": "声调：园主（yuánzhǔ）与援助（yuán zhù）第二个音节声调不同，意思是园子的主人。"}, {"text": "元素", "is_correct": false, "explanation": "声母：元素（yuánsù）与援助（yuán zhù）第二个音节声母不同（s 与 zh），意思是元素。"}], "explanations": {"援助": "援助（yuán zhù）：国家或组织之间的支援与帮助。", "圆珠": "声调：圆珠（yuánzhū）与援助（yuán zhù）第二个音节声调不同（第一声与第四声），意思是圆珠（笔）。", "原主": "声调：原主（yuánzhǔ）与援助（yuán zhù）第二个音节声调不同（第三声与第四声），意思是原来的主人。", "园主": "声调：园主（yuánzhǔ）与援助（yuán zhù）第二个音节声调不同，意思是园子的主人。", "元素": "声母：元素（yuánsù）与援助（yuán zhù）第二个音节声母不同（s 与 zh），意思是元素。"}, "sentence_index": null, "correct_answer": "援助"}, "level_3": {"options": [{"text": "援助", "is_correct": true, "explanation": "援助：派医生去帮助西部的医院，与“派医生去”的语境相合。"}, {"text": "收购", "is_correct": false, "explanation": "语义：“收购”是买下，派医生去收购医院不合常理，与医疗支援的语境不符。"}, {"text": "驱逐", "is_correct": false, "explanation": "语义：“驱逐”是赶走，派医生去驱逐医院说不通。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”要求人作宾语，不能说欢迎医院。"}], "explanations": {"援助": "援助：派医生去帮助西部的医院，与“派医生去”的语境相合。", "收购": "语义：“收购”是买下，派医生去收购医院不合常理，与医疗支援的语境不符。", "驱逐": "语义：“驱逐”是赶走，派医生去驱逐医院说不通。", "欢迎": "搭配：“欢迎”要求人作宾语，不能说欢迎医院。"}, "sentence_index": 0, "correct_answer": "援助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那家外国公司援助了这个赚钱的工厂。", "explanation": "这里应该用〈投资〉。援助是给有困难一方的帮助，已经赚钱的工厂不需要援助，出资做生意要说投资。"}, {"text": "他们一直援助我的计划。", "explanation": "这里应该用〈支持〉。援助指向有困难的地区或组织提供实际帮助，不用于计划这类抽象事物。"}, {"text": "那家公司援助了一场音乐会。", "explanation": "这里应该用〈赞助〉。援助的对象是有困难的人或地区，对音乐会等活动出资要说赞助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a6991f3-ea0c-4ae2-bfd6-d019767f2eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91200, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "援助", "is_correct": true, "explanation": "援助（yuán zhù）：国家或组织之间的支援与帮助。"}, {"text": "原剧", "is_correct": false, "explanation": "声母：原剧（yuánjù）与援助（yuán zhù）第二个音节声母不同（j 与 zh），意思是原创的戏剧。"}, {"text": "原序", "is_correct": false, "explanation": "声母：原序（yuánxù）与援助（yuán zhù）第二个音节声母不同（x 与 zh），意思是书前的序言。"}, {"text": "园路", "is_correct": false, "explanation": "声母：园路（yuánlù）与援助（yuán zhù）第二个音节声母不同（l 与 zh），意思是园中的小路。"}], "explanations": {"援助": "援助（yuán zhù）：国家或组织之间的支援与帮助。", "原剧": "声母：原剧（yuánjù）与援助（yuán zhù）第二个音节声母不同（j 与 zh），意思是原创的戏剧。", "原序": "声母：原序（yuánxù）与援助（yuán zhù）第二个音节声母不同（x 与 zh），意思是书前的序言。", "园路": "声母：园路（yuánlù）与援助（yuán zhù）第二个音节声母不同（l 与 zh），意思是园中的小路。"}, "sentence_index": null, "correct_answer": "援助"}, "level_3": {"options": [{"text": "援助", "is_correct": true, "explanation": "援助：地区之间的相互支援，与“东部的省份来”的语境相合。"}, {"text": "遗弃", "is_correct": false, "explanation": "语义：“遗弃”是抛下不管，与省份之间相互支援的语境相反。"}, {"text": "解雇", "is_correct": false, "explanation": "搭配：“解雇”的对象是员工，地区不能被解雇。"}, {"text": "毕业", "is_correct": false, "explanation": "配价：“毕业”是不及物动词，不能带人作宾语。"}], "explanations": {"援助": "援助：地区之间的相互支援，与“东部的省份来”的语境相合。", "遗弃": "语义：“遗弃”是抛下不管，与省份之间相互支援的语境相反。", "解雇": "搭配：“解雇”的对象是员工，地区不能被解雇。", "毕业": "配价：“毕业”是不及物动词，不能带人作宾语。"}, "sentence_index": 6, "correct_answer": "援助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师援助我复习了功课。", "explanation": "这里应该用〈辅导〉。援助多指对有困难的一方给予物资或实际支援，老师教功课要说辅导。"}, {"text": "奶奶援助我买了一台电脑。", "explanation": "这里应该用〈资助〉。援助多用于对群体或地区的帮扶，个人出钱供人买东西要说资助。"}, {"text": "她援助了那个刚考满分的学生。", "explanation": "这里应该用〈表扬〉。援助是给有困难一方的帮助，考满分的学生不需要援助，应说表扬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a6991f3-ea0c-4ae2-bfd6-d019767f2eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个组织从不援助过边远地区的学校。", "corrected_sentence": "这个组织从没援助过边远地区的学校。", "error_description": "错误：从不……过。正确：从没……过。表示过去从未有过的经历要用“没”，“不”用于习惯性的否定。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a6991f3-ea0c-4ae2-bfd6-d019767f2eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "邻近的城市常常被援助有困难的城市。", "corrected_sentence": "邻近的城市常常援助有困难的城市。", "error_description": "错误：“援助”前加了“被”，却保留了宾语“有困难的城市”，“被”字句不能带宾语。正确：援助有困难的城市。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a6991f3-ea0c-4ae2-bfd6-d019767f2eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
