INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91219, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "职工是在公司或工厂里工作的人。", "primary_collocate": null, "pronunciation": "zhí gōng", "ipa": "ʈʂɻ̩˧˥ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "这家工厂的职工每天早上七点上班。", "target_word": "职工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司职工可以免费坐班车。", "target_word": "职工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一家玩具厂的职工。", "target_word": "职工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班后，职工们一起走出工厂。", "target_word": "职工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板给职工涨了工资。", "target_word": "职工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公司只有十名职工。", "target_word": "职工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的职工在车间里认真工作。", "target_word": "职工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女职工中午可以休息一个小时。", "target_word": "职工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过节的时候，公司请职工吃饭。", "target_word": "职工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这家工厂当了十年职工。", "target_word": "职工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "職工", "label": "繁体"}, {"form": "名", "label": "量词"}, {"form": "女职工", "label": "复合"}, {"form": "老职工", "label": "复合"}], "register": "中性", "sense_fingerprint": "在公司或工厂里工作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a13f3c-7d80-4a9a-8407-2021ae5c1faf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91219, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "职工", "is_correct": true, "explanation": "zhí gōng 指在公司或工厂里工作的人。"}, {"text": "织工", "is_correct": false, "explanation": "zhī（第一声）与 zhí（第二声）声调不同，意思是织布的工人。"}, {"text": "石工", "is_correct": false, "explanation": "shí 与 zhí 声母 sh/zh 不同，意思是石匠。"}, {"text": "纸工", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是从事纸制品制作的工人。"}, {"text": "日工", "is_correct": false, "explanation": "rì 与 zhí 声母不同（r 与 zh），意思是按日计酬的工人。"}], "explanations": {"职工": "zhí gōng 指在公司或工厂里工作的人。", "织工": "zhī（第一声）与 zhí（第二声）声调不同，意思是织布的工人。", "石工": "shí 与 zhí 声母 sh/zh 不同，意思是石匠。", "纸工": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是从事纸制品制作的工人。", "日工": "rì 与 zhí 声母不同（r 与 zh），意思是按日计酬的工人。"}, "sentence_index": null, "correct_answer": "职工"}, "level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：学生在学校学习，不在这家工厂上班，与“上班”冲突。"}, {"text": "职工", "is_correct": true, "explanation": "正确：指在这家工厂工作、每天上班的人。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是来参观的人，不在工厂上班，与“上班”冲突。"}, {"text": "孩子", "is_correct": false, "explanation": "体貌：孩子指未成年人，与“每天早上七点上班”的成年劳动者不符。"}], "explanations": {"学生": "语义：学生在学校学习，不在这家工厂上班，与“上班”冲突。", "职工": "正确：指在这家工厂工作、每天上班的人。", "游客": "语义：游客是来参观的人，不在工厂上班，与“上班”冲突。", "孩子": "体貌：孩子指未成年人，与“每天早上七点上班”的成年劳动者不符。"}, "sentence_index": 0, "correct_answer": "职工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们厂新来了一台职工，干活很快。", "explanation": "这里量词用错：职工指人，要用〈名〉；〈台〉用于机器等物品，不能用来数职工。"}, {"text": "他是一名职工，专门在街上偷别人的钱包。", "explanation": "这里应该用〈小偷〉。职工指在公司或工厂工作的人，偷钱包的不是职工。"}, {"text": "职工们在街角给人算命，收点小钱。", "explanation": "这里应该用〈算命先生〉。职工指在公司或工厂工作的人，街角给人算命的不是职工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91219, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "职工", "is_correct": true, "explanation": "zhí gōng 指在公司或工厂里工作的人。"}, {"text": "机工", "is_correct": false, "explanation": "jī（第一声）与 zhí 声母不同（j 与 zh），意思是机械工人。"}, {"text": "志工", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）声调不同，意思是志愿服务的人。"}, {"text": "时工", "is_correct": false, "explanation": "shí 与 zhí 声母不同，意思是临时工。"}, {"text": "日工", "is_correct": false, "explanation": "rì 与 zhí 声母不同，意思是按日计酬的工人。"}], "explanations": {"职工": "zhí gōng 指在公司或工厂里工作的人。", "机工": "jī（第一声）与 zhí 声母不同（j 与 zh），意思是机械工人。", "志工": "zhì（第四声）与 zhí（第二声）声调不同，意思是志愿服务的人。", "时工": "shí 与 zhí 声母不同，意思是临时工。", "日工": "rì 与 zhí 声母不同，意思是按日计酬的工人。"}, "sentence_index": null, "correct_answer": "职工"}, "level_3": {"options": [{"text": "病人", "is_correct": false, "explanation": "语义：病人在医院接受治疗，不在车间工作，与“车间里”冲突。"}, {"text": "职工", "is_correct": true, "explanation": "正确：指在工厂车间里工作的人。"}, {"text": "婴儿", "is_correct": false, "explanation": "体貌：婴儿年幼，不能在车间里认真工作，与“认真工作”冲突。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众是来看演出的人，不在车间工作，与“车间里”冲突。"}], "explanations": {"病人": "语义：病人在医院接受治疗，不在车间工作，与“车间里”冲突。", "职工": "正确：指在工厂车间里工作的人。", "婴儿": "体貌：婴儿年幼，不能在车间里认真工作，与“认真工作”冲突。", "观众": "语义：观众是来看演出的人，不在车间工作，与“车间里”冲突。"}, "sentence_index": 6, "correct_answer": "职工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "职工放学后回家写作业。", "explanation": "这里应该用〈学生〉。职工是在单位工作的人，放学写作业的是学生。"}, {"text": "职工每天驾船抢劫过往商船。", "explanation": "这里应该用〈海盗〉。职工指在公司或工厂工作的人，驾船抢劫的是海盗。"}, {"text": "职工每天在车站门口向路人乞讨。", "explanation": "这里应该用〈乞丐〉。职工指在公司或工厂工作的人，向路人乞讨的是乞丐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91219, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂有五十只职工在夜班工作。", "corrected_sentence": "这家工厂有五十名职工在夜班工作。", "error_description": "量词错误：“职工”指人，应用量词“名”；“只”不能用来数人。正确说法：这家工厂有五十名职工在夜班工作。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91219, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每个职工们都要按时到岗。", "corrected_sentence": "每个职工都要按时到岗。", "error_description": "复数标记错误：“每个”表示逐一，与“们”不能同用。正确说法：每个职工都要按时到岗。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
