INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91220, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机关、企业等单位的工作人员。", "primary_collocate": null, "pronunciation": "zhí gōng", "ipa": "ʈʂɻ̩˧˥ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "这家工厂有两百多名职工。", "target_word": "职工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给全体职工发了新年礼物。", "target_word": "职工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的职工食堂中午十一点开门。", "target_word": "职工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "单位每年请职工做一次体检。", "target_word": "职工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸是这个单位的老职工。", "target_word": "职工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每位职工都有一张工作卡。", "target_word": "职工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂里的职工宿舍离车站很近。", "target_word": "职工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的职工要先学习安全知识。", "target_word": "职工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，职工的意见很重要。", "target_word": "职工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个单位的职工大多住在附近。", "target_word": "职工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "職工", "label": "繁体"}, {"form": "名", "label": "量词"}, {"form": "女职工", "label": "复合"}, {"form": "老职工", "label": "复合"}], "register": "中性", "sense_fingerprint": "机关企业等单位的工作人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a13f3c-7d80-4a9a-8407-2021ae5c1faf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91220, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "职工", "is_correct": true, "explanation": "zhí gōng 指在机关、企业等单位工作的人。"}, {"text": "织工", "is_correct": false, "explanation": "zhī（第一声）与 zhí（第二声）声调不同，意思是织布的工人。"}, {"text": "石工", "is_correct": false, "explanation": "shí 与 zhí 声母 sh/zh 不同，意思是石匠。"}, {"text": "纸工", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是从事纸制品制作的工人。"}, {"text": "日工", "is_correct": false, "explanation": "rì 与 zhí 声母不同（r 与 zh），意思是按日计酬的工人。"}], "explanations": {"职工": "zhí gōng 指在机关、企业等单位工作的人。", "织工": "zhī（第一声）与 zhí（第二声）声调不同，意思是织布的工人。", "石工": "shí 与 zhí 声母 sh/zh 不同，意思是石匠。", "纸工": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是从事纸制品制作的工人。", "日工": "rì 与 zhí 声母不同（r 与 zh），意思是按日计酬的工人。"}, "sentence_index": null, "correct_answer": "职工"}, "level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：学生在学校读书，不在这家工厂工作，与“这家工厂”冲突。"}, {"text": "职工", "is_correct": true, "explanation": "正确：指在这家工厂工作的人，与“两百多名”搭配。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民在田间务农，不在这家工厂，与“这家工厂”冲突。"}, {"text": "士兵", "is_correct": false, "explanation": "语义：士兵在军营服役，不在工厂工作，与“这家工厂”冲突。"}], "explanations": {"学生": "语义：学生在学校读书，不在这家工厂工作，与“这家工厂”冲突。", "职工": "正确：指在这家工厂工作的人，与“两百多名”搭配。", "农民": "语义：农民在田间务农，不在这家工厂，与“这家工厂”冲突。", "士兵": "语义：士兵在军营服役，不在工厂工作，与“这家工厂”冲突。"}, "sentence_index": 0, "correct_answer": "职工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个单位有一只职工很努力。", "explanation": "这里量词用错：职工指人，要用〈名〉；〈只〉多用于动物，不能用来数职工。"}, {"text": "班里的职工每天背着书包去上学。", "explanation": "这里应该用〈学生〉。职工指在单位工作的人，背着书包去上学的是学生。"}, {"text": "他是一名职工，专门在路边给人算命。", "explanation": "这里应该用〈算命先生〉。职工指在单位工作、领工资的人，路边给人算命的不是职工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91220, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "职工", "is_correct": true, "explanation": "zhí gōng 指在机关、企业等单位工作的人。"}, {"text": "机工", "is_correct": false, "explanation": "jī（第一声）与 zhí 声母不同（j 与 zh），意思是机械工人。"}, {"text": "志工", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）声调不同，意思是志愿服务的人。"}, {"text": "时工", "is_correct": false, "explanation": "shí 与 zhí 声母不同，意思是临时工。"}, {"text": "日工", "is_correct": false, "explanation": "rì 与 zhí 声母不同，意思是按日计酬的工人。"}], "explanations": {"职工": "zhí gōng 指在机关、企业等单位工作的人。", "机工": "jī（第一声）与 zhí 声母不同（j 与 zh），意思是机械工人。", "志工": "zhì（第四声）与 zhí（第二声）声调不同，意思是志愿服务的人。", "时工": "shí 与 zhí 声母不同，意思是临时工。", "日工": "rì 与 zhí 声母不同，意思是按日计酬的工人。"}, "sentence_index": null, "correct_answer": "职工"}, "level_3": {"options": [{"text": "士兵", "is_correct": false, "explanation": "语义：士兵住在军营，不住工厂的宿舍，与“厂里的”冲突。"}, {"text": "职工", "is_correct": true, "explanation": "正确：指在工厂工作的人，职工宿舍是单位为职工提供的住处。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是坐车的人，不住宿舍，与“宿舍”冲突。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是来参观的人，不住工厂宿舍，与“宿舍”冲突。"}], "explanations": {"士兵": "语义：士兵住在军营，不住工厂的宿舍，与“厂里的”冲突。", "职工": "正确：指在工厂工作的人，职工宿舍是单位为职工提供的住处。", "乘客": "语义：乘客是坐车的人，不住宿舍，与“宿舍”冲突。", "游客": "语义：游客是来参观的人，不住工厂宿舍，与“宿舍”冲突。"}, "sentence_index": 6, "correct_answer": "职工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "职工每天在街上偷别人的钱包。", "explanation": "这里应该用〈小偷〉。职工指在单位工作的人，偷钱包的不是职工。"}, {"text": "职工每天在车站门口向路人乞讨。", "explanation": "这里应该用〈乞丐〉。职工指在单位工作的人，在车站乞讨的不是职工。"}, {"text": "职工每天驾船抢劫过往商船。", "explanation": "这里应该用〈海盗〉。职工指在单位工作的人，驾船抢劫商船的是海盗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个厂有三只职工受了伤。", "corrected_sentence": "这个厂有三名职工受了伤。", "error_description": "量词错误：“职工”指人，应用量词“名”，不能用“只”。正确说法：这个厂有三名职工受了伤。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每位职工们都要带工作证。", "corrected_sentence": "每位职工都要带工作证。", "error_description": "复数标记错误：“每位”已表示每一个，后面不能再加“们”。正确说法：每位职工都要带工作证。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
