INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91229, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "舆论是很多人对一件事的想法和话。", "primary_collocate": null, "pronunciation": "yú lùn", "ipa": "y˧˥ lwən˥˩", "syllable_count": 2, "sentences": [{"text": "网上的舆论都支持他。", "target_word": "舆论", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家饭店的事，在网上引起了舆论。", "target_word": "舆论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "舆论都说他做得对，没有人怪他。", "target_word": "舆论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他怕舆论，所以不敢说真话。", "target_word": "舆论", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师的做法得到了舆论的支持。", "target_word": "舆论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "舆论对这个决定看法不一。", "target_word": "舆论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者想听听舆论是怎么说的。", "target_word": "舆论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上的舆论都在批评这家公司。", "target_word": "舆论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面对舆论，他一直没有回答。", "target_word": "舆论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的新闻可以影响舆论。", "target_word": "舆论", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "輿論", "label": "繁体"}], "register": "书面", "sense_fingerprint": "舆论：很多人对某件事的想法和议论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5eb1fb1c-7db6-4494-864a-ef12b168785b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91229, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "舆论", "is_correct": true, "explanation": "正确。“舆论”指很多人的看法，可以“支持”某人，符合“网上的舆论都支持他”。"}, {"text": "账户", "is_correct": false, "explanation": "语义：账户是财务记录，不能“支持”某人。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“人数”说的是数量，不能充当“支持”的主语，应说“人数增加”。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，没有“支持”人的意思。"}], "explanations": {"舆论": "正确。“舆论”指很多人的看法，可以“支持”某人，符合“网上的舆论都支持他”。", "账户": "语义：账户是财务记录，不能“支持”某人。", "人数": "搭配：“人数”说的是数量，不能充当“支持”的主语，应说“人数增加”。", "钥匙": "语义：钥匙是开锁的工具，没有“支持”人的意思。"}, "sentence_index": 0, "correct_answer": "舆论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他写了一篇舆论，发在报纸上。", "explanation": "这里应该用〈评论〉。“舆论”是公众的共同看法，不是个人写的文章，应说“评论”。"}, {"text": "他和舆论握了握手，所以不敢说真话。", "explanation": "这里应该用〈公众〉。“舆论”是众人的看法，不是人，不能握手。"}, {"text": "他在会上发表了一番舆论。", "explanation": "这里应该用〈言论〉。“舆论”是众人的共同看法，不能由一个人“发表”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a6991f3-ea0c-4ae2-bfd6-d019767f2eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91229, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "舆论", "is_correct": true, "explanation": "正确。“舆论”是可以“说”的看法，符合“记者想听听舆论是怎么说的”。"}, {"text": "气温", "is_correct": false, "explanation": "语义：气温是温度，不会“说”什么。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通工具，没有“说”的内容。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“数量”是多少的概念，不能表达观点，应与“统计”搭配。"}], "explanations": {"舆论": "正确。“舆论”是可以“说”的看法，符合“记者想听听舆论是怎么说的”。", "气温": "语义：气温是温度，不会“说”什么。", "地铁": "语义：地铁是交通工具，没有“说”的内容。", "数量": "搭配：“数量”是多少的概念，不能表达观点，应与“统计”搭配。"}, "sentence_index": 6, "correct_answer": "舆论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "好的新闻可以改变我个人的舆论。", "explanation": "这里应该用〈看法〉。“舆论”指众人的共同看法，不能说成“我个人的”。"}, {"text": "好的新闻可以证明我的舆论是对的。", "explanation": "这里应该用〈看法〉。“舆论”指众人的共同看法，不能说成“我的”个人看法。"}, {"text": "好的新闻可以把舆论讲成一个故事。", "explanation": "这里应该用〈报道〉。“舆论”是众人的看法，不是可以讲成故事的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a6991f3-ea0c-4ae2-bfd6-d019767f2eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91229, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事引起了一只很大的舆论。", "corrected_sentence": "这件事引起了很大的舆论。", "error_description": "量词错误：“只”用于动物或单个的东西，不能修饰“舆论”。应去掉“一只”，说“引起了很大的舆论”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a6991f3-ea0c-4ae2-bfd6-d019767f2eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91229, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次采访引起了舆论们。", "corrected_sentence": "这次采访引起了舆论。", "error_description": "“们”只加在指人的名词后，“舆论”是抽象名词，不能说“舆论们”，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a6991f3-ea0c-4ae2-bfd6-d019767f2eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
