INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91234, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一周的末尾，通常指星期六和星期日。", "primary_collocate": null, "pronunciation": "zhōu mò", "ipa": "ʈʂoʊ˥ mwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "周末商店里的人特别多。", "target_word": "周末", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们周末去看电影，好吗？", "target_word": "周末", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每个周末都去爬山。", "target_word": "周末", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末就是星期六和星期日。", "target_word": "周末", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个周末我要加班，不能陪你了。", "target_word": "周末", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末的路上车很多，我们坐地铁吧。", "target_word": "周末", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸周末喜欢在家看书。", "target_word": "周末", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一周工作五天，周末休息两天。", "target_word": "周末", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末快到了，大家都很高兴。", "target_word": "周末", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们约好这个周末见面。", "target_word": "周末", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "週末", "label": "繁体"}], "register": "中性", "sense_fingerprint": "周末：一周的末尾，通常指星期六和星期日", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5eb1fb1c-7db6-4494-864a-ef12b168785b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91234, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "周末", "is_correct": true, "explanation": "正确。“周末”指一周末尾的星期六和星期日，可以说“周末商店里的人特别多”。"}, {"text": "凌晨", "is_correct": false, "explanation": "语义：凌晨商店一般人很少，与“人特别多”矛盾。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：午夜时分商店大多已经关门，不会“人特别多”。"}, {"text": "深夜", "is_correct": false, "explanation": "语义：深夜多数商店已经打烊，与“人特别多”矛盾。"}], "explanations": {"周末": "正确。“周末”指一周末尾的星期六和星期日，可以说“周末商店里的人特别多”。", "凌晨": "语义：凌晨商店一般人很少，与“人特别多”矛盾。", "午夜": "语义：午夜时分商店大多已经关门，不会“人特别多”。", "深夜": "语义：深夜多数商店已经打烊，与“人特别多”矛盾。"}, "sentence_index": 0, "correct_answer": "周末"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛的周末最精彩。", "explanation": "这里应该用〈结尾〉。“周末”指一周的最后两天，不能指比赛的结尾。"}, {"text": "他把周末借给了朋友。", "explanation": "这里应该用〈时间〉。“周末”是一段时间，不能像物品一样借给别人。"}, {"text": "周末是一周的开始。", "explanation": "这里应该用〈周一〉。“周末”指一周的最后两天，不能说成一周的开始。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a6991f3-ea0c-4ae2-bfd6-d019767f2eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91234, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "周末", "is_correct": true, "explanation": "正确。“一周工作五天，周末休息两天”中，“周末”指一周末尾的两天休息时间，与句意相合。"}, {"text": "周一", "is_correct": false, "explanation": "语义：周一只是一天，不能“休息两天”。"}, {"text": "平日", "is_correct": false, "explanation": "语义：平日指工作日，与“工作五天，休息两天”的对比矛盾。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：午夜是一个时刻，不是两天的时段。"}], "explanations": {"周末": "正确。“一周工作五天，周末休息两天”中，“周末”指一周末尾的两天休息时间，与句意相合。", "周一": "语义：周一只是一天，不能“休息两天”。", "平日": "语义：平日指工作日，与“工作五天，休息两天”的对比矛盾。", "午夜": "语义：午夜是一个时刻，不是两天的时段。"}, "sentence_index": 6, "correct_answer": "周末"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部小说的周末写得很精彩。", "explanation": "这里应该用〈结尾〉。“周末”指一周的最后两天，不能指作品的结尾。"}, {"text": "我们坐在周末上聊天。", "explanation": "这里应该用〈椅子〉之类的具体物品。“周末”是时间，不能当作椅子来坐。"}, {"text": "我的爱好是周末。", "explanation": "这里应该用〈活动〉。“爱好”指经常做的具体事情，“周末”是时间段，不能作“爱好”的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a6991f3-ea0c-4ae2-bfd6-d019767f2eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91234, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们周末的去打球吧。", "corrected_sentence": "我们周末去打球吧。", "error_description": "结构错误：“周末”作时间状语，后面不加“的”，应说“周末去打球”；“周末的”不能直接修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a6991f3-ea0c-4ae2-bfd6-d019767f2eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91234, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在山上度过了一只周末。", "corrected_sentence": "我们在山上度过了一个周末。", "error_description": "量词错误：“周末”应用量词“个”。“只”用于动物或单个小物件，不能修饰“周末”，应改为“一个周末”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a6991f3-ea0c-4ae2-bfd6-d019767f2eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
