INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91238, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用车船等把货物从一地送到另一地。", "primary_collocate": null, "pronunciation": "yùn", "ipa": "yn˥˩", "syllable_count": 1, "sentences": [{"text": "这些苹果要用大卡车运到城里。", "target_word": "运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把一箱箱的水果运上了船。", "target_word": "运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天开车去港口运货。", "target_word": "运", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这批家具明天才能运到我家。", "target_word": "运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们用小船把米运过河。", "target_word": "运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把旧书运回老家去。", "target_word": "运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么重的东西，一个人运不了。", "target_word": "运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的路很窄，大车运不进去。", "target_word": "运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用马车运了三天的粮食。", "target_word": "运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些药要从北京运到西部的小村子。", "target_word": "运", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "運", "label": "繁体"}, {"form": "运了", "label": "体标（完成）"}, {"form": "运过", "label": "体标（经历）"}, {"form": "运输", "label": "复合"}], "register": "中性", "sense_fingerprint": "运：用车船等把货物从一地送到另一地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '476a3295-ccc1-45f7-ab1b-c537dc3fa42a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91238, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "运", "is_correct": true, "explanation": "正确。运（yùn）指用车船等把货物从一地送到另一地。"}, {"text": "云", "is_correct": false, "explanation": "云（yún）与运（yùn）声调不同，意思是云彩。"}, {"text": "允", "is_correct": false, "explanation": "允（yǔn）与运（yùn）声调不同，意思是允许、同意。"}, {"text": "验", "is_correct": false, "explanation": "验（yàn）与运（yùn）声调相同，但韵母不同（an 与 un），意思是检验。"}, {"text": "印", "is_correct": false, "explanation": "印（yìn）与运（yùn）声调相同，但韵母不同（in 与 un），意思是印刷、印记。"}], "explanations": {"运": "正确。运（yùn）指用车船等把货物从一地送到另一地。", "云": "云（yún）与运（yùn）声调不同，意思是云彩。", "允": "允（yǔn）与运（yùn）声调不同，意思是允许、同意。", "验": "验（yàn）与运（yùn）声调相同，但韵母不同（an 与 un），意思是检验。", "印": "印（yìn）与运（yùn）声调相同，但韵母不同（in 与 un），意思是印刷、印记。"}, "sentence_index": null, "correct_answer": "运"}, "level_3": {"options": [{"text": "运", "is_correct": true, "explanation": "正确。“用大卡车运到城里”表示用车把苹果送到城里，符合句意。"}, {"text": "寄", "is_correct": false, "explanation": "搭配：“寄”指通过邮递送信件或包裹，不能说“用大卡车寄到城里”。"}, {"text": "游", "is_correct": false, "explanation": "配价：“游”是不及物动词，不能带“苹果”作宾语，句子不成立。"}, {"text": "养", "is_correct": false, "explanation": "语义：“养”指培育、饲养，不表示把苹果送往某地，与“到城里”不搭。"}], "explanations": {"运": "正确。“用大卡车运到城里”表示用车把苹果送到城里，符合句意。", "寄": "搭配：“寄”指通过邮递送信件或包裹，不能说“用大卡车寄到城里”。", "游": "配价：“游”是不及物动词，不能带“苹果”作宾语，句子不成立。", "养": "语义：“养”指培育、饲养，不表示把苹果送往某地，与“到城里”不搭。"}, "sentence_index": 0, "correct_answer": "运"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这束花运给妈妈。", "explanation": "这里应该用〈送〉。运多指大批货物的运输，送花给人要用“送”。"}, {"text": "他把家运到了新城市。", "explanation": "这里应该用〈搬〉。运指货物的运送，整个家迁居要用“搬”。"}, {"text": "他运着一只小猫回家。", "explanation": "这里应该用〈抱〉。运用于大批货物，抱一只小猫回家要用“抱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91238, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "运", "is_correct": true, "explanation": "正确。运（yùn）指把货物从一地送到另一地。"}, {"text": "陨", "is_correct": false, "explanation": "陨（yǔn）与运（yùn）声调不同，意思是坠落、陨落。"}, {"text": "匀", "is_correct": false, "explanation": "匀（yún）与运（yùn）声调不同，意思是均匀。"}, {"text": "玉", "is_correct": false, "explanation": "玉（yù）与运（yùn）只差韵尾 n，意思是玉石。"}], "explanations": {"运": "正确。运（yùn）指把货物从一地送到另一地。", "陨": "陨（yǔn）与运（yùn）声调不同，意思是坠落、陨落。", "匀": "匀（yún）与运（yùn）声调不同，意思是均匀。", "玉": "玉（yù）与运（yùn）只差韵尾 n，意思是玉石。"}, "sentence_index": null, "correct_answer": "运"}, "level_3": {"options": [{"text": "运", "is_correct": true, "explanation": "正确。“一个人运不了”指一个人搬运不动，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能与“这么重的东西”搭配。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写文字，与搬动重物无关，句子不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声歌唱，与搬动重物无关，句子不通。"}], "explanations": {"运": "正确。“一个人运不了”指一个人搬运不动，符合句意。", "吃": "搭配：“吃”的对象是食物，不能与“这么重的东西”搭配。", "写": "语义：“写”指书写文字，与搬动重物无关，句子不通。", "唱": "语义：“唱”指发声歌唱，与搬动重物无关，句子不通。"}, "sentence_index": 6, "correct_answer": "运"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师运着一本词典去教室。", "explanation": "这里应该用〈拿〉。运指成批货物的搬运，拿一本词典去教室要用“拿”。"}, {"text": "我运着一只小狗去公园散步。", "explanation": "这里应该用〈牵〉。运多用于成批货物或牲畜的运输，牵着一只小狗去散步要用“牵”。"}, {"text": "小女孩运着一个书包去学校。", "explanation": "这里应该用〈背〉。书包背在身上要用“背”，运多指成批货物的运送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch