INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91240, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "敬辞，称对方的见解。", "primary_collocate": null, "pronunciation": "gāo jiàn", "ipa": "kɑʊ˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "您的高见让我很受启发。", "target_word": "高见", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请问您对这件事有什么高见？", "target_word": "高见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听了您的高见，我明白了很多。", "target_word": "高见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "关于这个计划，不知道您有什么高见。", "target_word": "高见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "各位有何高见，请尽管说。", "target_word": "高见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "您的高见得到了大家的赞同。", "target_word": "高见", "complexity_tier": "T3", "furigana": "gāo jiàn", "sentence_source": "generated"}, {"text": "老师，您对我的作文有什么高见？", "target_word": "高见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理，您的高见很有道理，我们照着做吧。", "target_word": "高见", "complexity_tier": "T3", "furigana": "gāo jiàn", "sentence_source": "generated"}, {"text": "这个问题，还望您不吝高见。", "target_word": "高见", "complexity_tier": "T3", "furigana": "gāo jiàn", "sentence_source": "generated"}, {"text": "您的高见我会认真考虑的。", "target_word": "高见", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "敬辞，尊称对方的意见或看法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: 吝 (Zipf 1.57)']::text[], 'e2c74ad2-a0ce-4c65-9079-a2c0132d354e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91240, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高见", "is_correct": true, "explanation": "敬辞，称对方的见解，与“您的”搭配，表示对方高明的意见让我受到启发。"}, {"text": "愚见", "is_correct": false, "explanation": "语义：“愚见”是谦称自己的见解，与“您的”指对方的意见相矛盾。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指身体的高矮，不是意见，不能让人受到启发。"}, {"text": "容貌", "is_correct": false, "explanation": "体貌：“容貌”指外表，与“启发”搭配不当，句意不通。"}], "explanations": {"高见": "敬辞，称对方的见解，与“您的”搭配，表示对方高明的意见让我受到启发。", "愚见": "语义：“愚见”是谦称自己的见解，与“您的”指对方的意见相矛盾。", "身高": "语义：“身高”指身体的高矮，不是意见，不能让人受到启发。", "容貌": "体貌：“容貌”指外表，与“启发”搭配不当，句意不通。"}, "sentence_index": 0, "correct_answer": "高见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的高见是这个计划可以再等一等。", "explanation": "这里应该用〈拙见〉。高见是敬辞，只用来称对方的见解，说自己的看法要用谦辞“拙见”。"}, {"text": "我想给您提一个高见，请您参考。", "explanation": "这里应该用〈建议〉。高见指对方的见解，自己提出想法时不能用这个敬辞。"}, {"text": "他花钱买了高见，放在书架上。", "explanation": "这里应该用〈礼物〉。高见是抽象的见解，不是可以花钱买、放在书架上的实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91240, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高见", "is_correct": true, "explanation": "敬辞，称对方的见解，与“老师”和“您”相合，表示请对方指教。"}, {"text": "废话", "is_correct": false, "explanation": "语域：“废话”含贬义，与对老师的尊敬语境不符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是意见，无法用来指作文的看法。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”说的是钱数，不能用来评价作文。"}], "explanations": {"高见": "敬辞，称对方的见解，与“老师”和“您”相合，表示请对方指教。", "废话": "语域：“废话”含贬义，与对老师的尊敬语境不符。", "天气": "语义：“天气”不是意见，无法用来指作文的看法。", "价格": "搭配：“价格”说的是钱数，不能用来评价作文。"}, "sentence_index": 6, "correct_answer": "高见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的高见很清楚，我们很快就会改进。", "explanation": "这里应该用〈思路〉。高见是敬辞，指人的见解，机器没有见解，不能这样用。"}, {"text": "他的高见很脏，别让孩子碰。", "explanation": "这里应该用〈衣服〉。高见是抽象的意见，不能用“脏”来形容。"}, {"text": "那只猫的高见很响，把大家都吵醒了。", "explanation": "这里应该用〈叫声〉。高见是人的见解，不能用“响”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对这个问题提出了一只高见。", "corrected_sentence": "他对这个问题提出了一番高见。", "error_description": "量词错误：“高见”是别人的见解，应用“番”计量，说“一番高见”；“只”用于动物，不能修饰“高见”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "关于这次活动，您有一座高见吗？", "corrected_sentence": "关于这次活动，您有什么高见吗？", "error_description": "量词错误：“高见”是抽象的见解，不能用“座”计量（“座”用于山、桥、房屋等大型固定物）；此处应说“有什么高见”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
