INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91245, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手指或鼠标一碰，把它打开。", "primary_collocate": null, "pronunciation": "diǎn kāi", "ipa": "tjɛn˨˩˦ kʰaɪ̯˥", "syllable_count": 2, "sentences": [{"text": "用手指一碰，就能点开这个软件。", "target_word": "点开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我点开微信，看到妈妈发来的话。", "target_word": "点开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她轻轻点开了桌面上的图标。", "target_word": "点开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你点开屏幕上的小红点。", "target_word": "点开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他点开网页，找到了那张地图。", "target_word": "点开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用手指点开了动画片。", "target_word": "点开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把这个文件点开，里面是空的。", "target_word": "点开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个附件点开以后，会出现一张表格。", "target_word": "点开", "complexity_tier": "T3", "furigana": "zhè gè fù jiàn diǎn kāi yǐ hòu huì chū xiàn yī zhāng biǎo gé。", "sentence_source": "generated"}, {"text": "点开这条短信，你就知道答案。", "target_word": "点开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他点开过这个软件，但是不会用。", "target_word": "点开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "点开了", "label": "体标"}, {"form": "点开过", "label": "体标"}, {"form": "點開", "label": "繁体"}], "register": "口语", "sense_fingerprint": "用手指或鼠标一碰就把软件、网页等打开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2f35b25-018a-4293-9f33-2ac90622ba3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91245, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喂", "is_correct": false, "explanation": "语义：“喂”的对象是人或动物，不能用于软件。"}, {"text": "点开", "is_correct": true, "explanation": "点开：用手指一碰就把软件打开，符合句意。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车、船等交通工具，不能说驾驶软件。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”是人或动物在水中的动作，与软件无关。"}], "explanations": {"喂": "语义：“喂”的对象是人或动物，不能用于软件。", "点开": "点开：用手指一碰就把软件打开，符合句意。", "驾驶": "搭配：“驾驶”的对象是车、船等交通工具，不能说驾驶软件。", "游": "语义：“游”是人或动物在水中的动作，与软件无关。"}, "sentence_index": 0, "correct_answer": "点开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她点开了那个包裹。", "explanation": "这里应该用〈拆开〉。拆包裹是打开外层包装，点开只用于屏幕上的软件、网页等。"}, {"text": "他点开了饼干袋，吃了一块。", "explanation": "这里应该用〈撕开〉。撕开饼干袋是用手扯破包装，点开只用于屏幕上的对象。"}, {"text": "我点开了那根绳子，想看看里面有什么。", "explanation": "这里应该用〈解开〉。解开绳子是把结松开，点开只用于屏幕上的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91245, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打扮", "is_correct": false, "explanation": "语义：“打扮”指修饰人的外表，不能用于文件。"}, {"text": "点开", "is_correct": true, "explanation": "点开：用鼠标或手指打开文件，符合“里面是空的”的句意。"}, {"text": "吹", "is_correct": false, "explanation": "搭配：“吹”的对象多是风、灰尘、口哨等，不能说吹文件。"}, {"text": "膜拜", "is_correct": false, "explanation": "语域：“膜拜”是书面的崇敬用语，与日常操作文件的口语句子不协调。"}], "explanations": {"打扮": "语义：“打扮”指修饰人的外表，不能用于文件。", "点开": "点开：用鼠标或手指打开文件，符合“里面是空的”的句意。", "吹": "搭配：“吹”的对象多是风、灰尘、口哨等，不能说吹文件。", "膜拜": "语域：“膜拜”是书面的崇敬用语，与日常操作文件的口语句子不协调。"}, "sentence_index": 6, "correct_answer": "点开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他点开了一个坏习惯。", "explanation": "这里用“点开”表示“养成”，但“点开”只指一碰即打开屏幕上的软件、网页等，不能表示养成习惯。"}, {"text": "妈妈点开了那个箱子，拿出了毛衣。", "explanation": "这里应该用〈打开〉。打开箱子是掀起箱盖取物，点开只用于屏幕上的软件、网页等。"}, {"text": "她点开了那片海。", "explanation": "这里应该用〈望〉。“望”指朝远处看，点开只用于屏幕上的软件、网页等，不能用于大海等自然景物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91245, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我轻轻一碰，就点开开了那个视频。", "corrected_sentence": "我轻轻一碰，就点开了那个视频。", "error_description": "错误在于补语“开”被重复写成“点开开”。“点开”已是动补结构，“开”不能再加一次，正确形式是“点开了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91245, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈昨晚点开开了那个网页。", "corrected_sentence": "妈妈昨晚点开了那个网页。", "error_description": "错误在于补语“开”被重复写成“点开开”。“点开”已是动补结构，“开”不能再加一次，正确形式是“点开了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
