INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91246, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手指或鼠标点击，使其打开。", "primary_collocate": null, "pronunciation": "diǎn kāi", "ipa": "tjɛn˨˩˦ kʰaɪ̯˥", "syllable_count": 2, "sentences": [{"text": "他用鼠标点开了那个文件。", "target_word": "点开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请点开这个链接看看。", "target_word": "点开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我点开邮件，里面是一张照片。", "target_word": "点开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机上的新消息，我还没点开。", "target_word": "点开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她点开视频，声音很大。", "target_word": "点开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你点开设置，就能改名字。", "target_word": "点开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不敢点开陌生人发的链接。", "target_word": "点开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他点开过那个网站，没有买东西。", "target_word": "点开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师点开了今天要看的课件。", "target_word": "点开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈教我点开手机里的地图。", "target_word": "点开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "点开了", "label": "体标"}, {"form": "点开过", "label": "体标"}, {"form": "點開", "label": "繁体"}], "register": "口语", "sense_fingerprint": "用手指或鼠标点击使文件、链接等打开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2f35b25-018a-4293-9f33-2ac90622ba3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91246, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象应是可以吃的东西，不能说吃文件。"}, {"text": "点开", "is_correct": true, "explanation": "点开：用鼠标点击使文件打开，符合句意。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指使物体着火，用在文件上不合逻辑，也与“用鼠标”的操作不符。"}, {"text": "点亮", "is_correct": false, "explanation": "搭配：“点亮”多用于灯、屏幕等，不能说点亮文件。"}], "explanations": {"吃": "语义：“吃”的对象应是可以吃的东西，不能说吃文件。", "点开": "点开：用鼠标点击使文件打开，符合句意。", "点燃": "语义：“点燃”指使物体着火，用在文件上不合逻辑，也与“用鼠标”的操作不符。", "点亮": "搭配：“点亮”多用于灯、屏幕等，不能说点亮文件。"}, "sentence_index": 0, "correct_answer": "点开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把门点开了，你进来吧。", "explanation": "这里应该用〈打开〉。点开只用于屏幕上的文件、链接等，门要用打开。"}, {"text": "他点开了那个抽屉，拿出了一把钥匙。", "explanation": "这里应该用〈拉开〉。拉抽屉是把它拉出来，点开只用于屏幕上的软件、文件等。"}, {"text": "她点开了锅盖，香味飘了出来。", "explanation": "这里应该用〈掀开〉。掀锅盖是把盖子抬起，点开只用于屏幕上的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拥抱", "is_correct": false, "explanation": "语义：“拥抱”的对象应是人，链接无法被拥抱。"}, {"text": "瞻仰", "is_correct": false, "explanation": "语域：“瞻仰”是书面的敬仰用语，与这句日常口语的表达不协调。"}, {"text": "点开", "is_correct": true, "explanation": "点开：用手指或鼠标点击使链接打开，符合句意。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车、船等交通工具，不能说驾驶链接。"}], "explanations": {"拥抱": "语义：“拥抱”的对象应是人，链接无法被拥抱。", "瞻仰": "语域：“瞻仰”是书面的敬仰用语，与这句日常口语的表达不协调。", "点开": "点开：用手指或鼠标点击使链接打开，符合句意。", "驾驶": "搭配：“驾驶”的对象是车、船等交通工具，不能说驾驶链接。"}, "sentence_index": 6, "correct_answer": "点开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈点开了一个好主意。", "explanation": "这里把“点开”当作“想出”来用，但“点开”只指用手指或鼠标点击屏幕上的对象使其打开，不能表示想出某个念头。"}, {"text": "我点开了那个柜子，拿出了几件衣服。", "explanation": "这里应该用〈打开〉。打开柜子是把柜门开启取物，点开只用于屏幕上的对象。"}, {"text": "我点开了那片天空，看了很久。", "explanation": "这里应该用〈望〉。“望”指朝远处看，点开只用于屏幕上的对象，不能用于天空等自然景物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在电脑上没点开了那个压缩包。", "corrected_sentence": "我在电脑上点开了那个压缩包。", "error_description": "否定与“了”冲突：“没”用于否定已发生的动作时不与“了”共现，应说“没点开”或“点开了”。错误形式为“没点开了”，正确形式为“点开了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板昨晚把点开了那个报表。", "corrected_sentence": "老板昨晚点开了那个报表。", "error_description": "错误在于“把”字句的结构：“把”后应为“把+宾语+动词+了”（如“把那个报表点开了”），此句把动词“点开”直接放在“把”后、宾语之前，不成立。去掉“把”即为正确形式：“点开了那个报表”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c7d398c-7af4-4a55-987f-49f50d59ae9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
