INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91251, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91251, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "排成一条线的字，或者排成一条线的人。", "primary_collocate": null, "pronunciation": "yì háng", "ipa": "i˥˩ xɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "学生们站成一行。", "target_word": "一行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们排成一行，等着上车。", "target_word": "一行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了一行字。", "target_word": "一行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路很窄，大家只能排成一行走。", "target_word": "一行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这封信只有一行字，很短。", "target_word": "一行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "运动员在起跑线后站成一行。", "target_word": "一行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把自己的名字写成一行小字。", "target_word": "一行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们坐成一行，听老师讲故事。", "target_word": "一行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙上有一行红色的大字。", "target_word": "一行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小朋友们手拉着手，站成一行。", "target_word": "一行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一行行", "label": "重叠"}], "register": "中性", "sense_fingerprint": "一行：排成一条线的字或人，如站成一行、写一行字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2beb4a87-1356-4fca-8f26-67e841f14fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91251, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一行", "is_correct": true, "explanation": "“一行”指排成一条线的学生，与“站成”搭配，符合题意。"}, {"text": "一杯", "is_correct": false, "explanation": "语义：“杯”指盛水等液体的器具，学生不能站成一杯。"}, {"text": "一本", "is_correct": false, "explanation": "搭配：“本”用于书册，不能用来计量排队站立的学生。"}, {"text": "一朵", "is_correct": false, "explanation": "语义：“朵”用于花，学生不是花，不能站成一朵。"}], "explanations": {"一行": "“一行”指排成一条线的学生，与“站成”搭配，符合题意。", "一杯": "语义：“杯”指盛水等液体的器具，学生不能站成一杯。", "一本": "搭配：“本”用于书册，不能用来计量排队站立的学生。", "一朵": "语义：“朵”用于花，学生不是花，不能站成一朵。"}, "sentence_index": 0, "correct_answer": "一行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从口袋里掏出了一行钞票。", "explanation": "这里应该用〈一沓〉。“一行”只用来计量排成线的字或人，成叠的钞票要用“一沓”。"}, {"text": "他骑上一行自行车去上学。", "explanation": "这里应该用〈一辆〉。“一行”只用来计量排成线的字或人，自行车要用“一辆”。"}, {"text": "我家养了一行狗。", "explanation": "这里应该用〈一只〉。“一行”只用来计量排成线的字或人，不能用来计量动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91251, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一行", "is_correct": true, "explanation": "“一行小字”指排成一条线的字，与“写成”搭配，符合题意。"}, {"text": "一碗", "is_correct": false, "explanation": "语义：“碗”是盛饭的器皿，名字不能写成一碗小字。"}, {"text": "一座", "is_correct": false, "explanation": "搭配：“座”用于山、楼等大型物体，不能用来计量小字。"}, {"text": "一棵", "is_correct": false, "explanation": "语义：“棵”用于植物，字不能算作一棵。"}], "explanations": {"一行": "“一行小字”指排成一条线的字，与“写成”搭配，符合题意。", "一碗": "语义：“碗”是盛饭的器皿，名字不能写成一碗小字。", "一座": "搭配：“座”用于山、楼等大型物体，不能用来计量小字。", "一棵": "语义：“棵”用于植物，字不能算作一棵。"}, "sentence_index": 6, "correct_answer": "一行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他只说了一行话，大家都笑了。", "explanation": "这里应该用〈一句〉。“一行”指排成一条线的字或人，说出的话要用“一句”。"}, {"text": "这首歌里有一行动听的旋律。", "explanation": "这里应该用〈一段〉。“一行”只能指排成线的字或人，旋律要用“一段”。"}, {"text": "他一口气喝掉了一行牛奶。", "explanation": "这里应该用〈一杯〉。“一行”只用来计量排成线的字或人，牛奶要用“一杯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91251, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墙上写着一行个醒目的标语。", "corrected_sentence": "墙上写着一行醒目的标语。", "error_description": "量词错误：“一行”已含量词，后面不能再加“个”，应说“一行醒目的标语”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91251, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "乘客们在站台上排成一个行。", "corrected_sentence": "乘客们在站台上排成一行。", "error_description": "量词错误：“行”前多加了“个”，应说“排成一行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
