INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91252, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91252, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一条横排；指文字或事物排成的一条线。", "primary_collocate": null, "pronunciation": "yì háng", "ipa": "i˥˩ xɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "雪地上留下了一行脚印。", "target_word": "一行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他只改了一行代码，程序就能用了。", "target_word": "一行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路边种着一行高高的杨树。", "target_word": "一行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑板上写着一行大字：欢迎回家。", "target_word": "一行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天上飞过一行大雁。", "target_word": "一行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在纸上画了一行小星星。", "target_word": "一行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首诗只有一行，却很感人。", "target_word": "一行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上的蚂蚁排成一行，慢慢向前走。", "target_word": "一行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "表格里每个格子只能写一行字。", "target_word": "一行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我用红笔在书上标出了一行字。", "target_word": "一行", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一行行", "label": "重叠"}], "register": "中性", "sense_fingerprint": "一行：一条横排，文字或事物排成一线，如一行字、一行脚印", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2beb4a87-1356-4fca-8f26-67e841f14fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一行", "is_correct": true, "explanation": "“一行脚印”指一条横排的脚印，与“留下”搭配，符合题意。"}, {"text": "一棵", "is_correct": false, "explanation": "搭配：“棵”用于植物，脚印不能用“棵”计量。"}, {"text": "一瓶", "is_correct": false, "explanation": "语义：“瓶”是盛液体的容器，雪地上不会留下一瓶脚印。"}, {"text": "一杯", "is_correct": false, "explanation": "语义：“杯”是盛饮料的器具，脚印不能是一杯。"}], "explanations": {"一行": "“一行脚印”指一条横排的脚印，与“留下”搭配，符合题意。", "一棵": "搭配：“棵”用于植物，脚印不能用“棵”计量。", "一瓶": "语义：“瓶”是盛液体的容器，雪地上不会留下一瓶脚印。", "一杯": "语义：“杯”是盛饮料的器具，脚印不能是一杯。"}, "sentence_index": 0, "correct_answer": "一行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她捧着一行鲜花走进教室。", "explanation": "这里应该用〈一束〉。“一行”强调排成线的字或事物，成束的鲜花要用“一束”。"}, {"text": "他一口气喝光了一行汤。", "explanation": "这里应该用〈一碗〉。“一行”只计量排成线的文字或事物，汤要用“一碗”。"}, {"text": "他只说了一行话，就转身走了。", "explanation": "这里应该用〈一句〉。“一行”指一条横排的文字，说出的话要用“一句”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一行", "is_correct": true, "explanation": "“一行”指一行诗句，修饰“这首诗”，与“只有”搭配，符合题意。"}, {"text": "一座", "is_correct": false, "explanation": "语义：“座”用于山、楼等大型物体，诗不能用“座”计量。"}, {"text": "一朵", "is_correct": false, "explanation": "搭配：“朵”多用于花朵、云朵，不能用来计量一首诗的句子。"}, {"text": "一碗", "is_correct": false, "explanation": "语义：“碗”是盛饭的器皿，诗不能算作一碗。"}], "explanations": {"一行": "“一行”指一行诗句，修饰“这首诗”，与“只有”搭配，符合题意。", "一座": "语义：“座”用于山、楼等大型物体，诗不能用“座”计量。", "一朵": "搭配：“朵”多用于花朵、云朵，不能用来计量一首诗的句子。", "一碗": "语义：“碗”是盛饭的器皿，诗不能算作一碗。"}, "sentence_index": 6, "correct_answer": "一行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首曲子有一行动人的旋律。", "explanation": "这里应该用〈一段〉。“一行”只能指排成横排的文字或事物，旋律要用“一段”。"}, {"text": "她把一行糖放进了嘴里。", "explanation": "这里应该用〈一颗〉。“一行”只计量排成线的字或事物，单颗糖要用“一颗”。"}, {"text": "我家养了一行小猫。", "explanation": "这里应该用〈一只〉。“一行”只能计量排成横排的文字或事物，小猫要用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91252, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "河岸边种着一行个垂柳。", "corrected_sentence": "河岸边种着一行垂柳。", "error_description": "量词错误：“一行”已含量词，后面不能再加“个”，应说“一行垂柳”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海边的沙地上留下了一行个清晰的脚印。", "corrected_sentence": "海边的沙地上留下了一行清晰的脚印。", "error_description": "量词错误：“一行”已含量词，后面不能再加“个”，应说“一行清晰的脚印”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
