INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91261, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "一套是合在一起的一整份东西。", "primary_collocate": null, "pronunciation": "yí tào", "ipa": "i˧˥ tʰɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我们租了一套有两个房间的房子。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一套新衣服，从上到下都是黑色的。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子和椅子是一套的。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖一套完整的厨房用具。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她送了我一套小学英语书。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我们一套练习，一共二十页。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想出了一套办法，大家都同意。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这一套资料交给经理。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的生日礼物是一套积木。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里放着一套红木家具。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一整套", "label": "复合"}], "register": "中性", "sense_fingerprint": "量词：合在一起的一整份东西，如房子、家具、资料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d5693c-26b2-4f0a-ad61-6ebde57a6292') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91261, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一套", "is_correct": true, "explanation": "正确答案：一套（yí tào），指合在一起的一整份东西。"}, {"text": "椅套", "is_correct": false, "explanation": "yǐ（第三声）与 yí（第二声）声调不同，椅套指椅子上的罩子。"}, {"text": "一道", "is_correct": false, "explanation": "tào 与 dào 声母不同：t 送气，d 不送气，一道意思是一起或一条路。"}, {"text": "一趟", "is_correct": false, "explanation": "tào 与 tàng 韵母不同（ao 与 ang），一趟指一次往返，是量词。"}], "explanations": {"一套": "正确答案：一套（yí tào），指合在一起的一整份东西。", "椅套": "yǐ（第三声）与 yí（第二声）声调不同，椅套指椅子上的罩子。", "一道": "tào 与 dào 声母不同：t 送气，d 不送气，一道意思是一起或一条路。", "一趟": "tào 与 tàng 韵母不同（ao 与 ang），一趟指一次往返，是量词。"}, "sentence_index": null, "correct_answer": "一套"}, "level_3": {"options": [{"text": "一套", "is_correct": true, "explanation": "正确：一套指一整套住房，与“有两个房间的房子”相符。"}, {"text": "一间", "is_correct": false, "explanation": "语义：“间”指一个房间，与后文“两个房间”矛盾。"}, {"text": "一把", "is_correct": false, "explanation": "搭配：“把”用于有柄或可握的器具，不用于房子。"}, {"text": "一台", "is_correct": false, "explanation": "搭配：“台”用于机器、设备，不用于住房。"}], "explanations": {"一套": "正确：一套指一整套住房，与“有两个房间的房子”相符。", "一间": "语义：“间”指一个房间，与后文“两个房间”矛盾。", "一把": "搭配：“把”用于有柄或可握的器具，不用于房子。", "一台": "搭配：“台”用于机器、设备，不用于住房。"}, "sentence_index": 0, "correct_answer": "一套"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市场上运来了一套蔬菜，摊主正在卸车。", "explanation": "这里应该用〈一批〉。“一套”指合在一起的一整份东西，成批运来的蔬菜要说“一批”。"}, {"text": "他剥了一套花生吃。", "explanation": "这里应该用〈一把〉。“一套”用于合在一起的一整份东西，散颗粒的花生要说“一把”或“一包”。"}, {"text": "早上他喝了一套牛奶。", "explanation": "这里应该用〈一盒〉。牛奶是液体，要用“一盒”或“一瓶”计量，不能用“一套”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91261, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一套", "is_correct": true, "explanation": "正确：一套指成系统的一整套办法，与“大家都同意”相符。"}, {"text": "一对", "is_correct": false, "explanation": "搭配：“对”指成双成对的东西，办法不成对，不能用“对”计量。"}, {"text": "一匹", "is_correct": false, "explanation": "搭配：“匹”用于马和成卷的布，不用于办法。"}, {"text": "一根", "is_correct": false, "explanation": "搭配：“根”用于细长的东西，不用于办法。"}], "explanations": {"一套": "正确：一套指成系统的一整套办法，与“大家都同意”相符。", "一对": "搭配：“对”指成双成对的东西，办法不成对，不能用“对”计量。", "一匹": "搭配：“匹”用于马和成卷的布，不用于办法。", "一根": "搭配：“根”用于细长的东西，不用于办法。"}, "sentence_index": 6, "correct_answer": "一套"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子角落里堆着一套木柴，准备过冬。", "explanation": "这里应该用〈一堆〉。“一套”指合在一起的一整份东西，随意堆放的木柴要说“一堆”。"}, {"text": "屋檐下挂着一套玉米，金黄金黄的。", "explanation": "这里应该用〈一串〉。“一套”指合在一起的一整份东西，用绳子挂成一串的玉米要说“一串”。"}, {"text": "他小心地捧着一套沙子，撒进了花盆。", "explanation": "这里应该用〈一捧〉。“一套”指合在一起的一整份东西，双手捧起的沙子要说“一捧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91261, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她买了一套的床上用品。", "corrected_sentence": "她买了一套床上用品。", "error_description": "错误形式：一套的床上用品；正确形式：一套床上用品。“一套”作数量定语时后面不加“的”，应直接接名词。", "correct_sentence_indices": [0, 1, 4]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91261, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把一套的工具交给了新来的工人。", "corrected_sentence": "老师把一套工具交给了新来的工人。", "error_description": "错误形式：一套的工具；正确形式：一套工具。“一套”作数量定语修饰名词时，后面不能加“的”，应直接接名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
