INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91262, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "一组配合成整体的东西。", "primary_collocate": null, "pronunciation": "yí tào", "ipa": "i˧˥ tʰɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我新买了一套茶具，一共六个杯子。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给孩子买了一套彩色笔。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店里有一套很有名的小说，一共五本。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈穿着一套红色的衣服去参加婚礼。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店换了一套新的餐具。", "target_word": "一套", "complexity_tier": "T3", "furigana": "yí tào", "sentence_source": "generated"}, {"text": "我们家有一套老沙发。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把一套新课本放进了书包。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发给每人一套练习题。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一套深色的西装去面试。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一套工具里有锤子和钳子。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一整套", "label": "复合"}], "register": "中性", "sense_fingerprint": "量词：配合成整体的一组东西，如茶具、衣服、工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d5693c-26b2-4f0a-ad61-6ebde57a6292') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91262, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一套", "is_correct": true, "explanation": "正确答案：一套（yí tào），指配成整体的一组东西。"}, {"text": "椅套", "is_correct": false, "explanation": "yǐ（第三声）与 yí（第二声）声调不同，椅套指椅子上的罩子。"}, {"text": "一道", "is_correct": false, "explanation": "tào 与 dào 声母不同：t 送气，d 不送气，一道意思是一起或一条路。"}, {"text": "一趟", "is_correct": false, "explanation": "tào 与 tàng 韵母不同（ao 与 ang），一趟指一次往返，是量词。"}], "explanations": {"一套": "正确答案：一套（yí tào），指配成整体的一组东西。", "椅套": "yǐ（第三声）与 yí（第二声）声调不同，椅套指椅子上的罩子。", "一道": "tào 与 dào 声母不同：t 送气，d 不送气，一道意思是一起或一条路。", "一趟": "tào 与 tàng 韵母不同（ao 与 ang），一趟指一次往返，是量词。"}, "sentence_index": null, "correct_answer": "一套"}, "level_3": {"options": [{"text": "一套", "is_correct": true, "explanation": "正确：一套指成组配合的一整套茶具，与后文“一共六个杯子”相符。"}, {"text": "一对", "is_correct": false, "explanation": "搭配：“对”指成双的东西，六个杯子的一整套茶具不是一对。"}, {"text": "一只", "is_correct": false, "explanation": "搭配：“只”用于动物或成对物中的一个，不用于计量茶具。"}, {"text": "一把", "is_correct": false, "explanation": "搭配：“把”用于有柄或可握的器具，成套的茶具不用“把”计量。"}], "explanations": {"一套": "正确：一套指成组配合的一整套茶具，与后文“一共六个杯子”相符。", "一对": "搭配：“对”指成双的东西，六个杯子的一整套茶具不是一对。", "一只": "搭配：“只”用于动物或成对物中的一个，不用于计量茶具。", "一把": "搭配：“把”用于有柄或可握的器具，成套的茶具不用“把”计量。"}, "sentence_index": 0, "correct_answer": "一套"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "院子里走着一套小鸡，都在地上找虫子吃。", "explanation": "这里应该用〈一群〉。“一套”指配成整体的一组东西，成群的小鸡要说“一群”。"}, {"text": "我渴了，就喝了一套水。", "explanation": "这里应该用〈一杯〉。“一套”用于配成整体的成组物品，水要用“一杯”计量。"}, {"text": "妈妈去超市买了一套大米。", "explanation": "这里应该用〈一袋〉。“一套”不用于散装的粮食，大米要说“一袋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一套", "is_correct": true, "explanation": "正确：一套指成套的课本，与“放进了书包”的语境相符。"}, {"text": "一块", "is_correct": false, "explanation": "搭配：“块”用于块状的东西，不用于成套的课本。"}, {"text": "一片", "is_correct": false, "explanation": "搭配：“片”用于平而薄的东西，课本不能用“片”计量。"}, {"text": "一张", "is_correct": false, "explanation": "语义：“张”指平面的纸、床等，成册的课本不是一张纸，与“一套”的成组意思不合。"}], "explanations": {"一套": "正确：一套指成套的课本，与“放进了书包”的语境相符。", "一块": "搭配：“块”用于块状的东西，不用于成套的课本。", "一片": "搭配：“片”用于平而薄的东西，课本不能用“片”计量。", "一张": "语义：“张”指平面的纸、床等，成册的课本不是一张纸，与“一套”的成组意思不合。"}, "sentence_index": 6, "correct_answer": "一套"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "仓库里运来了一套砖，堆在门口。", "explanation": "这里应该用〈一批〉。“一套”指配成整体的一组东西，成批运来的散砖要说“一批”。"}, {"text": "枝头挂着一套红枣，红彤彤的。", "explanation": "这里应该用〈一串〉。“一套”指配成整体的一组东西，挂成一串的红枣要说“一串”。"}, {"text": "院子里堆着一套垃圾，都没人收。", "explanation": "这里应该用〈一堆〉。“一套”指配成整体的一组东西，随手堆在一起的垃圾要说“一堆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给我买了一套的运动服。", "corrected_sentence": "妈妈给我买了一套运动服。", "error_description": "错误形式：一套的运动服；正确形式：一套运动服。“一套”作数量定语时后面不加“的”，应直接接名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师给每个学生发了一套一套练习册。", "corrected_sentence": "老师给每个学生发了一套练习册。", "error_description": "重复错误：错误形式是“一套一套练习册”，正确形式是“一套练习册”。“一套”只出现一次，多写一个“一套”是多余的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91271, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难听", "is_correct": true, "explanation": "正确。“难听”指话或声音听起来使人不舒服，与“中听”构成反义。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”形容清晰明白，与“中听”没有反义关系。"}, {"text": "认真", "is_correct": false, "explanation": "无关：“认真”形容态度，与“中听”的话语感受无反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "无关：“便宜”形容价格低，与“中听”没有反义关系。"}], "correct_answer": "难听", "explanations": {"难听": "正确。“难听”指话或声音听起来使人不舒服，与“中听”构成反义。", "清楚": "无关：“清楚”形容清晰明白，与“中听”没有反义关系。", "认真": "无关：“认真”形容态度，与“中听”的话语感受无反义关系。", "便宜": "无关：“便宜”形容价格低，与“中听”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91271, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难听", "is_correct": true, "explanation": "正确。“难听”指话听起来让人不舒服，与“中听”是反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "无关：“漂亮”形容外貌或事物好看，与“中听”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "无关：“干净”形容清洁，与“中听”无反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "无关：“高兴”形容心情，与“中听”的反义关系无关。"}], "correct_answer": "难听", "explanations": {"难听": "正确。“难听”指话听起来让人不舒服，与“中听”是反义关系。", "漂亮": "无关：“漂亮”形容外貌或事物好看，与“中听”没有反义关系。", "干净": "无关：“干净”形容清洁，与“中听”无反义关系。", "高兴": "无关：“高兴”形容心情，与“中听”的反义关系无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91271, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "中听是话说出来，听着让人舒服。", "primary_collocate": null, "pronunciation": "zhòng tīng", "ipa": "ʈʂʊŋ˥˩ tʰiŋ˥", "syllable_count": 2, "sentences": [{"text": "他的话很不中听，大家都不高兴。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话说得真中听，我心里很高兴。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "良药苦口，忠言往往不中听。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话总是很中听，朋友都喜欢她。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这话不中听，说得太直接了。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他夸我的几句话特别中听。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说的话虽然不中听，但是对我有用。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人说了几句中听的话，老板笑了。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些话听着不中听，却是真话。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想说句不中听的话，你别生气。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不中听", "label": "否定"}, {"form": "中聽", "label": "繁体"}], "register": "口语", "sense_fingerprint": "中听：话说得让人听着舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4849ac9e-2819-4619-bcd7-af3a75ec75c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91271, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中听", "is_correct": true, "explanation": "正确。“很不中听”指话说得让人听着不舒服，与“大家都不高兴”呼应。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”形容人的岁数，不能用来形容“话”，句子不通。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”指人的情绪，不能用来说“话”高兴与否。"}, {"text": "健壮", "is_correct": false, "explanation": "语义：“健壮”形容人或动物的身体，与“话”搭配不当。"}], "explanations": {"中听": "正确。“很不中听”指话说得让人听着不舒服，与“大家都不高兴”呼应。", "年轻": "语义：“年轻”形容人的岁数，不能用来形容“话”，句子不通。", "高兴": "搭配：“高兴”指人的情绪，不能用来说“话”高兴与否。", "健壮": "语义：“健壮”形容人或动物的身体，与“话”搭配不当。"}, "sentence_index": 0, "correct_answer": "中听"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子坐起来很中听。", "explanation": "这里应该用〈舒服〉。中听只用于言语，不能形容椅子坐着的感觉，坐着舒服要说舒服。"}, {"text": "这场比赛很中听。", "explanation": "这里应该用〈精彩〉。中听只用于说话、言论，不能用来评价比赛，比赛好看要说精彩。"}, {"text": "这道菜很中听。", "explanation": "这里应该用〈可口〉。中听只形容言语，不能用来形容食物，食物好吃要说可口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91271, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中听", "is_correct": true, "explanation": "正确。“不中听”指话说出来让人听着不舒服，与前一分句的“虽然”相呼应。"}, {"text": "好看", "is_correct": false, "explanation": "语义：“好看”形容外貌或景象，不能用来形容“话”。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”指价格低，与“话”搭配不当。"}, {"text": "结实", "is_correct": false, "explanation": "语义：“结实”形容物体或身体坚固，不能用来形容说话。"}], "explanations": {"中听": "正确。“不中听”指话说出来让人听着不舒服，与前一分句的“虽然”相呼应。", "好看": "语义：“好看”形容外貌或景象，不能用来形容“话”。", "便宜": "搭配：“便宜”指价格低，与“话”搭配不当。", "结实": "语义：“结实”形容物体或身体坚固，不能用来形容说话。"}, "sentence_index": 6, "correct_answer": "中听"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影很中听。", "explanation": "这里应该用〈感人〉。中听形容说的话，不能用来评价电影，电影让人动容要说感人。"}, {"text": "这本书很中听。", "explanation": "这里应该用〈有趣〉。中听只用于言语，不能用来形容书，书好玩要说有趣。"}, {"text": "这间屋子很中听。", "explanation": "这里应该用〈整洁〉。中听只用于说的话，不能形容房间，房间干净要说整洁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91271, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这番话说很中听，我很高兴。", "corrected_sentence": "他这番话说得很中听，我很高兴。", "error_description": "错误：“说很中听”，正确：“说得很中听”。“很中听”作程度补语，要用“得”连接动词和补语，漏掉“得”就不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91271, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她说了几句很中听话，我们都很高兴。", "corrected_sentence": "她说了几句很中听的话，我们都很高兴。", "error_description": "错误：“很中听话”，正确：“很中听的话”。“中听”修饰名词“话”时，中间要加“的”，漏掉“的”就不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91272, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难听", "is_correct": true, "explanation": "正确。“难听”指话听起来让人不舒服，与“中听”是反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "无关：“高兴”形容心情，不指话的听感，与“中听”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”形容清晰明白，与“中听”无反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "无关：“便宜”形容价格低，与“中听”没有反义关系。"}], "correct_answer": "难听", "explanations": {"难听": "正确。“难听”指话听起来让人不舒服，与“中听”是反义关系。", "高兴": "无关：“高兴”形容心情，不指话的听感，与“中听”没有反义关系。", "清楚": "无关：“清楚”形容清晰明白，与“中听”无反义关系。", "便宜": "无关：“便宜”形容价格低，与“中听”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91272, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难听", "is_correct": true, "explanation": "正确。“难听”指话听起来让人不舒服，与“中听”是反义关系。"}, {"text": "认真", "is_correct": false, "explanation": "无关：“认真”形容态度，与“中听”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "无关：“干净”形容清洁，与“中听”无反义关系。"}, {"text": "精致", "is_correct": false, "explanation": "无关：“精致”形容做工或样式精细，与“中听”没有反义关系。"}], "correct_answer": "难听", "explanations": {"难听": "正确。“难听”指话听起来让人不舒服，与“中听”是反义关系。", "认真": "无关：“认真”形容态度，与“中听”没有反义关系。", "干净": "无关：“干净”形容清洁，与“中听”无反义关系。", "精致": "无关：“精致”形容做工或样式精细，与“中听”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91272, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "话听起来使人满意或舒服。", "primary_collocate": null, "pronunciation": "zhòng tīng", "ipa": "ʈʂʊŋ˥˩ tʰiŋ˥", "syllable_count": 2, "sentences": [{"text": "老师夸我的话真中听。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他挑了几句中听的话来安慰我。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这话说得不中听，她听了很生气。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新同事嘴很甜，说的话都很中听。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不爱听奉承，可是他的话很中听。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人觉得孩子的话中听，笑得很开心。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的批评一点也不中听，我听了很难受。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好话谁都爱听，中听的话让人心里暖。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说话要中听一些，别伤了别人的心。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的几句话不太中听，同桌听了不说话。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不中听", "label": "否定"}, {"form": "中聽", "label": "繁体"}], "register": "口语", "sense_fingerprint": "中听：话听起来让人满意、舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4849ac9e-2819-4619-bcd7-af3a75ec75c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91272, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中听", "is_correct": true, "explanation": "正确。“真中听”指话让人听着舒服，与“老师夸我”的语境相符。"}, {"text": "刺耳", "is_correct": false, "explanation": "语义：“刺耳”指声音尖锐难听，与“老师夸我”的赞扬语境矛盾。"}, {"text": "难看", "is_correct": false, "explanation": "语义：“难看”形容外貌不好看，不能用来说“话”，且与“夸我”矛盾。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”指价格低，不能用来形容“话”。"}], "explanations": {"中听": "正确。“真中听”指话让人听着舒服，与“老师夸我”的语境相符。", "刺耳": "语义：“刺耳”指声音尖锐难听，与“老师夸我”的赞扬语境矛盾。", "难看": "语义：“难看”形容外貌不好看，不能用来说“话”，且与“夸我”矛盾。", "便宜": "搭配：“便宜”指价格低，不能用来形容“话”。"}, "sentence_index": 0, "correct_answer": "中听"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店的菜很中听。", "explanation": "这里应该用〈好吃〉。中听只用于说的话，不能用来形容食物，食物味道好要说好吃。"}, {"text": "她穿的裙子很中听。", "explanation": "这里应该用〈漂亮〉。中听形容话语，不能形容衣服，衣服好看要说漂亮。"}, {"text": "躺在沙发上很中听。", "explanation": "这里应该用〈舒服〉。中听只用于言语，不能形容身体的感受，身体舒适要说舒服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中听", "is_correct": true, "explanation": "正确。“一点也不中听”指批评让人听着很不舒服，与“我听了很难受”呼应。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音响亮爽利，不用来形容“批评”。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容人或事物的形体，不能用来形容“批评”。"}, {"text": "凉快", "is_correct": false, "explanation": "语义：“凉快”形容天气或感觉凉爽，与“批评”搭配不当，且与“很难受”的语境无关。"}], "explanations": {"中听": "正确。“一点也不中听”指批评让人听着很不舒服，与“我听了很难受”呼应。", "清脆": "语义：“清脆”形容声音响亮爽利，不用来形容“批评”。", "高大": "搭配：“高大”形容人或事物的形体，不能用来形容“批评”。", "凉快": "语义：“凉快”形容天气或感觉凉爽，与“批评”搭配不当，且与“很难受”的语境无关。"}, "sentence_index": 6, "correct_answer": "中听"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些蔬菜很中听。", "explanation": "这里应该用〈新鲜〉。中听只用于说的话，不能形容蔬菜，蔬菜不陈旧要说新鲜。"}, {"text": "这间教室很中听。", "explanation": "这里应该用〈宽敞〉。中听形容话语，不能形容教室，空间大要说宽敞。"}, {"text": "这些书摆得很中听。", "explanation": "这里应该用〈整齐〉。中听只用于言语，不能用来形容摆放，摆放有序要说整齐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他说的几句话得中听，大家都笑了。", "corrected_sentence": "他说的几句话很中听，大家都笑了。", "error_description": "错误：“得中听”，正确：“很中听”。程度副词“很”修饰形容词，不能用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人听了我的几句很中听话，笑个不停。", "corrected_sentence": "老人听了我的几句很中听的话，笑个不停。", "error_description": "错误：“很中听话”，正确：“很中听的话”。“中听”修饰名词“话”时，中间要加“的”，漏掉“的”就不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
