INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91275, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "走在最前面带头的人。", "primary_collocate": null, "pronunciation": "xiān fēng", "ipa": "ɕjɛn˥ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "他是我们队的先锋。", "target_word": "先锋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位先锋走在最前面。", "target_word": "先锋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王做了我们的先锋。", "target_word": "先锋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家让他当先锋，他走在前面带路。", "target_word": "先锋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先锋已经到山顶了。", "target_word": "先锋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥是登山队的先锋，走得很快。", "target_word": "先锋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁愿意做先锋，先去前面看看？", "target_word": "先锋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先锋回头对大家说：“跟我来！”", "target_word": "先锋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次探险，他是我们队的先锋，第一个进了山洞。", "target_word": "先锋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路不好走，先锋用刀开路。", "target_word": "先锋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位先锋", "label": "量词"}, {"form": "一名先锋", "label": "量词"}], "register": "书面", "sense_fingerprint": "走在队伍最前面带头的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daefa5e4-da06-49ae-91b6-3464485ab917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91275, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "先锋", "is_correct": true, "explanation": "正确：先锋 xiān fēng，指走在队伍最前面带头的人。"}, {"text": "险峰", "is_correct": false, "explanation": "xiǎn（第三声）与 xiān（第一声）声调不同，意思是险峻的山峰。"}, {"text": "新风", "is_correct": false, "explanation": "xīn 与 xiān 的韵母不同（-in 与 -ian），意思是新风气或新鲜空气。"}, {"text": "西风", "is_correct": false, "explanation": "xī 比 xiān 少了韵尾 n，意思是从西边吹来的风。"}, {"text": "尖峰", "is_correct": false, "explanation": "jiān 与 xiān 声母不同（j 与 x），意思是山的尖顶或最高处。"}], "explanations": {"先锋": "正确：先锋 xiān fēng，指走在队伍最前面带头的人。", "险峰": "xiǎn（第三声）与 xiān（第一声）声调不同，意思是险峻的山峰。", "新风": "xīn 与 xiān 的韵母不同（-in 与 -ian），意思是新风气或新鲜空气。", "西风": "xī 比 xiān 少了韵尾 n，意思是从西边吹来的风。", "尖峰": "jiān 与 xiān 声母不同（j 与 x），意思是山的尖顶或最高处。"}, "sentence_index": null, "correct_answer": "先锋"}, "level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子是物品，不能指“他”这个人。"}, {"text": "先锋", "is_correct": true, "explanation": "正确：先锋指走在队伍最前面带头的人，与“他是我们队的……”相合。"}, {"text": "纪录", "is_correct": false, "explanation": "搭配：“纪录”是成绩，不说“他是……纪录”，应说“纪录保持者”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然事物，与指人的身份不合。"}], "explanations": {"桌子": "语义：桌子是物品，不能指“他”这个人。", "先锋": "正确：先锋指走在队伍最前面带头的人，与“他是我们队的……”相合。", "纪录": "搭配：“纪录”是成绩，不说“他是……纪录”，应说“纪录保持者”。", "河流": "语义：河流是自然事物，与指人的身份不合。"}, "sentence_index": 0, "correct_answer": "先锋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛他踢先锋，进了两个球。", "explanation": "这里应该用〈前锋〉。先锋指走在队伍最前面带头的人；足球中进攻位置叫“前锋”，不说“踢先锋”。"}, {"text": "他总是落在队伍最后面断后，是我们的先锋。", "explanation": "这里的“先锋”指走在最前面带头的人，与“落在队伍最后面”的位置相反；表示走在最后面的人应说〈殿后〉。"}, {"text": "这张先锋走在最前面，很勇敢。", "explanation": "这里应该用〈位〉。先锋指人，量词用“位”或“名”，“张”多用于纸张、桌子等平面的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91275, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地毯", "is_correct": false, "explanation": "语义：地毯是物品，不能去前面看看。"}, {"text": "先锋", "is_correct": true, "explanation": "正确：先锋指带头走在前面的人，与“谁愿意做……先去前面看看”相合。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是计时器具，不能指愿意先去前面看看的人。"}, {"text": "道路", "is_correct": false, "explanation": "搭配：“做”一般不接“道路”，应说“修道路”。"}], "explanations": {"地毯": "语义：地毯是物品，不能去前面看看。", "先锋": "正确：先锋指带头走在前面的人，与“谁愿意做……先去前面看看”相合。", "闹钟": "语义：闹钟是计时器具，不能指愿意先去前面看看的人。", "道路": "搭配：“做”一般不接“道路”，应说“修道路”。"}, "sentence_index": 6, "correct_answer": "先锋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在中场打先锋，传球很准。", "explanation": "这里应该用〈前卫〉。足球中“前卫”指中场球员，“先锋”不是这个位置的名称。"}, {"text": "这朵先锋今年带领全队拿了冠军。", "explanation": "这里应该用〈位〉。先锋指人，量词用“位”或“名”，“朵”用于花。"}, {"text": "他整天躺在床上不愿动，是我们班的先锋。", "explanation": "这里的“先锋”指走在最前面、带头行动的人，与“整天躺在床上不愿动”矛盾；这种落在后面的人应说〈落伍者〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91275, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我们队的一只先锋，总是走在最前面。", "corrected_sentence": "他是我们队的一名先锋，总是走在最前面。", "error_description": "“先锋”指人，量词应用“名”或“位”，不能用“只”（“只”多用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91275, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经做过一只先锋，带着大家走在最前面。", "corrected_sentence": "他曾经做过一名先锋，带着大家走在最前面。", "error_description": "“先锋”指人，量词应用“名”或“位”，不能用“只”（“只”多用于动物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
