INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91276, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在前面带头行进或起带头作用的人或队伍。", "primary_collocate": null, "pronunciation": "xiān fēng", "ipa": "ɕjɛn˥ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这支队伍是大军的先锋，很快到了河边。", "target_word": "先锋", "complexity_tier": "T3", "furigana": "xiān fēng", "sentence_source": "generated"}, {"text": "他们是行业里的先锋。", "target_word": "先锋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人是改革的先锋。", "target_word": "先锋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的队伍走在大军的最前面，是先锋。", "target_word": "先锋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是环保的先锋，大家都向她学习。", "target_word": "先锋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先锋带着大家向前走。", "target_word": "先锋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生是抗病毒的先锋。", "target_word": "先锋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，我们要做学习的先锋。", "target_word": "先锋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司是科技行业的先锋。", "target_word": "先锋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天亮前，我们的先锋出发了。", "target_word": "先锋", "complexity_tier": "T3", "furigana": "xiān fēng", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位先锋", "label": "量词"}, {"form": "一名先锋", "label": "量词"}], "register": "书面", "sense_fingerprint": "在某方面起带头作用的人或队伍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daefa5e4-da06-49ae-91b6-3464485ab917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91276, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "先锋", "is_correct": true, "explanation": "正确：先锋 xiān fēng，指在某方面起带头作用的人或队伍。"}, {"text": "险峰", "is_correct": false, "explanation": "xiǎn（第三声）与 xiān（第一声）声调不同，意思是险峻的山峰。"}, {"text": "新风", "is_correct": false, "explanation": "xīn 与 xiān 的韵母不同（-in 与 -ian），意思是新风气或新鲜空气。"}, {"text": "西风", "is_correct": false, "explanation": "xī 比 xiān 少了韵尾 n，意思是从西边吹来的风。"}, {"text": "尖峰", "is_correct": false, "explanation": "jiān 与 xiān 声母不同（j 与 x），意思是山的尖顶或最高处。"}], "explanations": {"先锋": "正确：先锋 xiān fēng，指在某方面起带头作用的人或队伍。", "险峰": "xiǎn（第三声）与 xiān（第一声）声调不同，意思是险峻的山峰。", "新风": "xīn 与 xiān 的韵母不同（-in 与 -ian），意思是新风气或新鲜空气。", "西风": "xī 比 xiān 少了韵尾 n，意思是从西边吹来的风。", "尖峰": "jiān 与 xiān 声母不同（j 与 x），意思是山的尖顶或最高处。"}, "sentence_index": null, "correct_answer": "先锋"}, "level_3": {"options": [{"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是用具，不能指一支队伍。"}, {"text": "先锋", "is_correct": true, "explanation": "正确：先锋指在某方面起带头作用的队伍，与“大军的”相合，符合句意。"}, {"text": "蜗牛", "is_correct": false, "explanation": "搭配：蜗牛爬得慢，与“很快到了河边”搭配不合。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然事物，不能说“是大军的河流”。"}], "explanations": {"雨伞": "语义：雨伞是用具，不能指一支队伍。", "先锋": "正确：先锋指在某方面起带头作用的队伍，与“大军的”相合，符合句意。", "蜗牛": "搭配：蜗牛爬得慢，与“很快到了河边”搭配不合。", "河流": "语义：河流是自然事物，不能说“是大军的河流”。"}, "sentence_index": 0, "correct_answer": "先锋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张先锋今年带动了整个行业的发展。", "explanation": "这里应该用〈位〉。先锋指人，量词用“位”或“名”，“张”用于平面的东西。"}, {"text": "这支队伍今天一直躲在山洞里不出来，是大军的先锋。", "explanation": "这里的“先锋”指带头行动的人，与“一直躲在山洞里不出来”矛盾；这种落在后面的人应说〈落伍者〉。"}, {"text": "这朵先锋总是走在大家前面。", "explanation": "这里应该用〈位〉。先锋指人，量词用“位”或“名”，“朵”用于花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91276, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "药品", "is_correct": false, "explanation": "语义：医生是人，不能说“是……药品”。"}, {"text": "先锋", "is_correct": true, "explanation": "正确：先锋指在某方面起带头作用的人，与“医生是抗病毒的……”相合。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套是用具，与指人的身份不合。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“抗病毒的”多修饰药物、疫苗等，不修饰窗帘。"}], "explanations": {"药品": "语义：医生是人，不能说“是……药品”。", "先锋": "正确：先锋指在某方面起带头作用的人，与“医生是抗病毒的……”相合。", "手套": "语义：手套是用具，与指人的身份不合。", "窗帘": "搭配：“抗病毒的”多修饰药物、疫苗等，不修饰窗帘。"}, "sentence_index": 6, "correct_answer": "先锋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只先锋今年带动了全行业。", "explanation": "这里应该用〈位〉。先锋指人，“只”多用于动物，不用来数人。"}, {"text": "他在禁区里做先锋，专门抢点射门。", "explanation": "这里应该用〈前锋〉。足球中在禁区附近抢点射门的进攻球员叫“前锋”，“先锋”不是这个位置的名称。"}, {"text": "这颗先锋很有勇气，总是冲在最前面。", "explanation": "这里应该用〈位〉。先锋指人，量词用“位”或“名”，“颗”用于圆形的小东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司曾经做过行业的一朵先锋，很受尊敬。", "corrected_sentence": "这家公司曾经做过行业的一个先锋，很受尊敬。", "error_description": "“先锋”可指人或团体，量词可用“个”，不能用“朵”（“朵”多用于花）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那座先锋在改革中带头，大家都很佩服。", "corrected_sentence": "那位先锋在改革中带头，大家都很佩服。", "error_description": "“先锋”指人，量词应用“位”或“名”，不能用“座”（“座”用于山、建筑等大型固定的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
