INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91281, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91281, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "了无是一点也没有。", "primary_collocate": null, "pronunciation": "liǎo wú", "ipa": "liɑʊ˨˩˦ u˧˥", "syllable_count": 2, "sentences": [{"text": "他对这份工作了无兴趣。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里了无声息，一个人也没有。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪后的路上了无人迹。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他躺在床上，了无睡意。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人孤身一人，了无牵挂。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影老套，了无新意。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大火过后，这里了无痕迹。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对危险，他了无惧色。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失败以后，他对生活了无信心。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事了无趣味，我看了一半就停了。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "了無", "label": "繁体"}], "register": "书面", "sense_fingerprint": "了无：一点也没有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4849ac9e-2819-4619-bcd7-af3a75ec75c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91281, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "了无", "is_correct": true, "explanation": "正确。“了无兴趣”表示一点兴趣也没有，与句意一致。"}, {"text": "发挥", "is_correct": false, "explanation": "搭配：“发挥”多接作用、才能，不说“发挥兴趣”。"}, {"text": "测量", "is_correct": false, "explanation": "语义：“测量”针对可量化的事物，兴趣无法测量，句中不通。"}, {"text": "排斥", "is_correct": false, "explanation": "搭配：“排斥”多用于人或观点，不与“兴趣”搭配。"}], "explanations": {"了无": "正确。“了无兴趣”表示一点兴趣也没有，与句意一致。", "发挥": "搭配：“发挥”多接作用、才能，不说“发挥兴趣”。", "测量": "语义：“测量”针对可量化的事物，兴趣无法测量，句中不通。", "排斥": "搭配：“排斥”多用于人或观点，不与“兴趣”搭配。"}, "sentence_index": 0, "correct_answer": "了无"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他躺在床上，了无很多睡意。", "explanation": "这里误把〈了无〉当成“大量、许多”的意思来用，但它表示“一点也没有”。"}, {"text": "他躺在床上，了无很深的睡意。", "explanation": "这里误把〈了无〉当成“程度深、很强烈”的意思来用，但它表示全无，不能用来修饰程度。"}, {"text": "他躺在床上，了无没有睡意。", "explanation": "这里误把〈了无〉当成“仍然有”的意思来用。〈了无〉本身已是否定，再接“没有”就成了双重否定，意思与原意相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91281, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "了无", "is_correct": true, "explanation": "正确。“了无痕迹”表示一点痕迹也没有，与“大火过后”的语境相合。"}, {"text": "增添", "is_correct": false, "explanation": "搭配：“增添”多接色彩、负担，不说“增添痕迹”。"}, {"text": "目睹", "is_correct": false, "explanation": "配价：“目睹”的对象是事件或场面，不能说“目睹痕迹”。"}, {"text": "扩大", "is_correct": false, "explanation": "语义：“扩大”与“大火过后”的语境矛盾，痕迹不会随之扩大。"}], "explanations": {"了无": "正确。“了无痕迹”表示一点痕迹也没有，与“大火过后”的语境相合。", "增添": "搭配：“增添”多接色彩、负担，不说“增添痕迹”。", "目睹": "配价：“目睹”的对象是事件或场面，不能说“目睹痕迹”。", "扩大": "语义：“扩大”与“大火过后”的语境矛盾，痕迹不会随之扩大。"}, "sentence_index": 6, "correct_answer": "了无"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个故事了无很多趣味，我看了一半就停了。", "explanation": "这里误把〈了无〉当成“大量、许多”的意思来用，但它表示“一点也没有”。"}, {"text": "这个故事了无很深的寓意，我看了一半就停了。", "explanation": "这里误把〈了无〉当成“程度深、很有内涵”的意思来用，但它表示全无，不能修饰有深度的内容。"}, {"text": "这个故事了无最有趣的地方，我看了一半就停了。", "explanation": "这里误把〈了无〉当成“最、极其”的意思来用，但它表示全无，与“最有趣”的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91281, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间旧屋子里了无气生，连猫也没有。", "corrected_sentence": "这间旧屋子里了无生气，连猫也没有。", "error_description": "“了无”后的“生气”顺序颠倒，写成“气生”，不成词。正确说法是“了无生气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91281, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这次考试前了无很多准备，结果考得很糟糕。", "corrected_sentence": "他这次考试前了无准备，结果考得很糟糕。", "error_description": "错误：“了无很多准备”，正确：“了无准备”。“了无”已表示一点也没有，不能再与“很多”连用，二者意思矛盾，应去掉“很多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
