INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91282, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "全无；一点也没有（多用于书面）。", "primary_collocate": null, "pronunciation": "liǎo wú", "ipa": "liɑʊ˨˩˦ u˧˥", "syllable_count": 2, "sentences": [{"text": "湖面平静，了无波澜。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走后，屋里了无生气。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天空干净，了无云影。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事过去很久，他心里了无怨恨。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读完书，了无收获。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章了无特色，读起来很没意思。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人了无畏惧，一直往前走。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着离开，了无遗憾。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜深了，街上了无行人。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小村子了无变化，和多年前一样。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "了無", "label": "繁体"}], "register": "书面", "sense_fingerprint": "了无：全无，多用于书面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4849ac9e-2819-4619-bcd7-af3a75ec75c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91282, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "了无", "is_correct": true, "explanation": "正确。“了无波澜”表示水面没有一点起伏，与“平静”相合。"}, {"text": "驯服", "is_correct": false, "explanation": "搭配：“驯服”多用于动物或力量，不说“驯服波澜”。"}, {"text": "织", "is_correct": false, "explanation": "语义：“织”用于线、布，与水面的波动无关，句中不通。"}, {"text": "唤醒", "is_correct": false, "explanation": "搭配：“唤醒”多接意识、记忆，不接“波澜”。"}], "explanations": {"了无": "正确。“了无波澜”表示水面没有一点起伏，与“平静”相合。", "驯服": "搭配：“驯服”多用于动物或力量，不说“驯服波澜”。", "织": "语义：“织”用于线、布，与水面的波动无关，句中不通。", "唤醒": "搭配：“唤醒”多接意识、记忆，不接“波澜”。"}, "sentence_index": 0, "correct_answer": "了无"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事过去很久，他心里了无很多怨恨。", "explanation": "这里误把〈了无〉当成“大量、许多”的意思来用，但它表示“一点也没有”。"}, {"text": "这件事过去很久，他心里了无更多的怨恨。", "explanation": "这里误把〈了无〉当成“比以前更多”的意思来用，但它表示全无，不能用于比较数量的多少。"}, {"text": "这件事过去很久，他心里了无很深的怨恨。", "explanation": "这里误把〈了无〉当成“程度深、很强烈”的意思来用，但它表示全无。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91282, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "了无", "is_correct": true, "explanation": "正确。“了无畏惧”表示一点也不害怕，与“一直往前走”相合。"}, {"text": "雕刻", "is_correct": false, "explanation": "搭配：“雕刻”接物体，不接“畏惧”。"}, {"text": "修补", "is_correct": false, "explanation": "搭配：“修补”接器物或关系，不说“修补畏惧”。"}, {"text": "播种", "is_correct": false, "explanation": "语义：“播种”与人的心理状态无关，句中不通。"}], "explanations": {"了无": "正确。“了无畏惧”表示一点也不害怕，与“一直往前走”相合。", "雕刻": "搭配：“雕刻”接物体，不接“畏惧”。", "修补": "搭配：“修补”接器物或关系，不说“修补畏惧”。", "播种": "语义：“播种”与人的心理状态无关，句中不通。"}, "sentence_index": 6, "correct_answer": "了无"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小村子了无很多变化，和多年前一样。", "explanation": "这里误把〈了无〉当成“大量、许多”的意思来用，但它表示“一点也没有”。"}, {"text": "这个小村子了无很大的变化，和多年前一样。", "explanation": "这里误把〈了无〉当成“程度大、很明显”的意思来用，但它表示全无，不能说有很大的变化。"}, {"text": "这个小村子了无最大的变化，和多年前一样。", "explanation": "这里误把〈了无〉当成“最、极其”的意思来用，但它表示全无，与“最大”的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条河的水面了无过涟漪。", "corrected_sentence": "这条河的水面了无涟漪。", "error_description": "“了无”是固定的词，句中已含“了”，表示全无，不能再接“过”表示经历。错误形式是“了无过涟漪”，应写作“了无涟漪”，去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家旧书店的货架上了无很多新书。", "corrected_sentence": "这家旧书店的货架上了无新书。", "error_description": "错误：“了无很多新书”，正确：“了无新书”。“了无”表示全无，不能与“很多”连用，二者意思矛盾，应去掉“很多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c8696-24d1-44da-8978-5eb060ebc3d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91283, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "黑暗", "is_correct": true, "explanation": "正确：黑暗与光明是反义词，指没有光亮。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙形容表面不光滑，与光明没有反义关系。"}, {"text": "冰凉", "is_correct": false, "explanation": "冰凉形容温度低，与光明没有反义关系。"}, {"text": "干瘪", "is_correct": false, "explanation": "干瘪形容缺少水分、不饱满，与光明没有反义关系。"}], "correct_answer": "黑暗", "explanations": {"黑暗": "正确：黑暗与光明是反义词，指没有光亮。", "粗糙": "粗糙形容表面不光滑，与光明没有反义关系。", "冰凉": "冰凉形容温度低，与光明没有反义关系。", "干瘪": "干瘪形容缺少水分、不饱满，与光明没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91283, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "黑暗", "is_correct": true, "explanation": "正确：黑暗与光明是反义词，指没有光亮。"}, {"text": "湿润", "is_correct": false, "explanation": "湿润形容含有水分，与光明没有反义关系。"}, {"text": "辛辣", "is_correct": false, "explanation": "辛辣形容味道，与光明没有反义关系。"}, {"text": "清脆", "is_correct": false, "explanation": "清脆形容声音，与光明没有反义关系。"}], "correct_answer": "黑暗", "explanations": {"黑暗": "正确：黑暗与光明是反义词，指没有光亮。", "湿润": "湿润形容含有水分，与光明没有反义关系。", "辛辣": "辛辣形容味道，与光明没有反义关系。", "清脆": "清脆形容声音，与光明没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91283, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很亮，有光，让人觉得有希望。", "primary_collocate": null, "pronunciation": "guāng míng", "ipa": "kwɑŋ˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他的前途很光明。", "target_word": "光明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳出来了，天地都光明了。", "target_word": "光明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的未来一定光明。", "target_word": "光明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里点了灯，一下子光明起来了。", "target_word": "光明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一条光明的路。", "target_word": "光明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对生活有光明的希望。", "target_word": "光明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏事过去了，前面是光明的日子。", "target_word": "光明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光明的灯火让大家有了信心。", "target_word": "光明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看到光明的前景，心里很高兴。", "target_word": "光明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们终于走出了山洞，眼前一片光明。", "target_word": "光明", "complexity_tier": "T3", "furigana": "guāng míng", "sentence_source": "generated"}], "morphological_forms": [{"form": "光明正大", "label": "复合"}], "register": "通用", "sense_fingerprint": "明亮有光，让人觉得有希望", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daefa5e4-da06-49ae-91b6-3464485ab917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91283, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "柔软", "is_correct": false, "explanation": "语义：柔软形容质地，不能用来形容前途。"}, {"text": "光明", "is_correct": true, "explanation": "正确：光明指明亮，也比喻有希望，符合“前途很……”的句意。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：锋利多形容刀刃，不说“前途很锋利”。"}, {"text": "沙哑", "is_correct": false, "explanation": "语义：沙哑形容声音，与前途无关。"}], "explanations": {"柔软": "语义：柔软形容质地，不能用来形容前途。", "光明": "正确：光明指明亮，也比喻有希望，符合“前途很……”的句意。", "锋利": "搭配：锋利多形容刀刃，不说“前途很锋利”。", "沙哑": "语义：沙哑形容声音，与前途无关。"}, "sentence_index": 0, "correct_answer": "光明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的生意一天比一天惨淡，前景光明。", "explanation": "这里的“光明”指有希望、前景好，不能用来形容一天比一天惨淡的情况，这里应该用〈暗淡〉。"}, {"text": "前面的路很光明，却黑得伸手不见五指。", "explanation": "这里的“光明”指明亮，与“黑得伸手不见五指”矛盾；这里应该用〈黑暗〉。"}, {"text": "他的身体很光明，每天都能跑十公里。", "explanation": "这里的“光明”指明亮或前途有希望，不用来形容身体状况，这里应该用〈健康〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91283, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湿润", "is_correct": false, "explanation": "语义：湿润形容物体潮湿，与日子的好坏无关。"}, {"text": "光明", "is_correct": true, "explanation": "正确：光明作定语修饰“日子”，表示有希望，与“坏事过去了”前后相合。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：宽敞多形容空间，不说“宽敞的日子”。"}, {"text": "肥胖", "is_correct": false, "explanation": "语义：肥胖形容人或动物的体型，不能形容日子。"}], "explanations": {"湿润": "语义：湿润形容物体潮湿，与日子的好坏无关。", "光明": "正确：光明作定语修饰“日子”，表示有希望，与“坏事过去了”前后相合。", "宽敞": "搭配：宽敞多形容空间，不说“宽敞的日子”。", "肥胖": "语义：肥胖形容人或动物的体型，不能形容日子。"}, "sentence_index": 6, "correct_answer": "光明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题讲得很光明，大家一听就懂。", "explanation": "这里应该用〈清楚〉。光明指明亮或前途有希望，不用来形容讲解是否清楚。"}, {"text": "他的前途很光明，可惜早已没有任何希望了。", "explanation": "这里的“光明”指有希望，与“早已没有任何希望”矛盾；这里应该用〈渺茫〉。"}, {"text": "这盘菜的味道很光明，大家都爱吃。", "explanation": "这里应该用〈鲜美〉。光明指明亮或前途有希望，不用来形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91283, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司的发展前景很光明地，大家都看好它。", "corrected_sentence": "这家公司的发展前景很光明，大家都看好它。", "error_description": "“光明”作谓语时后面不加“地”，应说“很光明”，不能说“很光明地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91283, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的前途变很光明。", "corrected_sentence": "他的前途变得很光明。", "error_description": "“变”后接形容词作结果时要用补语“得”，应说“变得很光明”，不能说“变很光明”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
