INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91288, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "排列；陈列。", "primary_collocate": null, "pronunciation": "liè", "ipa": "li̯e˥˩", "syllable_count": 1, "sentences": [{"text": "书店里的新书整齐地列在架子上。", "target_word": "列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里列着很多古代的东西。", "target_word": "列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店的橱窗里列着各式各样的手表。", "target_word": "列", "complexity_tier": "T3", "furigana": "shāng diàn de chú chuāng lǐ liè zhe gè shì gè yàng de shǒu biǎo", "sentence_source": "generated"}, {"text": "同学们在操场上列成了两排。", "target_word": "列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "名单上列着十个人的名字。", "target_word": "列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把椅子按顺序列在墙边。", "target_word": "列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格表上列着每种菜的价钱。", "target_word": "列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货架上列着各种饮料。", "target_word": "列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街道两旁列着一排路灯。", "target_word": "列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书按大小顺序列好了。", "target_word": "列", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "列了", "label": "完成体"}, {"form": "列着", "label": "持续体"}, {"form": "列队", "label": "复合词"}, {"form": "列表", "label": "复合词"}], "register": "中性", "sense_fingerprint": "按次序排好、摆出来或写在表上：列在架子上、列成一排、名单上列着", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27aa1c00-fc1e-4f9c-85cd-83e1806a40ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91288, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "列", "is_correct": true, "explanation": "正确：列（liè）指按次序排开或陈列。"}, {"text": "谢", "is_correct": false, "explanation": "xiè 与 liè 声母不同（x / l），意思是感谢。"}, {"text": "立", "is_correct": false, "explanation": "lì（第四声）与 liè 韵母不同（i / ie），声调相同，意思是站立。"}, {"text": "料", "is_correct": false, "explanation": "liào 与 liè 韵母不同（ao / ie），意思是材料。"}, {"text": "咧", "is_correct": false, "explanation": "liē（第一声）与 liè（第四声）声调不同，意思是咧嘴。"}], "explanations": {"列": "正确：列（liè）指按次序排开或陈列。", "谢": "xiè 与 liè 声母不同（x / l），意思是感谢。", "立": "lì（第四声）与 liè 韵母不同（i / ie），声调相同，意思是站立。", "料": "liào 与 liè 韵母不同（ao / ie），意思是材料。", "咧": "liē（第一声）与 liè（第四声）声调不同，意思是咧嘴。"}, "sentence_index": null, "correct_answer": "列"}, "level_3": {"options": [{"text": "列", "is_correct": true, "explanation": "正确：“整齐地列在架子上”指按次序摆放，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下去，书不能“吃”在架子上。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”指人或动物躺下休息，书不能“睡”在架子上。"}, {"text": "说", "is_correct": false, "explanation": "配价：“说”要接话语作宾语，不能带“在架子上”这样的处所补语。"}], "explanations": {"列": "正确：“整齐地列在架子上”指按次序摆放，符合句意。", "吃": "语义：“吃”指把食物咽下去，书不能“吃”在架子上。", "睡": "语义：“睡”指人或动物躺下休息，书不能“睡”在架子上。", "说": "配价：“说”要接话语作宾语，不能带“在架子上”这样的处所补语。"}, "sentence_index": 0, "correct_answer": "列"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在墙上列了一扇窗。", "explanation": "这里应该用〈开〉。开窗要用“开”，列只表示按次序排开或写出事项，不能用于窗户。"}, {"text": "他把书列进书包。", "explanation": "这里应该用〈放〉。把书装进书包要用“放”，列强调按次序排开，不用于装进某处。"}, {"text": "地上列着很多垃圾。", "explanation": "这里应该用〈堆〉。乱堆的东西不能用“列”，列强调整齐地排开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91288, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "列", "is_correct": true, "explanation": "正确：列（liè）指按次序排开或陈列。"}, {"text": "界", "is_correct": false, "explanation": "jiè 与 liè 声母不同（j / l），意思是界限。"}, {"text": "切", "is_correct": false, "explanation": "qiè 与 liè 声母不同（q / l），意思是切开。"}, {"text": "略", "is_correct": false, "explanation": "lüè 与 liè 韵母不同（üe / ie），意思是省略。"}, {"text": "利", "is_correct": false, "explanation": "lì（第四声）与 liè 韵母不同（i / ie），声调相同，意思是利益。"}], "explanations": {"列": "正确：列（liè）指按次序排开或陈列。", "界": "jiè 与 liè 声母不同（j / l），意思是界限。", "切": "qiè 与 liè 声母不同（q / l），意思是切开。", "略": "lüè 与 liè 韵母不同（üe / ie），意思是省略。", "利": "lì（第四声）与 liè 韵母不同（i / ie），声调相同，意思是利益。"}, "sentence_index": null, "correct_answer": "列"}, "level_3": {"options": [{"text": "列", "is_correct": true, "explanation": "正确：“价格表上列着”指按次序写出或排列在表上，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出声音演唱，不能用于价格表上的内容。"}, {"text": "跑", "is_correct": false, "explanation": "配价：“跑”是不及物动词，不能带“每种菜的价钱”作宾语。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“笑”指面部表情或发出笑声，价钱不能用“笑”来呈现。"}], "explanations": {"列": "正确：“价格表上列着”指按次序写出或排列在表上，符合句意。", "唱": "语义：“唱”指发出声音演唱，不能用于价格表上的内容。", "跑": "配价：“跑”是不及物动词，不能带“每种菜的价钱”作宾语。", "笑": "语义：“笑”指面部表情或发出笑声，价钱不能用“笑”来呈现。"}, "sentence_index": 6, "correct_answer": "列"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把碗列干净了，然后出门。", "explanation": "这里应该用〈洗〉。把碗弄干净要用“洗”，列指按次序排开，不能表示清洁。"}, {"text": "他在树下列了一个苹果。", "explanation": "这里应该用〈摘〉。从树上取下苹果要用“摘”，列表示按次序排开或写出事项，不能用于采摘。"}, {"text": "他饿了，在厨房里列了一碗面。", "explanation": "这里应该用〈煮〉。列是按次序排开，不能表示烹饪；做面要用“煮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91288, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师让大家在操场上列为一排。", "corrected_sentence": "老师让大家在操场上列成一排。", "error_description": "错误在结果补语“为”。“列成一排”表示排成某种行列，应该用“成”，不能用“为”，即“列成一排”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91288, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "货架上的饮料列很整齐。", "corrected_sentence": "货架上的饮料列得很整齐。", "error_description": "错误在程度补语的标记。“列”后带补语“很整齐”，要用结构助词“得”连接，应说“列得很整齐”，漏掉“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
