INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91301, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一遍又一遍地做。", "primary_collocate": null, "pronunciation": "fǎn fù", "ipa": "fan˨˩ fu˥˩", "syllable_count": 2, "sentences": [{"text": "为了考试，我反复练习写汉字。", "target_word": "反复", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写完以后，请你反复检查。", "target_word": "反复", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把这段话反复读了很多遍。", "target_word": "反复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们反复听这段录音。", "target_word": "反复", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个动作他反复做了十次。", "target_word": "反复", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我反复试了几次才成功。", "target_word": "反复", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她反复擦着桌子，擦得很干净。", "target_word": "反复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学语言要反复听，反复说。", "target_word": "反复", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他反复洗了三次手。", "target_word": "反复", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做实验时，我们要反复测量。", "target_word": "反复", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "反反复复", "label": "重叠"}], "register": "中性", "sense_fingerprint": "把同一个动作一遍又一遍地做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2c74ad2-a0ce-4c65-9079-a2c0132d354e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91301, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "反复", "is_correct": true, "explanation": "正确答案：反复 fǎnfù，意思是一遍又一遍地做。"}, {"text": "反序", "is_correct": false, "explanation": "xù（第四声）与 fù（第四声）声母不同，意思是颠倒次序。"}, {"text": "反顾", "is_correct": false, "explanation": "gù（第四声）与 fù（第四声）声母不同，意思是回头看。"}, {"text": "反目", "is_correct": false, "explanation": "mù（第四声）与 fù（第四声）声母不同，意思是彼此翻脸、决裂。"}], "explanations": {"反复": "正确答案：反复 fǎnfù，意思是一遍又一遍地做。", "反序": "xù（第四声）与 fù（第四声）声母不同，意思是颠倒次序。", "反顾": "gù（第四声）与 fù（第四声）声母不同，意思是回头看。", "反目": "mù（第四声）与 fù（第四声）声母不同，意思是彼此翻脸、决裂。"}, "sentence_index": null, "correct_answer": "反复"}, "level_3": {"options": [{"text": "不用", "is_correct": false, "explanation": "语义：“不用”表示不必，与“为了考试”的目的矛盾。"}, {"text": "反复", "is_correct": true, "explanation": "正确：“反复”表示一遍又一遍地练习，符合“为了考试”的语境。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多与否定词连用，不与表示进行的“练习”搭配。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示与预期相反，与“为了考试”的正常目的不协调。"}], "explanations": {"不用": "语义：“不用”表示不必，与“为了考试”的目的矛盾。", "反复": "正确：“反复”表示一遍又一遍地练习，符合“为了考试”的语境。", "从来": "搭配：“从来”多与否定词连用，不与表示进行的“练习”搭配。", "偏偏": "语义：“偏偏”表示与预期相反，与“为了考试”的正常目的不协调。"}, "sentence_index": 0, "correct_answer": "反复"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师让我们反复听一遍这段录音。", "explanation": "这里应该用〈再〉。“反复”表示多次重复，只听一遍要用“再”。"}, {"text": "这个动作他反复做了一次就完成了。", "explanation": "“反复”强调多次重复，与“做了一次就完成了”矛盾，应去掉“反复”。"}, {"text": "这是她第一次反复去海边。", "explanation": "“第一次”表示只有一次，与“反复”的多次重复矛盾，这里应去掉“反复”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91301, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "反复", "is_correct": true, "explanation": "正确答案：反复 fǎnfù，意思是一遍又一遍地做。"}, {"text": "繁复", "is_correct": false, "explanation": "fán（第二声）与 fǎn（第三声）声调不同，意思是繁多复杂。"}, {"text": "反腐", "is_correct": false, "explanation": "fǔ（第三声）与 fù（第四声）声调不同，意思是反对腐败。"}, {"text": "翻覆", "is_correct": false, "explanation": "fān（第一声）与 fǎn（第三声）声调不同，意思是翻转、倾覆。"}], "explanations": {"反复": "正确答案：反复 fǎnfù，意思是一遍又一遍地做。", "繁复": "fán（第二声）与 fǎn（第三声）声调不同，意思是繁多复杂。", "反腐": "fǔ（第三声）与 fù（第四声）声调不同，意思是反对腐败。", "翻覆": "fān（第一声）与 fǎn（第三声）声调不同，意思是翻转、倾覆。"}, "sentence_index": null, "correct_answer": "反复"}, "level_3": {"options": [{"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与表示正在进行的“擦着”矛盾。"}, {"text": "反复", "is_correct": true, "explanation": "正确：“反复”表示一遍又一遍地擦，与“擦得很干净”的语境相符。"}, {"text": "一齐", "is_correct": false, "explanation": "搭配：“一齐”要求多个主体，与单数的“她”不搭配。"}, {"text": "互相", "is_correct": false, "explanation": "搭配：“互相”需要彼此双方，与单数的“她”及“擦桌子”不搭配。"}], "explanations": {"从不": "语义：“从不”表示从来没有，与表示正在进行的“擦着”矛盾。", "反复": "正确：“反复”表示一遍又一遍地擦，与“擦得很干净”的语境相符。", "一齐": "搭配：“一齐”要求多个主体，与单数的“她”不搭配。", "互相": "搭配：“互相”需要彼此双方，与单数的“她”及“擦桌子”不搭配。"}, "sentence_index": 6, "correct_answer": "反复"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他反复考上了大学。", "explanation": "“考上大学”是一次性的结果，不能重复发生，“反复”用于此处不当，应去掉“反复”。"}, {"text": "这个实验他只做了一次，却反复做了一次。", "explanation": "“只做了一次”与“反复”的多次重复矛盾，这里应去掉“反复”。"}, {"text": "这座桥是十年前反复建成的。", "explanation": "“建成”是一次完成的结果，不能用“反复”修饰，这里应直接说“建成”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91301, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈反复得叮嘱我注意安全。", "corrected_sentence": "妈妈反复叮嘱我注意安全。", "error_description": "错误：“得”插在副词“反复”和动词“叮嘱”之间。正确：“反复”直接修饰动词，应说“反复叮嘱”，不加“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91301, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师反复的解释这道题。", "corrected_sentence": "老师反复解释这道题。", "error_description": "错误：“的”插在副词“反复”和动词“解释”之间。正确：“反复”直接修饰动词，应说“反复解释”，“的”不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
