INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91308, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91308, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "兴趣、爱好相同的人。", "primary_collocate": null, "pronunciation": "tóng hào", "ipa": "tʰʊŋ˧˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我在网上认识了很多同好。", "target_word": "同好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和同好们一起去看展览。", "target_word": "同好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组里都是爱画画的同好。", "target_word": "同好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末，同好们会在公园见面。", "target_word": "同好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找几位爱跑步的同好。", "target_word": "同好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这里，你可以遇到很多同好。", "target_word": "同好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己的书借给了同好。", "target_word": "同好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同好们都喜欢听老歌。", "target_word": "同好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我多年的同好，也是朋友。", "target_word": "同好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这些同好每个月聚一次。", "target_word": "同好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "书面", "sense_fingerprint": "兴趣爱好相同的人，指志同道合的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2c74ad2-a0ce-4c65-9079-a2c0132d354e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91308, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "邻居", "is_correct": false, "explanation": "语义：“邻居”指住得近的人，与“在网上认识”的语境矛盾。"}, {"text": "同好", "is_correct": true, "explanation": "正确：“同好”指兴趣爱好相同的人，与“在网上认识”搭配自然。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“认识”的对象应是人，“作业”不能被认识。"}, {"text": "同桌", "is_correct": false, "explanation": "语义：“同桌”指同班并坐的同学，与“在网上认识”的语境不符。"}], "explanations": {"邻居": "语义：“邻居”指住得近的人，与“在网上认识”的语境矛盾。", "同好": "正确：“同好”指兴趣爱好相同的人，与“在网上认识”搭配自然。", "作业": "搭配：“认识”的对象应是人，“作业”不能被认识。", "同桌": "语义：“同桌”指同班并坐的同学，与“在网上认识”的语境不符。"}, "sentence_index": 0, "correct_answer": "同好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他和我从小一起长大，是多年的同好。", "explanation": "这里应该用〈同伴〉。“同好”指爱好相同的人，从小一起长大的伙伴应说“同伴”。"}, {"text": "公园里有很多同好的花，开得很漂亮。", "explanation": "“同好”只指有相同爱好的人，不能用来修饰“花”。"}, {"text": "我们班的同好下午要考试。", "explanation": "这里应该用〈同学〉。“同好”指爱好相同的人，同班的人应说“同学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91308, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "搭配：“借给”的对象应是人，“桌子”不能接受借书。"}, {"text": "同好", "is_correct": true, "explanation": "正确：“同好”指兴趣爱好相同的人，可以接受借书，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”不能接受别人借出的书，与“借给”搭配不当。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：借书给小偷不合常理，与整句的语境不协调。"}], "explanations": {"桌子": "搭配：“借给”的对象应是人，“桌子”不能接受借书。", "同好": "正确：“同好”指兴趣爱好相同的人，可以接受借书，符合句意。", "空气": "搭配：“空气”不能接受别人借出的书，与“借给”搭配不当。", "小偷": "语义：借书给小偷不合常理，与整句的语境不协调。"}, "sentence_index": 6, "correct_answer": "同好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个人是同好，一起抢了银行。", "explanation": "这里应该用〈同伙〉。“同好”指爱好相同的人，不含贬义，一起作案的人应说“同伙”。"}, {"text": "这两家公司是同好，竞争非常激烈。", "explanation": "这里应该用〈同行〉。“同好”指爱好相同的人，两家公司属于同一行业，应说“同行”。"}, {"text": "我和同好每天一起上班，两人一起骗了老板的钱。", "explanation": "这里应该用〈同伙〉。“同好”指爱好相同的人，不能指一起作案的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91308, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末，我和几只同好去爬山。", "corrected_sentence": "周末，我和几位同好去爬山。", "error_description": "错误：量词“只”用于“同好”。“同好”指人，应用量词“位”，说“几位同好”。量词要与名词的类别匹配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91308, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是我的同好的，我们每周一起下棋。", "corrected_sentence": "她是我的同好，我们每周一起下棋。", "error_description": "错误：“的”多余。“我的”已经表示所属，“同好”后面不应再加“的”。正确：“她是我的同好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91309, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
