INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91309, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "动画是用画好的图，一张接一张放出来，看起来会动的片子。", "primary_collocate": null, "pronunciation": "dòng huà", "ipa": "tʊŋ˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "动画里的小猫会说话。", "target_word": "动画", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我妹妹最爱看动画。", "target_word": "动画", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这部动画画得真好看。", "target_word": "动画", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们花了三年才做完这部动画。", "target_word": "动画", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "动画一秒钟要放很多张画。", "target_word": "动画", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看着动画，孩子笑了起来。", "target_word": "动画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部动画我已经看过三遍了。", "target_word": "动画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们放了一部关于海洋的动画。", "target_word": "动画", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "动画不是真人演的，是画出来的。", "target_word": "动画", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把自己画的图做成了一部短动画。", "target_word": "动画", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "動畫", "label": "繁体"}, {"form": "动画片", "label": "复合"}, {"form": "动画电影", "label": "复合"}], "register": "中性", "sense_fingerprint": "把画好的图一张接一张放出来、看起来会动的片子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '155cb381-df48-4f0d-a482-c866d65aa334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91309, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水壶", "is_correct": false, "explanation": "语义：水壶里不会有会说话的小猫，句子说不通。"}, {"text": "动画", "is_correct": true, "explanation": "正确：“动画里的小猫”指动画片中的角色，符合句意。"}, {"text": "牙齿", "is_correct": false, "explanation": "语义：牙齿里不可能藏着会说话的小猫，句子说不通。"}, {"text": "果汁", "is_correct": false, "explanation": "语义：果汁里不会有会说话的小猫，句子说不通。"}], "explanations": {"水壶": "语义：水壶里不会有会说话的小猫，句子说不通。", "动画": "正确：“动画里的小猫”指动画片中的角色，符合句意。", "牙齿": "语义：牙齿里不可能藏着会说话的小猫，句子说不通。", "果汁": "语义：果汁里不会有会说话的小猫，句子说不通。"}, "sentence_index": 0, "correct_answer": "动画"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段动画很动听。", "explanation": "这里应该用〈音乐〉。“动听”形容声音，动画是影片，不能说动听。"}, {"text": "这场动画的舞台很大。", "explanation": "这里应该用〈话剧〉。舞台是话剧的演出场所，动画是影片，不说“舞台很大”。"}, {"text": "他们借了一台动画。", "explanation": "这里量词应该用〈部〉。“台”用于机器、电器，影片要用“部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91309, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地图", "is_correct": false, "explanation": "搭配：“这部”用于影片、书籍等，地图应用“张”。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不能“看过三遍”，句子说不通。"}, {"text": "动画", "is_correct": true, "explanation": "正确：“这部动画”指一部影片，“看过三遍”符合句意。"}, {"text": "雨", "is_correct": false, "explanation": "量词：“这部”用于影片、书籍等，不能用于雨。"}], "explanations": {"地图": "搭配：“这部”用于影片、书籍等，地图应用“张”。", "饼干": "语义：饼干不能“看过三遍”，句子说不通。", "动画": "正确：“这部动画”指一部影片，“看过三遍”符合句意。", "雨": "量词：“这部”用于影片、书籍等，不能用于雨。"}, "sentence_index": 6, "correct_answer": "动画"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部动画的玩家很多。", "explanation": "这里应该用〈游戏〉。玩家是玩游戏的人，动画是影片，应说观众。"}, {"text": "这段动画读起来很有韵味。", "explanation": "这里应该用〈诗歌〉。“读”针对文字，动画是影片，不能说“读”。"}, {"text": "这部动画我弹了好多遍。", "explanation": "这里应该用〈曲子〉。“弹”针对乐器演奏，动画是影片，不能说“弹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91309, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班放了一座新动画。", "corrected_sentence": "我们班放了一部新动画。", "error_description": "量词错误：“动画”应用“部”，“座”用于山、桥、楼等大型固定的物体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91309, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部动画的很有名，大家都知道。", "corrected_sentence": "这部动画很有名，大家都知道。", "error_description": "结构助词错误：“的”使“动画”变成定语，后面缺少中心语，句子不通；“动画很有名”中“很有名”是谓语，不应加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
