INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91310, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91310, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "把一系列画面连续播放，形成运动效果的影片。", "primary_collocate": null, "pronunciation": "dòng huà", "ipa": "tʊŋ˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "我喜欢看动画。", "target_word": "动画", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这部动画很有意思。", "target_word": "动画", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们每天晚上看动画。", "target_word": "动画", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部动画是用电脑做的。", "target_word": "动画", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从小就喜欢画动画。", "target_word": "动画", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末我和弟弟在家看了一部动画。", "target_word": "动画", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部日本动画的故事很感人。", "target_word": "动画", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想学做动画，所以去了北京。", "target_word": "动画", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影院正在放一部新动画。", "target_word": "动画", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部动画里的小狗会说话，大家都喜欢它。", "target_word": "动画", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "動畫", "label": "繁体"}, {"form": "动画片", "label": "复合"}, {"form": "动画电影", "label": "复合"}], "register": "中性", "sense_fingerprint": "由连续播放的画面形成运动效果的影片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '155cb381-df48-4f0d-a482-c866d65aa334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "声音", "is_correct": false, "explanation": "搭配：“看”与“声音”不搭配，声音要用“听”。"}, {"text": "动画", "is_correct": true, "explanation": "正确：“看动画”是常见搭配，指观看动画片，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：味道要用“闻”或“尝”，不能说“看”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见，“看空气”说不通。"}], "explanations": {"声音": "搭配：“看”与“声音”不搭配，声音要用“听”。", "动画": "正确：“看动画”是常见搭配，指观看动画片，符合句意。", "味道": "搭配：味道要用“闻”或“尝”，不能说“看”。", "空气": "语义：空气看不见，“看空气”说不通。"}, "sentence_index": 0, "correct_answer": "动画"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本动画是用纸画的。", "explanation": "这里应该用〈漫画〉。动画是连续播放的影片，不是一本书，应说“漫画”。"}, {"text": "这部动画是演员在舞台上演的。", "explanation": "这里应该用〈话剧〉。动画是画出来的影片，不是舞台上演出的戏，应说“话剧”。"}, {"text": "我买了一把动画。", "explanation": "这里量词应该用〈部〉。动画是影片，“把”用于有柄的器具，影片要用“部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜没有能让人感动的故事，“这部蔬菜的故事”说不通。"}, {"text": "香水", "is_correct": false, "explanation": "量词：“这部”用于影视、书籍等作品，香水应说“这瓶”，句子不成立。"}, {"text": "动画", "is_correct": true, "explanation": "正确：“这部日本动画”指一部日本动画片，其故事很感人，符合句意。"}, {"text": "船", "is_correct": false, "explanation": "搭配：“这部”用于影视、书籍等作品，船要用“艘”。"}], "explanations": {"蔬菜": "语义：蔬菜没有能让人感动的故事，“这部蔬菜的故事”说不通。", "香水": "量词：“这部”用于影视、书籍等作品，香水应说“这瓶”，句子不成立。", "动画": "正确：“这部日本动画”指一部日本动画片，其故事很感人，符合句意。", "船": "搭配：“这部”用于影视、书籍等作品，船要用“艘”。"}, "sentence_index": 6, "correct_answer": "动画"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段动画很好喝。", "explanation": "这里应该用〈饮料〉。“好喝”形容饮品，动画是影片，不能说“好喝”。"}, {"text": "这部动画的关卡很难。", "explanation": "这里应该用〈游戏〉。关卡是游戏的组成部分，动画是影片，没有关卡。"}, {"text": "这段动画读起来很美。", "explanation": "这里应该用〈诗歌〉。“读”针对文字，动画是影片，不能说“读”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师带我们班看了一条动画。", "corrected_sentence": "老师带我们班看了一部动画。", "error_description": "量词错误：“动画”是影片，应用“部”，“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们喜欢那部很新动画。", "corrected_sentence": "孩子们喜欢那部新动画。", "error_description": "程度词错误：“很”不能直接修饰名词前的形容词定语，应说“新动画”，删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91313, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "肯定", "is_correct": true, "explanation": "肯定：与“否定”相对，表示说“是”或认为对，是词典所列的反义词。"}, {"text": "收集", "is_correct": false, "explanation": "收集：与“否定”没有反义关系，只是普通的动作动词。"}, {"text": "参观", "is_correct": false, "explanation": "参观：与“否定”没有反义关系，指去某地看一看。"}, {"text": "制造", "is_correct": false, "explanation": "制造：与“否定”没有反义关系，指做出某种东西。"}], "correct_answer": "肯定", "explanations": {"肯定": "肯定：与“否定”相对，表示说“是”或认为对，是词典所列的反义词。", "收集": "收集：与“否定”没有反义关系，只是普通的动作动词。", "参观": "参观：与“否定”没有反义关系，指去某地看一看。", "制造": "制造：与“否定”没有反义关系，指做出某种东西。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91313, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "肯定", "is_correct": true, "explanation": "肯定：与“否定”相对，表示说“是”或认为对，是词典所列的反义词。"}, {"text": "收获", "is_correct": false, "explanation": "收获：与“否定”没有反义关系，指得到成果。"}, {"text": "散步", "is_correct": false, "explanation": "散步：与“否定”没有反义关系，指随意走动。"}, {"text": "修理", "is_correct": false, "explanation": "修理：与“否定”没有反义关系，指使器物恢复正常。"}], "correct_answer": "肯定", "explanations": {"肯定": "肯定：与“否定”相对，表示说“是”或认为对，是词典所列的反义词。", "收获": "收获：与“否定”没有反义关系，指得到成果。", "散步": "散步：与“否定”没有反义关系，指随意走动。", "修理": "修理：与“否定”没有反义关系，指使器物恢复正常。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91313, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说“不是”，说“不对”。", "primary_collocate": null, "pronunciation": "fǒu dìng", "ipa": "foʊ˨˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师否定了他的答案。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问他是不是病了，他马上否定了。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她摇摇头，否定了我的话。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他连连摆手，否定了我的推测。", "target_word": "否定", "complexity_tier": "T3", "furigana": "fǒu dìng", "sentence_source": "generated"}, {"text": "听到问题，他想也不想就否定了。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈否定了我的想法。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着否定了这个说法。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问他是不是在骗人，他连忙否定。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她否定了朋友的建议。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听完我的话，没有否定，只是笑着点头。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "否定了", "label": "体标"}, {"form": "否定过", "label": "体标"}], "register": "中性", "sense_fingerprint": "开口回答说不是、不对，当面表示不同意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2c74ad2-a0ce-4c65-9079-a2c0132d354e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91313, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "否定", "is_correct": true, "explanation": "否定：表示老师认为答案不对，说“不是”，与句意相符。"}, {"text": "坐", "is_correct": false, "explanation": "搭配：“坐”不能与“答案”搭配，“坐了他的答案”不成立。"}, {"text": "感动", "is_correct": false, "explanation": "配价：“感动”的宾语要是人，不能用“答案”作宾语。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能接“答案”作宾语，“喝了他的答案”不通。"}], "explanations": {"否定": "否定：表示老师认为答案不对，说“不是”，与句意相符。", "坐": "搭配：“坐”不能与“答案”搭配，“坐了他的答案”不成立。", "感动": "配价：“感动”的宾语要是人，不能用“答案”作宾语。", "喝": "搭配：“喝”不能接“答案”作宾语，“喝了他的答案”不通。"}, "sentence_index": 0, "correct_answer": "否定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他否定地答应了朋友的邀请，说周末一定到。", "explanation": "否定与答应矛盾，这里应该用〈欣然〉。"}, {"text": "他一直占着我的座位，不肯让开。", "explanation": "否定针对说法或观点，座位不能否定，这里应该用〈占〉。"}, {"text": "他否定地点了点头。", "explanation": "这里的“否定”表示说“不对”，与“点了点头”表示同意相矛盾，应改用〈摇了摇头〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91313, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "否定", "is_correct": true, "explanation": "否定：表示不认同这个说法，符合句意。"}, {"text": "感激", "is_correct": false, "explanation": "配价：“感激”的对象通常是人或帮助，不能说“感激这个说法”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”通常与歌曲搭配，不能说“唱这个说法”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能接“说法”作宾语，“吃了这个说法”不通。"}], "explanations": {"否定": "否定：表示不认同这个说法，符合句意。", "感激": "配价：“感激”的对象通常是人或帮助，不能说“感激这个说法”。", "唱": "搭配：“唱”通常与歌曲搭配，不能说“唱这个说法”。", "吃": "搭配：“吃”不能接“说法”作宾语，“吃了这个说法”不通。"}, "sentence_index": 6, "correct_answer": "否定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他否定了我送的那束花。", "explanation": "这里应该用〈婉拒〉。否定用于观点、说法，拒绝实物礼物要用婉拒。"}, {"text": "他否定了今天下午的会议。", "explanation": "这里应该用〈取消〉。否定用于观点、说法的不对，会议要取消，不能说否定。"}, {"text": "他否定地笑了笑，说：好的。", "explanation": "否定地修饰“笑”，又说“好的”，表示同意，前后矛盾，这里不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91313, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师否定得他的作文。", "corrected_sentence": "老师否定了他的作文。", "error_description": "错误：“否定”后面用了“得”，应改为“了”。正确：“否定了”表示动作已完成，“得”是补语标记，不能接在动词后直接带宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91313, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有否定了我的建议。", "corrected_sentence": "他没有否定过我的建议。", "error_description": "错误：“没有”否定经历时，“否定”后应用“过”，不能用“了”。正确：“没有否定过”，“了”不能与“没有”连用表示未发生的动作。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91314, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "肯定", "is_correct": true, "explanation": "肯定：与“否定”相对，表示认为对、予以承认，是词典所列的反义词。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：与“否定”没有反义关系，指到外地游览。"}, {"text": "收藏", "is_correct": false, "explanation": "收藏：与“否定”没有反义关系，指把物品保存起来。"}, {"text": "搜索", "is_correct": false, "explanation": "搜索：与“否定”没有反义关系，指到处寻找。"}], "correct_answer": "肯定", "explanations": {"肯定": "肯定：与“否定”相对，表示认为对、予以承认，是词典所列的反义词。", "旅行": "旅行：与“否定”没有反义关系，指到外地游览。", "收藏": "收藏：与“否定”没有反义关系，指把物品保存起来。", "搜索": "搜索：与“否定”没有反义关系，指到处寻找。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91314, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "肯定", "is_correct": true, "explanation": "肯定：与“否定”相对，表示认为对、予以承认，是词典所列的反义词。"}, {"text": "收拾", "is_correct": false, "explanation": "收拾：与“否定”没有反义关系，指整理、料理。"}, {"text": "漫步", "is_correct": false, "explanation": "漫步：与“否定”没有反义关系，指慢慢地散步。"}, {"text": "修补", "is_correct": false, "explanation": "修补：与“否定”没有反义关系，指修理破损的地方。"}], "correct_answer": "肯定", "explanations": {"肯定": "肯定：与“否定”相对，表示认为对、予以承认，是词典所列的反义词。", "收拾": "收拾：与“否定”没有反义关系，指整理、料理。", "漫步": "漫步：与“否定”没有反义关系，指慢慢地散步。", "修补": "修补：与“否定”没有反义关系，指修理破损的地方。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91314, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "不承认事物存在或不赞成；与“肯定”相对。", "primary_collocate": null, "pronunciation": "fǒu dìng", "ipa": "foʊ˨˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我们不能否定他的努力。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他否定了这个计划。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人否定这个办法的作用。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要因为一次错误就否定自己。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生否定了这种说法。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的结果否定了他们的看法。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都肯定他的做法，没人否定。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她否定了过去的生活方式。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不能完全否定这个方法。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩，没有人能否定。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "否定了", "label": "体标"}, {"form": "否定过", "label": "体标"}], "register": "中性", "sense_fingerprint": "不承认某事物存在或价值，不赞成，与肯定相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2c74ad2-a0ce-4c65-9079-a2c0132d354e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91314, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "否定", "is_correct": true, "explanation": "否定：表示不承认努力的价值，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“努力”搭配，“吃他的努力”不成立。"}, {"text": "感动", "is_correct": false, "explanation": "配价：“感动”的宾语要是人，“努力”不能作宾语。"}, {"text": "制造", "is_correct": false, "explanation": "搭配：“制造”可接“困难”等，不能说“制造他的努力”。"}], "explanations": {"否定": "否定：表示不承认努力的价值，符合句意。", "吃": "搭配：“吃”不能与“努力”搭配，“吃他的努力”不成立。", "感动": "配价：“感动”的宾语要是人，“努力”不能作宾语。", "制造": "搭配：“制造”可接“困难”等，不能说“制造他的努力”。"}, "sentence_index": 0, "correct_answer": "否定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她否定了我送给她的花。", "explanation": "这里应该用〈婉拒〉。否定指否认观点或价值，花是实物，要用婉拒。"}, {"text": "她听到这个消息，否定地跳了起来。", "explanation": "否定不能修饰“跳”这样的动作，这里应该用〈激动〉。"}, {"text": "大家都否定他的努力，纷纷表示赞同。", "explanation": "这里应该用〈肯定〉。否定表示不承认价值，与“纷纷表示赞同”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91314, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "否定", "is_correct": true, "explanation": "否定：表示不认同，与前句“肯定”形成对照，符合句意。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”与“肯定他的做法”的语境无关，句意不通。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”与“肯定”的对比无关，句意不通。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能与“做法”发生动宾关系，句意不通。"}], "explanations": {"否定": "否定：表示不认同，与前句“肯定”形成对照，符合句意。", "哭": "语义：“哭”与“肯定他的做法”的语境无关，句意不通。", "睡": "语义：“睡”与“肯定”的对比无关，句意不通。", "游泳": "配价：“游泳”是不及物动词，不能与“做法”发生动宾关系，句意不通。"}, "sentence_index": 6, "correct_answer": "否定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他否定了昨天的天气。", "explanation": "这里应该用〈讨论〉。否定针对观点、价值的不承认，天气是现象，不能否定。"}, {"text": "这把椅子否定了我的请求。", "explanation": "否定的动作要由人来做，椅子不能否定请求，这里应该用〈拒绝〉。"}, {"text": "这盆花很漂亮，她否定地看了又看。", "explanation": "否定不能修饰“看”，这里应该用〈仔细〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们不能了否定你的想法。", "corrected_sentence": "我们不能否定你的想法。", "error_description": "“了”不能插在“不能”与“否定”之间，应写作“不能否定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他否定了掉我的计划。", "corrected_sentence": "他否定掉了我的计划。", "error_description": "“掉”是结果补语，应紧跟动词，写作“否定掉了”，“了”不能放在“掉”前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
