INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91325, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "难过或没办法的时候，叹出来的声音。", "primary_collocate": null, "pronunciation": "āi", "ipa": "aɪ˥", "syllable_count": 1, "sentences": [{"text": "唉，今天又下雨了。", "target_word": "唉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唉，我的手机又坏了。", "target_word": "唉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他叹了口气说：“唉，没办法。”", "target_word": "唉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唉，作业还有这么多。", "target_word": "唉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“唉，我又没考好。”小明说。", "target_word": "唉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唉，我真不知道怎么办。", "target_word": "唉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看着空房子，说：“唉！”", "target_word": "唉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唉，朋友都走了，我一个人真难过。", "target_word": "唉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唉，这么好的东西，坏了。", "target_word": "唉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唉，钱不够，只好不买了。", "target_word": "唉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "唉声叹气", "label": "复合"}], "register": "口语", "sense_fingerprint": "难过或无奈时叹气的声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daefa5e4-da06-49ae-91b6-3464485ab917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91325, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "唉", "is_correct": true, "explanation": "唉（āi，第一声）：叹词，表示难过或没办法时叹出的声音。"}, {"text": "爱", "is_correct": false, "explanation": "ài（第四声）与 āi（第一声）声调不同，意思是爱。"}, {"text": "矮", "is_correct": false, "explanation": "ǎi（第三声）与 āi（第一声）声调不同，意思是矮。"}, {"text": "挨", "is_correct": false, "explanation": "ái（第二声）与 āi（第一声）声调不同，意思是挨。"}, {"text": "开", "is_correct": false, "explanation": "kāi 比 āi 多了声母 k，意思是打开。"}, {"text": "呆", "is_correct": false, "explanation": "dāi 比 āi 多了声母 d，意思是呆板。"}], "explanations": {"唉": "唉（āi，第一声）：叹词，表示难过或没办法时叹出的声音。", "爱": "ài（第四声）与 āi（第一声）声调不同，意思是爱。", "矮": "ǎi（第三声）与 āi（第一声）声调不同，意思是矮。", "挨": "ái（第二声）与 āi（第一声）声调不同，意思是挨。", "开": "kāi 比 āi 多了声母 k，意思是打开。", "呆": "dāi 比 āi 多了声母 d，意思是呆板。"}, "sentence_index": null, "correct_answer": "唉"}, "level_3": {"options": [{"text": "唉", "is_correct": true, "explanation": "叹词「唉」表示难过或无奈，与「又下雨了」的无奈语气相合。"}, {"text": "哇", "is_correct": false, "explanation": "语义：「哇」表示惊喜或赞叹，与「又下雨了」的无奈语气不合。"}, {"text": "嘻嘻", "is_correct": false, "explanation": "语义：「嘻嘻」是轻笑声，与「又下雨了」的无奈语气不合。"}, {"text": "哇塞", "is_correct": false, "explanation": "语域：「哇塞」是很随意的口语感叹，表达兴奋，与这句的无奈语气不合。"}], "explanations": {"唉": "叹词「唉」表示难过或无奈，与「又下雨了」的无奈语气相合。", "哇": "语义：「哇」表示惊喜或赞叹，与「又下雨了」的无奈语气不合。", "嘻嘻": "语义：「嘻嘻」是轻笑声，与「又下雨了」的无奈语气不合。", "哇塞": "语域：「哇塞」是很随意的口语感叹，表达兴奋，与这句的无奈语气不合。"}, "sentence_index": 0, "correct_answer": "唉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "唉，这个蛋糕真漂亮！", "explanation": "这里应该用〈哇〉。唉表示难过或无奈，赞叹漂亮时要用〈哇〉。"}, {"text": "唉，我们班考了第一名！", "explanation": "这里应该用〈太好了〉。唉表示难过或无奈，表达为成绩高兴时要用〈太好了〉。"}, {"text": "唉，今天阳光真好，我们去公园吧！", "explanation": "这里应该用〈太好了〉。唉表示难过或无奈，与阳光好、去公园的愉快语境不合，表达高兴时应改用〈太好了〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91325, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "唉", "is_correct": true, "explanation": "唉（āi，第一声）：叹词，表示难过或没办法时叹出的声音。"}, {"text": "癌", "is_correct": false, "explanation": "ái（第二声）与 āi（第一声）声调不同，意思是癌症。"}, {"text": "碍", "is_correct": false, "explanation": "ài（第四声）与 āi（第一声）声调不同，意思是妨碍。"}, {"text": "该", "is_correct": false, "explanation": "gāi 比 āi 多了声母 g，意思是应该。"}], "explanations": {"唉": "唉（āi，第一声）：叹词，表示难过或没办法时叹出的声音。", "癌": "ái（第二声）与 āi（第一声）声调不同，意思是癌症。", "碍": "ài（第四声）与 āi（第一声）声调不同，意思是妨碍。", "该": "gāi 比 āi 多了声母 g，意思是应该。"}, "sentence_index": null, "correct_answer": "唉"}, "level_3": {"options": [{"text": "唉", "is_correct": true, "explanation": "叹词「唉」表示难过或无奈，与「空房子」的孤寂感相合。"}, {"text": "哈哈", "is_correct": false, "explanation": "语义：「哈哈」是笑声，与看着空房子的伤感不合。"}, {"text": "喂", "is_correct": false, "explanation": "语用：「喂」是打招呼或呼唤别人的用语，与看着空房子的伤感不合。"}, {"text": "嗨", "is_correct": false, "explanation": "语义：「嗨」是招呼或兴奋时的感叹，与看着空房子的伤感不合。"}], "explanations": {"唉": "叹词「唉」表示难过或无奈，与「空房子」的孤寂感相合。", "哈哈": "语义：「哈哈」是笑声，与看着空房子的伤感不合。", "喂": "语用：「喂」是打招呼或呼唤别人的用语，与看着空房子的伤感不合。", "嗨": "语义：「嗨」是招呼或兴奋时的感叹，与看着空房子的伤感不合。"}, "sentence_index": 6, "correct_answer": "唉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "唉，尊敬的各位来宾，欢迎大家光临本店！", "explanation": "这里是迎宾致辞，应表达热情的问候。唉表示难过或无奈，与这种语气相反，不能用。"}, {"text": "唉，小朋友们，早上好！", "explanation": "唉表示叹息或无奈，向小朋友问候应是轻快热情的语气，不能用唉。"}, {"text": "尊敬的王教授：唉，您的来信已经收到。", "explanation": "唉表示叹息，书信中的礼貌告知应是平和的客套语气，不能用叹息，应去掉唉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91325, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "唉了，他又迟到了。", "corrected_sentence": "唉，他又迟到了。", "error_description": "叹词「唉」后面不能加「了」。正确写法是「唉，他又迟到了。」，「了」是动态助词，不能直接加在叹词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
