INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91335, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "心里觉得很重要，很关心。", "primary_collocate": null, "pronunciation": "zài hu", "ipa": "tsai˥˩ xu", "syllable_count": 2, "sentences": [{"text": "她很在乎别人对她的看法。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他最在乎的就是家人。", "target_word": "在乎", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈很在乎我的学习成绩。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在乎这份工作，所以每天都很努力。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我知道你在乎我，谢谢你。", "target_word": "在乎", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她很在乎朋友，常常打电话问好。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们很在乎老师的表扬。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛输了，他很难过，因为他太在乎了。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在乎的不是钱，而是大家的尊重。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人最在乎的是孩子过得好不好。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "在乎过", "label": "体标"}, {"form": "满不在乎", "label": "复合"}], "register": "口语", "sense_fingerprint": "在乎：心里觉得重要而关心，如很在乎家人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2beb4a87-1356-4fca-8f26-67e841f14fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91335, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制定", "is_correct": false, "explanation": "语义：“制定”指订立计划、规章，不能用于“看法”。"}, {"text": "在乎", "is_correct": true, "explanation": "在乎：心里看重，很关心，与“别人对她的看法”搭配自然。"}, {"text": "体谅", "is_correct": false, "explanation": "搭配：“体谅”的对象应是人，不能说“体谅看法”。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清理场所或物品，与“看法”不合。"}], "explanations": {"制定": "语义：“制定”指订立计划、规章，不能用于“看法”。", "在乎": "在乎：心里看重，很关心，与“别人对她的看法”搭配自然。", "体谅": "搭配：“体谅”的对象应是人，不能说“体谅看法”。", "打扫": "语义：“打扫”指清理场所或物品，与“看法”不合。"}, "sentence_index": 0, "correct_answer": "在乎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家在乎市中心，交通很方便。", "explanation": "这里应该用〈在〉。在乎（同“在于”）只用于“关键、成败”等抽象词之后，不能表示位于某处。"}, {"text": "我在乎了他一眼，他就低下了头。", "explanation": "这里应该用〈看〉。在乎表示看重、关心，不表示看一眼。"}, {"text": "妈妈把碗在乎在柜子上。", "explanation": "这里应该用〈放〉。在乎表示看重，不表示把东西摆放在某处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91335, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雕刻", "is_correct": false, "explanation": "语义：“雕刻”指在材料上刻出形状，不能用于“表扬”。"}, {"text": "挥舞", "is_correct": false, "explanation": "搭配：“挥舞”的对象是旗子、手臂等具体物，不能说“挥舞表扬”。"}, {"text": "在乎", "is_correct": true, "explanation": "在乎：心里看重，很关心，与“老师的表扬”搭配自然。"}, {"text": "熨烫", "is_correct": false, "explanation": "语义：“熨烫”指用熨斗把衣物烫平，“表扬”不能被熨烫。"}], "explanations": {"雕刻": "语义：“雕刻”指在材料上刻出形状，不能用于“表扬”。", "挥舞": "搭配：“挥舞”的对象是旗子、手臂等具体物，不能说“挥舞表扬”。", "在乎": "在乎：心里看重，很关心，与“老师的表扬”搭配自然。", "熨烫": "语义：“熨烫”指用熨斗把衣物烫平，“表扬”不能被熨烫。"}, "sentence_index": 6, "correct_answer": "在乎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报告他在乎了三天才写完。", "explanation": "这里应该用〈花〉。在乎表示看重，不表示花费时间，应说“花了三天”。"}, {"text": "我很快在乎了问题所在。", "explanation": "这里应该用〈发现〉。在乎表示看重，不表示找到。"}, {"text": "她在乎了一件红裙子去参加晚会。", "explanation": "这里应该用〈穿〉。在乎表示看重、关心，不表示穿着衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91335, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸很在乎过家里的卫生。", "corrected_sentence": "爸爸很在乎家里的卫生。", "error_description": "体标错误：“很”表示程度，与表示经历的“过”不能同现，“很在乎过”不成立，应说“很在乎家里的卫生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91335, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她最在乎了别人的眼光。", "corrected_sentence": "她最在乎别人的眼光。", "error_description": "体标错误：“最在乎”描述的是持续的心理状态，不能与完成体“了”搭配，应去掉“了”，说“她最在乎别人的眼光”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
