INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91336, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91336, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "放在心上；介意。", "primary_collocate": null, "pronunciation": "zài hu", "ipa": "tsai˥˩ xu", "syllable_count": 2, "sentences": [{"text": "别人怎么说，我一点儿也不在乎。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他迟到了几分钟，老师并不在乎。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这点小事，你就别在乎了。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，可他一点也不在乎，照样去跑步。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不在乎衣服贵不贵，只要好看就行。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友开玩笑，他从来都不在乎。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不在乎别人的看法，只做自己想做的事。", "target_word": "在乎", "complexity_tier": "T3", "furigana": "wǒ bú zài hu bié rén de kàn fǎ，zhǐ zuò zì jǐ xiǎng zuò de shì。", "sentence_source": "generated"}, {"text": "他穿得很旧，可是一点也不在乎。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别人笑他，他会在乎吗？", "target_word": "在乎", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "就算有人批评他，他也不在乎。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "在乎过", "label": "体标"}, {"form": "满不在乎", "label": "复合"}], "register": "口语", "sense_fingerprint": "在乎：放在心上、介意，多用于否定，如不在乎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2beb4a87-1356-4fca-8f26-67e841f14fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91336, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在乎", "is_correct": true, "explanation": "“在乎”表示放在心上、介意，与“不”搭配，符合题意。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指在水中前进，与“别人怎么说”的语境无关。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”指快速移动，与“说”的语境不合。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指用水加热食物，与“别人怎么说”的语境不合。"}], "explanations": {"在乎": "“在乎”表示放在心上、介意，与“不”搭配，符合题意。", "游": "语义：“游”指在水中前进，与“别人怎么说”的语境无关。", "跑": "语义：“跑”指快速移动，与“说”的语境不合。", "煮": "语义：“煮”指用水加热食物，与“别人怎么说”的语境不合。"}, "sentence_index": 0, "correct_answer": "在乎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "钥匙在乎抽屉里。", "explanation": "这里应该用〈放〉。“在乎”表示放在心上，不能表示物体的位置，放东西要用“放”。"}, {"text": "杯子在乎桌子上。", "explanation": "这里应该用〈放〉。“在乎”不能表示物体的位置，杯子摆在桌上要用“放”。"}, {"text": "书包在乎椅子上。", "explanation": "这里可用〈搁〉或〈放〉。“在乎”不能表示物体的位置，书包放在椅子上要用这类动词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91336, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在乎", "is_correct": true, "explanation": "“在乎”表示放在心上，与“不”搭配，表示不把别人的看法放在心上，符合题意。"}, {"text": "熨", "is_correct": false, "explanation": "语义：“熨”指用熨斗把衣物烫平，看法不能被熨。"}, {"text": "煎", "is_correct": false, "explanation": "语义：“煎”指用油加热食物，看法不能被煎。"}, {"text": "吵", "is_correct": false, "explanation": "配价：“吵”是不及物动词，不能带“别人的看法”作宾语。"}], "explanations": {"在乎": "“在乎”表示放在心上，与“不”搭配，表示不把别人的看法放在心上，符合题意。", "熨": "语义：“熨”指用熨斗把衣物烫平，看法不能被熨。", "煎": "语义：“煎”指用油加热食物，看法不能被煎。", "吵": "配价：“吵”是不及物动词，不能带“别人的看法”作宾语。"}, "sentence_index": 6, "correct_answer": "在乎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的手机在乎口袋里。", "explanation": "这里应该用〈装〉。“在乎”不能表示物体的位置，手机装在口袋里要用“装”。"}, {"text": "他在乎会场的前排。", "explanation": "这里应该用〈坐〉。“在乎”表示放在心上，不能表示人所处的位置。"}, {"text": "他的篮球在乎箱子里。", "explanation": "这里应该用〈放〉。“在乎”不能表示位置，篮球放在箱子里要用“放”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91336, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一点儿也不不在乎别人的闲话。", "corrected_sentence": "他一点儿也不在乎别人的闲话。", "error_description": "否定词重复：“在乎”前只需一个“不”，应说“一点儿也不在乎”，不能说“不不在乎”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91336, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一直在乎了朋友的感受。", "corrected_sentence": "她一直在乎着朋友的感受。", "error_description": "体标错误：“在乎”表示持续的状态，应用动态助词“着”，说“在乎着朋友的感受”，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91352, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "终", "is_correct": true, "explanation": "“始”与“终”是反义：“始”指开头，“终”指结尾，如“有始有终”。"}, {"text": "看", "is_correct": false, "explanation": "“看”指视觉动作，与“开始”没有反义关系。"}, {"text": "留", "is_correct": false, "explanation": "“留”指停留或保存，与“开始”没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”指进食，与“开始”没有反义关系。"}], "correct_answer": "终", "explanations": {"终": "“始”与“终”是反义：“始”指开头，“终”指结尾，如“有始有终”。", "看": "“看”指视觉动作，与“开始”没有反义关系。", "留": "“留”指停留或保存，与“开始”没有反义关系。", "吃": "“吃”指进食，与“开始”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91352, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "终", "is_correct": true, "explanation": "“始”与“终”是反义：“始”指开头，“终”指结尾，如“有始有终”。"}, {"text": "坐", "is_correct": false, "explanation": "“坐”指身体停留在椅子等物上，与“开始”没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”指快速移动，与“开始”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”指书写文字，与“开始”没有反义关系。"}], "correct_answer": "终", "explanations": {"终": "“始”与“终”是反义：“始”指开头，“终”指结尾，如“有始有终”。", "坐": "“坐”指身体停留在椅子等物上，与“开始”没有反义关系。", "跑": "“跑”指快速移动，与“开始”没有反义关系。", "写": "“写”指书写文字，与“开始”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91352, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开始；起头。", "primary_collocate": null, "pronunciation": "shǐ", "ipa": "ʂɻ̩˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个故事始于一个雨天。", "target_word": "始", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春节的习俗始于很久以前。", "target_word": "始", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的旅行始于北京。", "target_word": "始", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条河始于西边的雪山。", "target_word": "始", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一切都始于一个小小的想法。", "target_word": "始", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的成功始于每天早起。", "target_word": "始", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这段友谊始于小学。", "target_word": "始", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "会议始于下午两点，止于五点。", "target_word": "始", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项比赛始于一百多年前。", "target_word": "始", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场大雪始于昨天晚上。", "target_word": "始", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "开始", "label": "复合"}, {"form": "起始", "label": "复合"}], "register": "书面语", "sense_fingerprint": "始：开始、起头，常见于“始于…”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2beb4a87-1356-4fca-8f26-67e841f14fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91352, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "始", "is_correct": true, "explanation": "正确答案。“始”读 shǐ（第三声），意思是开始。"}, {"text": "是", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是“是”。"}, {"text": "事", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是“事情”。"}, {"text": "市", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是“城市”。"}, {"text": "石", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，意思是“石头”。"}], "explanations": {"始": "正确答案。“始”读 shǐ（第三声），意思是开始。", "是": "shì（第四声）与 shǐ（第三声）声调不同，意思是“是”。", "事": "shì（第四声）与 shǐ（第三声）声调不同，意思是“事情”。", "市": "shì（第四声）与 shǐ（第三声）声调不同，意思是“城市”。", "石": "shí（第二声）与 shǐ（第三声）声调不同，意思是“石头”。"}, "sentence_index": null, "correct_answer": "始"}, "level_3": {"options": [{"text": "始", "is_correct": true, "explanation": "“始于”表示开始于某个时间或地点，与题干“故事”的开端语境相符。"}, {"text": "属", "is_correct": false, "explanation": "搭配：“属于”表示归属，不能说故事属于一个雨天。"}, {"text": "归", "is_correct": false, "explanation": "语义：“归于”指最终归向或归属，与故事的开端不合。"}, {"text": "集", "is_correct": false, "explanation": "语义：“集于”指聚集，故事不能聚集在一个雨天。"}], "explanations": {"始": "“始于”表示开始于某个时间或地点，与题干“故事”的开端语境相符。", "属": "搭配：“属于”表示归属，不能说故事属于一个雨天。", "归": "语义：“归于”指最终归向或归属，与故事的开端不合。", "集": "语义：“集于”指聚集，故事不能聚集在一个雨天。"}, "sentence_index": 0, "correct_answer": "始"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛始于终点。", "explanation": "“始于”后要接起点，“终点”是结束的地方，不能作起点。"}, {"text": "这段友谊始于结束。", "explanation": "“始于”后要接起点，“结束”是终点，不能作起点。"}, {"text": "这段旅程始于结局。", "explanation": "“始于”后要接起点，“结局”是结束的状态，不能作起点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91352, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "始", "is_correct": true, "explanation": "正确答案。“始”读 shǐ（第三声），意思是开始。"}, {"text": "世", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是“世界”。"}, {"text": "试", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是“尝试”。"}, {"text": "十", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，意思是“数字十”。"}, {"text": "室", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是“房间”。"}], "explanations": {"始": "正确答案。“始”读 shǐ（第三声），意思是开始。", "世": "shì（第四声）与 shǐ（第三声）声调不同，意思是“世界”。", "试": "shì（第四声）与 shǐ（第三声）声调不同，意思是“尝试”。", "十": "shí（第二声）与 shǐ（第三声）声调不同，意思是“数字十”。", "室": "shì（第四声）与 shǐ（第三声）声调不同，意思是“房间”。"}, "sentence_index": null, "correct_answer": "始"}, "level_3": {"options": [{"text": "始", "is_correct": true, "explanation": "“始于”表示开始于某个时间，与题干“友谊”的开端语境相符。"}, {"text": "落", "is_correct": false, "explanation": "语义：“落于”指降落、落在某处，友谊不能落在小学。"}, {"text": "置", "is_correct": false, "explanation": "搭配：“置于”用于物体的放置，友谊不能被放置于小学。"}, {"text": "陷", "is_correct": false, "explanation": "语义：“陷于”指陷入某种困境，与友谊开始于小学的语境不合。"}], "explanations": {"始": "“始于”表示开始于某个时间，与题干“友谊”的开端语境相符。", "落": "语义：“落于”指降落、落在某处，友谊不能落在小学。", "置": "搭配：“置于”用于物体的放置，友谊不能被放置于小学。", "陷": "语义：“陷于”指陷入某种困境，与友谊开始于小学的语境不合。"}, "sentence_index": 6, "correct_answer": "始"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们的爱情始于告别。", "explanation": "“始于”后要接起点，“告别”是结束，不能作起点。"}, {"text": "这份工作始于退休。", "explanation": "“始于”后要接起点，“退休”是结束，不能作起点。"}, {"text": "这个故事始于谢幕。", "explanation": "“始于”后要接起点，“谢幕”是演出结束的时候，不能作起点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场比赛始在下午两点。", "corrected_sentence": "这场比赛始于下午两点。", "error_description": "搭配错误：“始”后面的介词应为“于”，说“始于某时”，不能说“始在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晚会始七点半。", "corrected_sentence": "晚会始于七点半。", "error_description": "介词缺失：“始”后接时间须用介词“于”，应说“始于七点半”，不能省去“于”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91363, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "热闹", "is_correct": true, "explanation": "反义：“热闹”与“寂寞”相对，指人多、有生气，正是“身边没有人陪”的反面。"}, {"text": "聪明", "is_correct": false, "explanation": "无反义关系：“聪明”形容头脑灵活，与“寂寞”的情感义没有相对关系。"}, {"text": "整齐", "is_correct": false, "explanation": "无反义关系：“整齐”形容摆放规整，不是“寂寞”的反义词。"}, {"text": "明亮", "is_correct": false, "explanation": "无反义关系：“明亮”形容光线充足，与“寂寞”的情感义没有相对关系。"}], "correct_answer": "热闹", "explanations": {"热闹": "反义：“热闹”与“寂寞”相对，指人多、有生气，正是“身边没有人陪”的反面。", "聪明": "无反义关系：“聪明”形容头脑灵活，与“寂寞”的情感义没有相对关系。", "整齐": "无反义关系：“整齐”形容摆放规整，不是“寂寞”的反义词。", "明亮": "无反义关系：“明亮”形容光线充足，与“寂寞”的情感义没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91363, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "热闹", "is_correct": true, "explanation": "反义：“热闹”与“寂寞”相对，指有人陪伴、气氛活跃，与“身边没有人说话”正好相反。"}, {"text": "干净", "is_correct": false, "explanation": "无反义关系：“干净”指没有灰尘或污物，与“寂寞”的情感义无关。"}, {"text": "高大", "is_correct": false, "explanation": "无反义关系：“高大”形容体型，与“寂寞”没有相对关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "无反义关系：“漂亮”形容外貌美好，与“寂寞”没有相对关系。"}], "correct_answer": "热闹", "explanations": {"热闹": "反义：“热闹”与“寂寞”相对，指有人陪伴、气氛活跃，与“身边没有人说话”正好相反。", "干净": "无反义关系：“干净”指没有灰尘或污物，与“寂寞”的情感义无关。", "高大": "无反义关系：“高大”形容体型，与“寂寞”没有相对关系。", "漂亮": "无反义关系：“漂亮”形容外貌美好，与“寂寞”没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91363, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "身边没有人陪，心里空空的。", "primary_collocate": null, "pronunciation": "jì mò", "ipa": "tɕi˥˩ mwo˥˩", "syllable_count": 2, "sentences": [{"text": "朋友都回家了，我一个人很寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个人住在大城市，常常觉得寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都去上学了，奶奶在家很寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末没有人找我玩，我有点寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上他一个人吃饭，感到很寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你寂寞的时候，可以给我打电话。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国第一个月，我很想家，也很寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都走了，宿舍里只有我，真寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他养了一只猫，不再寂寞了。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人身边没有人说话，心里很寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "身边没有人陪伴，心里空虚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a2dbba0-d718-455c-a394-e29e30cffffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91363, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寂寞", "is_correct": true, "explanation": "正确：“寂寞”表示身边没有人陪、心里空虚，与“朋友都回家了，我一个人”的语境相符。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指人多、气氛活跃，与“我一个人”的语境相矛盾。"}, {"text": "拥挤", "is_correct": false, "explanation": "搭配：“拥挤”说人多、空间挤，不能用来形容“我一个人”的状态。"}, {"text": "喧闹", "is_correct": false, "explanation": "语义：“喧闹”指声音大、人声嘈杂，与“朋友都回家了”之后只剩我一个人的情形不符。"}], "explanations": {"寂寞": "正确：“寂寞”表示身边没有人陪、心里空虚，与“朋友都回家了，我一个人”的语境相符。", "热闹": "语义：“热闹”指人多、气氛活跃，与“我一个人”的语境相矛盾。", "拥挤": "搭配：“拥挤”说人多、空间挤，不能用来形容“我一个人”的状态。", "喧闹": "语义：“喧闹”指声音大、人声嘈杂，与“朋友都回家了”之后只剩我一个人的情形不符。"}, "sentence_index": 0, "correct_answer": "寂寞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影太寂寞了，我看了一半就走了。", "explanation": "这里应该用〈无聊〉。“寂寞”说人身边没人陪、心里空虚，形容电影乏味要用“无聊”。"}, {"text": "这次考试我考得很寂寞。", "explanation": "这里应该用〈不理想〉。“寂寞”指人身边没人陪、心里空虚，评价考试结果要说“考得不理想”。"}, {"text": "比赛赢了，他寂寞得跳了起来。", "explanation": "这里应该用〈兴奋〉。“寂寞”指人孤单空虚，赢球后的激动心情要用“兴奋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91363, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寂寞", "is_correct": true, "explanation": "正确：“寂寞”与“很想家”同属思乡时的孤单心情，与“也很”的并列语气相符。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”描述外貌，与“很想家”的心情无关，读起来不通。"}, {"text": "幽静", "is_correct": false, "explanation": "语义：“幽静”多形容环境或安静的性情，与“很想家”的孤单心情不符，“也很幽静”接在这里意思不合。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，与“很想家”的心情毫不相干，“也很高大”不通。"}], "explanations": {"寂寞": "正确：“寂寞”与“很想家”同属思乡时的孤单心情，与“也很”的并列语气相符。", "漂亮": "体貌：“漂亮”描述外貌，与“很想家”的心情无关，读起来不通。", "幽静": "语义：“幽静”多形容环境或安静的性情，与“很想家”的孤单心情不符，“也很幽静”接在这里意思不合。", "高大": "体貌：“高大”形容身材，与“很想家”的心情毫不相干，“也很高大”不通。"}, "sentence_index": 6, "correct_answer": "寂寞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "图书馆里很寂寞，大家都在认真看书。", "explanation": "这里应该用〈安静〉。“寂寞”指人心里孤单，形容读书的环境要用“安静”。"}, {"text": "上台前，他寂寞得手心直冒汗。", "explanation": "这里应该用〈紧张〉。“寂寞”指人身边没人陪、心里空虚，上台前心里发慌要用“紧张”。"}, {"text": "这道数学题他做得很寂寞。", "explanation": "这里应该用〈做得对〉。“寂寞”指人心里孤单，评价做题情况要说“做得对”或“做得快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91363, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "放假以后，宿舍里很安静，我被寂寞。", "corrected_sentence": "放假以后，宿舍里很安静，我很寂寞。", "error_description": "错误：“寂寞”是形容词，表示心里的状态，不能用“被”构成被动句。应去掉“被”，改为“我很寂寞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91363, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一个人住在老家，寂寞很。", "corrected_sentence": "他一个人住在老家，寂寞得很。", "error_description": "错误：程度补语的标记“得”漏掉了。“寂寞”后要用“得很”作程度补语，应说“寂寞得很”，不能说“寂寞很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91364, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "热闹", "is_correct": true, "explanation": "反义：“热闹”与“寂寞”相对，指人多、有生气，与“冷清孤单”的意思相反。"}, {"text": "精致", "is_correct": false, "explanation": "无反义关系：“精致”形容做工细致，与“寂寞”没有相对关系。"}, {"text": "明亮", "is_correct": false, "explanation": "无反义关系：“明亮”形容光线充足，与“寂寞”的意思不相对。"}, {"text": "结实", "is_correct": false, "explanation": "无反义关系：“结实”形容牢固、强壮，与“寂寞”无关。"}], "correct_answer": "热闹", "explanations": {"热闹": "反义：“热闹”与“寂寞”相对，指人多、有生气，与“冷清孤单”的意思相反。", "精致": "无反义关系：“精致”形容做工细致，与“寂寞”没有相对关系。", "明亮": "无反义关系：“明亮”形容光线充足，与“寂寞”的意思不相对。", "结实": "无反义关系：“结实”形容牢固、强壮，与“寂寞”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91364, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "热闹", "is_correct": true, "explanation": "反义：“热闹”与“寂寞”相对，指生活有人陪伴、气氛活跃，与“很寂寞”相反。"}, {"text": "富有", "is_correct": false, "explanation": "无反义关系：“富有”指资产多或内容丰富，与“寂寞”没有相对关系。"}, {"text": "整洁", "is_correct": false, "explanation": "无反义关系：“整洁”形容干净利落，与“寂寞”无关。"}, {"text": "响亮", "is_correct": false, "explanation": "无反义关系：“响亮”形容声音清楚有力，与“寂寞”没有相对关系。"}], "correct_answer": "热闹", "explanations": {"热闹": "反义：“热闹”与“寂寞”相对，指生活有人陪伴、气氛活跃，与“很寂寞”相反。", "富有": "无反义关系：“富有”指资产多或内容丰富，与“寂寞”没有相对关系。", "整洁": "无反义关系：“整洁”形容干净利落，与“寂寞”无关。", "响亮": "无反义关系：“响亮”形容声音清楚有力，与“寂寞”没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91364, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "孤单冷清，内心感到无依无靠。", "primary_collocate": null, "pronunciation": "jì mò", "ipa": "tɕi˥˩ mwo˥˩", "syllable_count": 2, "sentences": [{"text": "夜深了，街上没有人，显得很寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小村子冬天很寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的夜晚安静又寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他失去了亲人，内心十分寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪地里只有一棵树，看上去很寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她过着寂寞的生活，没有亲人，也没有朋友。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在异乡无依无靠，心里寂寞极了。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大房子里只有老人，冷清又寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的夜里，寂寞的歌声传了过来。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退休以后，他觉得生活很寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "环境冷清孤单，内心无依无靠", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a2dbba0-d718-455c-a394-e29e30cffffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寂寞", "is_correct": true, "explanation": "正确：“寂寞”形容街上没人、冷清孤单，与“街上没有人”相符。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指人多、有生气，与“街上没有人”正好相反。"}, {"text": "拥挤", "is_correct": false, "explanation": "语义：“拥挤”指人或物挤在一起，与“街上没有人”矛盾。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”形容声音乱，与“没有人”所描写的安静场景不搭配。"}], "explanations": {"寂寞": "正确：“寂寞”形容街上没人、冷清孤单，与“街上没有人”相符。", "热闹": "语义：“热闹”指人多、有生气，与“街上没有人”正好相反。", "拥挤": "语义：“拥挤”指人或物挤在一起，与“街上没有人”矛盾。", "嘈杂": "搭配：“嘈杂”形容声音乱，与“没有人”所描写的安静场景不搭配。"}, "sentence_index": 0, "correct_answer": "寂寞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "跑完马拉松，他寂寞得站不起来。", "explanation": "这里应该用〈累〉。“寂寞”指人孤单无依，形容身体劳累要用“累”。"}, {"text": "孩子对新玩具很寂寞。", "explanation": "这里应该用〈好奇〉。“寂寞”指人孤单无依，孩子对新事物的兴趣要用“好奇”。"}, {"text": "这次演讲他讲得很寂寞。", "explanation": "这里应该用〈精彩〉。“寂寞”指人孤单无依，评价演讲好坏要说“讲得精彩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寂寞", "is_correct": true, "explanation": "正确：“寂寞”形容心里孤单、无依无靠，与“在异乡无依无靠”相符。"}, {"text": "富裕", "is_correct": false, "explanation": "语义：“富裕”指物质充足，与“无依无靠”的处境正相反，“心里富裕”与句子的孤单之意矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，用在“心里”上不通。"}, {"text": "庞大", "is_correct": false, "explanation": "体貌：“庞大”形容体积或规模，不能用来形容心里的感受。"}], "explanations": {"寂寞": "正确：“寂寞”形容心里孤单、无依无靠，与“在异乡无依无靠”相符。", "富裕": "语义：“富裕”指物质充足，与“无依无靠”的处境正相反，“心里富裕”与句子的孤单之意矛盾。", "高大": "体貌：“高大”形容身材，用在“心里”上不通。", "庞大": "体貌：“庞大”形容体积或规模，不能用来形容心里的感受。"}, "sentence_index": 6, "correct_answer": "寂寞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的地铁站很寂寞，人很多，声音也很大。", "explanation": "这里应该用〈热闹〉。“寂寞”指冷清、孤单，描写人多声大的场面要用“热闹”。"}, {"text": "这次面试他表现得很寂寞。", "explanation": "这里应该用〈出色〉。“寂寞”指人孤单无依，评价面试表现要用“出色”。"}, {"text": "房东对我很寂寞，见面时总会热情地打招呼。", "explanation": "这里应该用〈热情〉。“寂寞”指人孤单无依，形容对人的态度要用“热情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下了课，校园里没有人，我觉得寂寞很。", "corrected_sentence": "下了课，校园里没有人，我觉得寂寞得很。", "error_description": "错误：程度补语的标记“得”漏掉了。“寂寞”后要用“得很”作程度补语，应说“寂寞得很”，不能说“寂寞很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "节日过后，他一个人在屋里，觉得寂寞很。", "corrected_sentence": "节日过后，他一个人在屋里，觉得寂寞得很。", "error_description": "错误：程度补语的标记“得”漏掉了。“寂寞”后要用“得很”作程度补语，应说“寂寞得很”，不能说“寂寞很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
