INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91374, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "面积单位，边长为一千米的正方形的面积为一平方千米。", "primary_collocate": null, "pronunciation": "píng fāng qiān mǐ", "ipa": "pʰiŋ˧˥ faŋ˥ tɕʰjɛn˥ mi˨˩˦", "syllable_count": 4, "sentences": [{"text": "平方千米是面积单位。", "target_word": "平方千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一平方千米等于一百万平方米。", "target_word": "平方千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园的面积是两平方千米。", "target_word": "平方千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边长一千米的正方形，面积是一平方千米。", "target_word": "平方千米", "complexity_tier": "T3", "furigana": "píng fāng qiān mǐ", "sentence_source": "generated"}, {"text": "平方千米比平方米大得多。", "target_word": "平方千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面积单位里有平方米和平方千米。", "target_word": "平方千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了怎样用平方千米算面积。", "target_word": "平方千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大地图常用平方千米做单位。", "target_word": "平方千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一百万平方米就是一平方千米。", "target_word": "平方千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题的答案要以平方千米为单位。", "target_word": "平方千米", "complexity_tier": "T3", "furigana": "píng fāng qiān mǐ", "sentence_source": "generated"}], "morphological_forms": [{"form": "平方公里", "label": "同义异称"}], "register": "书面", "sense_fingerprint": "面积单位，一千米见方的面积", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a13f3c-7d80-4a9a-8407-2021ae5c1faf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91374, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平方千米", "is_correct": true, "explanation": "正确：平方千米本身就是面积单位，与句中的“面积单位”一致。"}, {"text": "吨", "is_correct": false, "explanation": "语义：吨是重量单位，不是面积单位，与“面积单位”冲突。"}, {"text": "度", "is_correct": false, "explanation": "搭配：“度”多用于温度、角度，不能用作面积单位的名称。"}, {"text": "斤", "is_correct": false, "explanation": "语义：斤是重量单位，句中说的是面积单位，不符。"}], "explanations": {"平方千米": "正确：平方千米本身就是面积单位，与句中的“面积单位”一致。", "吨": "语义：吨是重量单位，不是面积单位，与“面积单位”冲突。", "度": "搭配：“度”多用于温度、角度，不能用作面积单位的名称。", "斤": "语义：斤是重量单位，句中说的是面积单位，不符。"}, "sentence_index": 0, "correct_answer": "平方千米"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间教室的面积是六十平方千米。", "explanation": "这里应该用〈平方米〉。平方千米的面积太大，教室的面积要用平方米来说。"}, {"text": "我家到学校有三平方千米远。", "explanation": "这里应该用〈千米〉。平方千米量的是面积，说两地的距离要用千米。"}, {"text": "他的体重是五十平方千米。", "explanation": "这里应该用〈千克〉。平方千米是面积单位，说体重要用千克。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平方千米", "is_correct": true, "explanation": "正确：句中要填的是面积单位，讲的是面积的计算，“平方千米”正合适。"}, {"text": "升", "is_correct": false, "explanation": "语义：升是容量单位，讲的是面积的算法，不能用“升”。"}, {"text": "公斤", "is_correct": false, "explanation": "语义：公斤是重量单位，与面积计算无关。"}, {"text": "克", "is_correct": false, "explanation": "搭配：“克”多用于很小的重量，不用来指需要计算的面积内容。"}], "explanations": {"平方千米": "正确：句中要填的是面积单位，讲的是面积的计算，“平方千米”正合适。", "升": "语义：升是容量单位，讲的是面积的算法，不能用“升”。", "公斤": "语义：公斤是重量单位，与面积计算无关。", "克": "搭配：“克”多用于很小的重量，不用来指需要计算的面积内容。"}, "sentence_index": 6, "correct_answer": "平方千米"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块菜地有五十平方千米。", "explanation": "这里应该用〈公顷〉。平方千米太大，一块菜地的面积通常用公顷。"}, {"text": "他每天要喝一平方千米的水。", "explanation": "这里应该用〈升〉。平方千米量的是面积，喝的水要用升来计量。"}, {"text": "这个游泳池的容积是五百平方千米。", "explanation": "这里应该用〈立方米〉。平方千米量的是面积，说容积（空间大小）要用立方单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块地有五个平方千米。", "corrected_sentence": "这块地有五平方千米。", "error_description": "错误在“平方千米”前多加了“个”。平方千米本身就是量词，数字后直接接它，应说“五平方千米”，不能说“五个平方千米”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片草地的面积是两块平方千米。", "corrected_sentence": "这片草地的面积是两平方千米。", "error_description": "量词错误：“平方千米”本身就是量词，数字后直接接它，前面不能再加“块”。应说“两平方千米”，不能说“两块平方千米”。正确说法：这片草地的面积是两平方千米。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
