INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91393, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数据处理是用电脑把很多数字整理好。", "primary_collocate": null, "pronunciation": "shù jù chǔ lǐ", "ipa": "ʂu˥˩ tɕy˥˩ ʈʂʰu˨˩˦ li˨˩˦", "syllable_count": 4, "sentences": [{"text": "数据处理要用电脑来做。", "target_word": "数据处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作是做数据处理。", "target_word": "数据处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据处理让表格变得很清楚。", "target_word": "数据处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学会了用电脑做数据处理。", "target_word": "数据处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据处理交给电脑以后，我们省了很多时间。", "target_word": "数据处理", "complexity_tier": "T3", "furigana": "shù jù chǔ lǐ jiāo gěi diàn nǎo yǐ hòu, wǒ men shěng le hěn duō shí jiān。", "sentence_source": "generated"}, {"text": "数据处理以后，我们就能看结果。", "target_word": "数据处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的数据处理工作很多。", "target_word": "数据处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在银行做数据处理的工作。", "target_word": "数据处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的软件能帮你做数据处理。", "target_word": "数据处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据处理做完了，请看这张图。", "target_word": "数据处理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "數據處理", "label": "繁体"}, {"form": "数据处理中心", "label": "复合"}], "register": "中性", "sense_fingerprint": "用电脑整理大量数字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a13f3c-7d80-4a9a-8407-2021ae5c1faf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91393, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "园艺", "is_correct": false, "explanation": "语义：园艺是培育花草树木，不用电脑来做，与“用电脑来做”冲突。"}, {"text": "数据处理", "is_correct": true, "explanation": "正确：指用电脑整理大量数字，与“用电脑来做”相符。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪是做饭菜，与用电脑整理数字无关，不能用电脑来做。"}, {"text": "手工", "is_correct": false, "explanation": "搭配：“手工”指用手制作的活，与“用电脑来做”搭配不当。"}], "explanations": {"园艺": "语义：园艺是培育花草树木，不用电脑来做，与“用电脑来做”冲突。", "数据处理": "正确：指用电脑整理大量数字，与“用电脑来做”相符。", "烹饪": "语义：烹饪是做饭菜，与用电脑整理数字无关，不能用电脑来做。", "手工": "搭配：“手工”指用手制作的活，与“用电脑来做”搭配不当。"}, "sentence_index": 0, "correct_answer": "数据处理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一名数据处理，每天整理表格。", "explanation": "这里应该用〈数据员〉。数据处理指整理数字的过程，不指人，不能用“一名”来数。"}, {"text": "公司建了一个数据处理来存放客户信息。", "explanation": "这里应该用〈数据库〉。数据库用来存放信息，数据处理是整理数字的过程，不能用来存放。"}, {"text": "他拨通了数据处理。", "explanation": "这里应该用〈电话〉。拨通的是电话，数据处理是过程，不能被拨打。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91393, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数据处理", "is_correct": true, "explanation": "正确：公司的数据处理工作指用电脑整理数字的工作，与“工作很多”相符。"}, {"text": "家务", "is_correct": false, "explanation": "语义：家务属于家庭内部的事，不是公司的工作，与“公司的”冲突。"}, {"text": "登山", "is_correct": false, "explanation": "语义：登山是户外运动，不是公司的工作，与“公司的”冲突。"}, {"text": "农活", "is_correct": false, "explanation": "搭配：“农活”指田间的劳作，与“公司的……工作”搭配不当。"}], "explanations": {"数据处理": "正确：公司的数据处理工作指用电脑整理数字的工作，与“工作很多”相符。", "家务": "语义：家务属于家庭内部的事，不是公司的工作，与“公司的”冲突。", "登山": "语义：登山是户外运动，不是公司的工作，与“公司的”冲突。", "农活": "搭配：“农活”指田间的劳作，与“公司的……工作”搭配不当。"}, "sentence_index": 6, "correct_answer": "数据处理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我吃了一顿数据处理，很饱。", "explanation": "这里应该用〈饭〉。数据处理是整理数字的过程，不能吃。"}, {"text": "他写了一首数据处理。", "explanation": "这里应该用〈诗〉。数据处理是过程，不是作品，不能用来写。"}, {"text": "她露出了灿烂的数据处理。", "explanation": "这里应该用〈笑容〉。露出的是笑容，数据处理是过程，不能被露出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91393, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只数据处理很顺利。", "corrected_sentence": "这次数据处理很顺利。", "error_description": "量词错误：“数据处理”是过程，应用量词“次”，不能用“只”（“只”多用于动物等）。正确说法：这次数据处理很顺利。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91393, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们需要先数据处理。", "corrected_sentence": "我们需要先做数据处理。", "error_description": "漏掉动词：“数据处理”前应加动词“做”，应说“先做数据处理”，不能直接说“先数据处理”。正确说法：我们需要先做数据处理。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
