INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91396, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在打斗或比赛中无法战胜对方。", "primary_collocate": null, "pronunciation": "dǎ bu guò", "ipa": "ta˨˩ pu kuo˥˩", "syllable_count": 3, "sentences": [{"text": "我们队打不过他们队。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛，我们恐怕打不过。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人打不过三个人。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方是冠军，我们打不过。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乒乓球我总是打不过他。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗打不过大狗，跑开了。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我练了很久，还是打不过他。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受了伤，打不过对手了。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个拳手太厉害，大家都打不过他。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打不过就跑，别硬打。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打得过", "label": "肯定式"}], "register": "口语", "sense_fingerprint": "在打架或比赛中不能战胜对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2c74ad2-a0ce-4c65-9079-a2c0132d354e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91396, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打不过", "is_correct": true, "explanation": "打不过：在比赛中无法战胜对方，符合句意。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”不是比赛中的较量方式，句意不通。"}, {"text": "亲吻", "is_correct": false, "explanation": "语义：“亲吻”与比赛的胜负无关，句意不通。"}, {"text": "支持", "is_correct": false, "explanation": "语义：“支持”是帮助对方，与比赛胜负无关，句意不通。"}], "explanations": {"打不过": "打不过：在比赛中无法战胜对方，符合句意。", "咬": "语义：“咬”不是比赛中的较量方式，句意不通。", "亲吻": "语义：“亲吻”与比赛的胜负无关，句意不通。", "支持": "语义：“支持”是帮助对方，与比赛胜负无关，句意不通。"}, "sentence_index": 0, "correct_answer": "打不过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛，我们终于打不过对手，拿到了冠军。", "explanation": "这里应该用〈战胜〉。打不过表示败给对方，与“拿到了冠军”的结果矛盾。"}, {"text": "这块石头打不过那棵大树。", "explanation": "这里应该用〈比不过〉。打不过指较量中败给对方，石头和树没有较量，只能说比不过。"}, {"text": "这门课我打不过，只好重修。", "explanation": "这里应该用〈考不过〉。打不过用于较量，考试不及格要用考不过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打不过", "is_correct": true, "explanation": "打不过：在较量中不能胜过对方，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能接人作宾语表示较量，“吃他”不成立。"}, {"text": "钻研", "is_correct": false, "explanation": "配价：“钻研”的宾语是学问或技术，不能说“钻研他”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不与人组成较量关系，“唱他”不成立。"}], "explanations": {"打不过": "打不过：在较量中不能胜过对方，符合句意。", "吃": "搭配：“吃”不能接人作宾语表示较量，“吃他”不成立。", "钻研": "配价：“钻研”的宾语是学问或技术，不能说“钻研他”。", "唱": "搭配：“唱”不与人组成较量关系，“唱他”不成立。"}, "sentence_index": 6, "correct_answer": "打不过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月的销售额打不过上个月。", "explanation": "这里应该用〈超过〉。打不过用于较量，业绩、数量的比较要用超过。"}, {"text": "这么多作业，我打不过。", "explanation": "这里应该用〈做不完〉。打不过用于较量，作业做不完要说做不完。"}, {"text": "我们打不过那班火车。", "explanation": "这里应该用〈赶不上〉。打不过用于较量，没赶上车要用赶不上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们队这次打不过了他们队。", "corrected_sentence": "我们队这次打不过他们队。", "error_description": "可能补语“打不过”后面不能直接加“了”，应写作“打不过他们队”；“了”放在可能补语后会使句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我弟弟能打不过邻居家的孩子。", "corrected_sentence": "我弟弟打不过邻居家的孩子。", "error_description": "“能”与可能补语“打不过”语义矛盾（两者都表示能力），不能同时使用，应去掉“能”，写作“我弟弟打不过邻居家的孩子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '994ee0e9-d586-44bf-b1f0-d8a963353b06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91403, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平静", "is_correct": true, "explanation": "反义：“平静”指情绪不激动，与“愤怒”相对。"}, {"text": "漂亮", "is_correct": false, "explanation": "无关：“漂亮”形容外貌，与“愤怒”不构成反义。"}, {"text": "坚硬", "is_correct": false, "explanation": "无关：“坚硬”形容质地，与情绪无关。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”指明白，不是与“愤怒”相对的词。"}], "correct_answer": "平静", "explanations": {"平静": "反义：“平静”指情绪不激动，与“愤怒”相对。", "漂亮": "无关：“漂亮”形容外貌，与“愤怒”不构成反义。", "坚硬": "无关：“坚硬”形容质地，与情绪无关。", "清楚": "无关：“清楚”指明白，不是与“愤怒”相对的词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91403, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平静", "is_correct": true, "explanation": "反义：“平静”指情绪不激动，与“愤怒”相对。"}, {"text": "轻巧", "is_correct": false, "explanation": "无关：“轻巧”形容重量或动作，与“愤怒”不构成反义。"}, {"text": "柔软", "is_correct": false, "explanation": "无关：“柔软”形容质地，与情绪无关。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”形容光线或眼神，不是与“愤怒”相对的词。"}], "correct_answer": "平静", "explanations": {"平静": "反义：“平静”指情绪不激动，与“愤怒”相对。", "轻巧": "无关：“轻巧”形容重量或动作，与“愤怒”不构成反义。", "柔软": "无关：“柔软”形容质地，与情绪无关。", "明亮": "无关：“明亮”形容光线或眼神，不是与“愤怒”相对的词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91403, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "愤怒是非常非常生气的样子。", "primary_collocate": null, "pronunciation": "fèn nù", "ipa": "fən˥˩ nu˥˩", "syllable_count": 2, "sentences": [{"text": "他愤怒地看着那个人。", "target_word": "愤怒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，大家都很愤怒。", "target_word": "愤怒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她愤怒的样子让孩子们很害怕。", "target_word": "愤怒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他愤怒地摔门走了。", "target_word": "愤怒", "complexity_tier": "T3", "furigana": "tā fèn nù de shuāi mén zǒu le", "sentence_source": "generated"}, {"text": "老板愤怒地把杯子放在桌上。", "target_word": "愤怒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到有人欺负小孩，妈妈十分愤怒。", "target_word": "愤怒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他愤怒极了，大声喊了起来。", "target_word": "愤怒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机们愤怒地按着喇叭。", "target_word": "愤怒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写了一封愤怒的信。", "target_word": "愤怒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很愤怒，一句话也不想说。", "target_word": "愤怒", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "愤怒的", "label": "定语形式"}, {"form": "愤怒地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "非常生气的样子：愤怒地看着、愤怒的样子、十分愤怒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27aa1c00-fc1e-4f9c-85cd-83e1806a40ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91403, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "愤怒", "is_correct": true, "explanation": "正确：“愤怒地看着”指带着怒气看，符合句意。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来描述看的样子。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容身高，不能用来描述看的样子。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：“粗糙”形容质地，不能用来形容看人的样子。"}], "explanations": {"愤怒": "正确：“愤怒地看着”指带着怒气看，符合句意。", "漂亮": "体貌：“漂亮”形容外貌，不能用来描述看的样子。", "矮": "体貌：“矮”形容身高，不能用来描述看的样子。", "粗糙": "语义：“粗糙”形容质地，不能用来形容看人的样子。"}, "sentence_index": 0, "correct_answer": "愤怒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子很愤怒，所以我不想进去。", "explanation": "这里应该用〈阴暗〉。“愤怒”描述的是人的怒气，不能用来形容房间；形容光线不足要用“阴暗”。"}, {"text": "他愤怒地刻苦学习，每天十个小时。", "explanation": "这里应该用〈努力〉。愤怒指强烈的怒气，不能用来形容学习的态度，描述刻苦学习要用“努力”。"}, {"text": "他愤怒地唱着歌回家。", "explanation": "这里应该用〈高兴〉。唱着歌回家是愉快的状态，“愤怒”与之不搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91403, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "愤怒", "is_correct": true, "explanation": "正确：“他愤怒极了”指怒气很大，与“大声喊了起来”相符。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”与后面的“大声喊了起来”矛盾。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容身体，与“大声喊了起来”没有关系。"}, {"text": "冷静", "is_correct": false, "explanation": "语义：“冷静”与“大声喊了起来”的情绪矛盾。"}], "explanations": {"愤怒": "正确：“他愤怒极了”指怒气很大，与“大声喊了起来”相符。", "安静": "语义：“安静”与后面的“大声喊了起来”矛盾。", "瘦": "体貌：“瘦”形容身体，与“大声喊了起来”没有关系。", "冷静": "语义：“冷静”与“大声喊了起来”的情绪矛盾。"}, "sentence_index": 6, "correct_answer": "愤怒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听到这个消息，我愤怒得合不上嘴。", "explanation": "这里应该用〈惊讶〉。合不上嘴表示吃惊，“愤怒”不能用来表示这种反应。"}, {"text": "这块蛋糕很愤怒，大家都抢着吃。", "explanation": "这里应该用〈好吃〉。“愤怒”描述的是人的怒气，不能用来形容蛋糕；形容味道好要用“好吃”。"}, {"text": "这条路很愤怒，车开得很快。", "explanation": "这里应该用〈平坦〉。“愤怒”描述的是人的怒气，不能用来形容道路；形容路面平整要用“平坦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91403, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他愤怒的把门关上了。", "corrected_sentence": "他愤怒地把门关上了。", "error_description": "错误在“的”。“愤怒”在这里修饰动词“关”，作状语，应该用“地”，不能用“的”，即“愤怒地把门关上了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91403, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到这个消息，他很愤怒极了。", "corrected_sentence": "听到这个消息，他愤怒极了。", "error_description": "错误在“很”。“愤怒极了”已用“极了”表示程度，前面不能再加“很”，应删去“很”，即“他愤怒极了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
