INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91437, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "能想出法子，把难事做成。", "primary_collocate": null, "pronunciation": "yǒu bàn fǎ", "ipa": "jou˨˩˦ pan˥˩ fa˨˩˦", "syllable_count": 3, "sentences": [{"text": "王经理真有办法，一天就把货找到了。", "target_word": "有办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很有办法，再难的事也能做成。", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都说小李有办法，让生意好起来了。", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈最有办法，什么难题都难不倒她。", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板很有办法，买到了最难买的票。", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你真有办法，这么快就修好了电脑。", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一点儿也不笨，做起事来很有办法。", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我朋友很有办法，总能找到便宜的机票。", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁最有办法，谁就能把这件事办成。", "target_word": "有办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都夸他有办法，把旧房子变成了新家。", "target_word": "有办法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没办法", "label": "否定"}, {"form": "没有办法", "label": "否定"}], "register": "口语", "sense_fingerprint": "有办法|属性|形容人能干、会想法子办成难事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e70502b-b805-4b8c-a302-573ca6cc38cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91437, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有办法", "is_correct": true, "explanation": "正确。「有办法」指能想出法子把事办成，与后句「一天就把货找到了」相符。"}, {"text": "没办法", "is_correct": false, "explanation": "语义：「没办法」表示想不出法子，与后句「一天就把货找到了」矛盾。"}, {"text": "懒", "is_correct": false, "explanation": "语义：「懒」与后句「一天就把货找到了」的高效不符，前后矛盾。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：「胖」描写外形，不能说明办事能力，与后句无关。"}], "explanations": {"有办法": "正确。「有办法」指能想出法子把事办成，与后句「一天就把货找到了」相符。", "没办法": "语义：「没办法」表示想不出法子，与后句「一天就把货找到了」矛盾。", "懒": "语义：「懒」与后句「一天就把货找到了」的高效不符，前后矛盾。", "胖": "体貌：「胖」描写外形，不能说明办事能力，与后句无关。"}, "sentence_index": 0, "correct_answer": "有办法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子很有办法，四条腿又结实又稳。", "explanation": "这里应该用〈结实〉。「有办法」说的是人的能力，不用来形容物品的质地。"}, {"text": "这首歌很有办法，大家都喜欢听。", "explanation": "这里应该用〈有名〉。「有办法」说的是人的能力，不用来形容歌曲出名。"}, {"text": "这个周末的天气很有办法，又冷又下雨。", "explanation": "这里应该用〈糟糕〉。「有办法」说的是人能想出法子，不用来形容天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91437, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有办法", "is_correct": true, "explanation": "正确。「有办法」说人做事有方法，与前句「一点儿也不笨」及后半句「做起事来」相符。"}, {"text": "有空", "is_correct": false, "explanation": "语义：「有空」指有闲暇，与「做起事来」的方式无关，句子不通。"}, {"text": "有钱", "is_correct": false, "explanation": "语义：金钱与「做起事来」的方式无关，句子意思不通。"}, {"text": "有病", "is_correct": false, "explanation": "体貌：「有病」指身体不适，不能描述做事的方式，与「不笨」矛盾。"}], "explanations": {"有办法": "正确。「有办法」说人做事有方法，与前句「一点儿也不笨」及后半句「做起事来」相符。", "有空": "语义：「有空」指有闲暇，与「做起事来」的方式无关，句子不通。", "有钱": "语义：金钱与「做起事来」的方式无关，句子意思不通。", "有病": "体貌：「有病」指身体不适，不能描述做事的方式，与「不笨」矛盾。"}, "sentence_index": 6, "correct_answer": "有办法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张纸很有办法，又白又厚。", "explanation": "这里应该用〈厚实〉。「有办法」说的是人能想出法子，不用来形容纸张。"}, {"text": "他前几天有办法，一直在家休息。", "explanation": "这里应该用〈有病〉。「有办法」指能解决问题，不能用来说身体不适。"}, {"text": "我今天有办法，不能去了。", "explanation": "这里应该用〈有事〉。「有办法」不表示有事情要做，这句话前后不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91437, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小张没办法，三天就把这台机器修好了。", "corrected_sentence": "小张有办法，三天就把这台机器修好了。", "error_description": "否定词用错：表示能想出办法、把事做成要用「有办法」；「没办法」表示想不出办法，与后面「三天就修好了」矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91437, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不有办法，把这件事办得很顺利。", "corrected_sentence": "他很有办法，把这件事办得很顺利。", "error_description": "否定词用错：「有」的否定应说「没有」，不能用「不」否定「有办法」。此处应为程度副词「很」，即「很有办法」，表示能干、会想办法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
