INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91442, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "按月给的零用钱或钱财。", "primary_collocate": null, "pronunciation": "yuè qián", "ipa": "ɥe˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "妈妈每月给我两百块月钱。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷给孙子的月钱不多。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明用月钱买了一个玩具。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的月钱一个星期就花完了。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，月钱要自己学会存。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟想要多一点月钱。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把月钱放进小盒子里。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上大学以后，爸爸每月寄月钱给我。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月爸爸没给我月钱。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都等着发月钱。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "月钱：家里长辈按月给孩子的零用钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4bdefeb-1e1d-4048-a525-662a680312a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91442, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "月钱", "is_correct": true, "explanation": "月钱指长辈按月给孩子的零用钱，是本题的正确答案。"}, {"text": "余钱", "is_correct": false, "explanation": "余钱（yú qián）与月钱（yuè qián）的韵母和声调都不同，意思是剩下的钱。"}, {"text": "月琴", "is_correct": false, "explanation": "qín 与 qián 韵母不同（-in 与 -ian），声调相同，意思是月琴，一种弹拨乐器。"}, {"text": "血钱", "is_correct": false, "explanation": "xuè（第四声）与 yuè（第四声）声母不同，意思是用残害人命等手段换来的钱。"}], "explanations": {"月钱": "月钱指长辈按月给孩子的零用钱，是本题的正确答案。", "余钱": "余钱（yú qián）与月钱（yuè qián）的韵母和声调都不同，意思是剩下的钱。", "月琴": "qín 与 qián 韵母不同（-in 与 -ian），声调相同，意思是月琴，一种弹拨乐器。", "血钱": "xuè（第四声）与 yuè（第四声）声母不同，意思是用残害人命等手段换来的钱。"}, "sentence_index": null, "correct_answer": "月钱"}, "level_3": {"options": [{"text": "月钱", "is_correct": true, "explanation": "月钱指长辈按月给孩子的零用钱，此处是妈妈每月给我的零用钱，正确。"}, {"text": "罚款", "is_correct": false, "explanation": "语义：罚款是违规后交给对方的钱，妈妈不会因此给我钱，句子不通。"}, {"text": "房租", "is_correct": false, "explanation": "配价：房租是付给房东的，不能说“妈妈给我房租”。"}, {"text": "押金", "is_correct": false, "explanation": "语义：押金是交给对方作保证的钱，不能由妈妈拿来给我。"}], "explanations": {"月钱": "月钱指长辈按月给孩子的零用钱，此处是妈妈每月给我的零用钱，正确。", "罚款": "语义：罚款是违规后交给对方的钱，妈妈不会因此给我钱，句子不通。", "房租": "配价：房租是付给房东的，不能说“妈妈给我房租”。", "押金": "语义：押金是交给对方作保证的钱，不能由妈妈拿来给我。"}, "sentence_index": 0, "correct_answer": "月钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "过年时爷爷给我一笔月钱。", "explanation": "这里应该用〈压岁钱〉。月钱是按月给的零用钱，过年时的红包不能叫月钱。"}, {"text": "他打碎了玻璃，赔了一笔月钱。", "explanation": "这里应该用〈赔偿金〉。月钱是按月给的零用钱，因损坏东西而付的赔偿不能叫月钱。"}, {"text": "妈妈给了我一台月钱。", "explanation": "这里应该用〈份〉或〈笔〉。〈台〉用于机器、电器等，不能用来量“月钱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91442, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月钱", "is_correct": true, "explanation": "月钱是长辈给孩子的零用钱，可以装进小盒子里，正确。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子太大，放不进小盒子里，句子不通。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海无法装进小盒子里，与“放进小盒子里”不合。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指人的身材，不是能放进盒子的东西。"}], "explanations": {"月钱": "月钱是长辈给孩子的零用钱，可以装进小盒子里，正确。", "房子": "语义：房子太大，放不进小盒子里，句子不通。", "大海": "语义：大海无法装进小盒子里，与“放进小盒子里”不合。", "身高": "体貌：身高指人的身材，不是能放进盒子的东西。"}, "sentence_index": 6, "correct_answer": "月钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校每学期给他发一笔月钱。", "explanation": "这里应该用〈奖学金〉。月钱是按月给的零用钱，学校每学期发的奖学金不能叫月钱。"}, {"text": "他闯红灯，被交警罚了一笔月钱。", "explanation": "这里应该用〈罚款〉。月钱是按月给的零用钱，交通违章的罚款不能叫月钱。"}, {"text": "她一下子收到了一只月钱。", "explanation": "这里应该用〈份〉或〈笔〉。〈只〉用于动物或成对物品中的一个，不能用来量“月钱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈每个月给我一台月钱。", "corrected_sentence": "妈妈每个月给我一笔月钱。", "error_description": "量词错误：“月钱”前应用“笔”，“台”用于机器、电器等，不能修饰“月钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈月钱每个月都按时给我。", "corrected_sentence": "妈妈的月钱每个月都按时给我。", "error_description": "领属标记错误：“妈妈月钱”漏了“的”，应说“妈妈的月钱”，名词修饰名词表示领属时要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
