INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91448, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "泛指物理中的波动，如声波、光波、电波。", "primary_collocate": null, "pronunciation": "bō", "ipa": "pwo˥", "syllable_count": 1, "sentences": [{"text": "声音是以波的形式传播的。", "target_word": "波", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光也是一种波。", "target_word": "波", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种波要靠空气或水之类的介质才能传播。", "target_word": "波", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种波的速度很快。", "target_word": "波", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "手机用的是一种看不见的波。", "target_word": "波", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图上的波一高一低，很有规律。", "target_word": "波", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水里的波和空气里的波都能传递能量。", "target_word": "波", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同一种波在不同的介质里，速度往往不一样。", "target_word": "波", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个实验可以让我们看见波是怎么传的。", "target_word": "波", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震时，地下会传出很强的波。", "target_word": "波", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "波浪", "label": "复合"}, {"form": "声波", "label": "复合"}, {"form": "电波", "label": "复合"}], "register": "中性", "sense_fingerprint": "波：物理中的波动（声、光、电）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '476a3295-ccc1-45f7-ab1b-c537dc3fa42a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91448, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "波", "is_correct": true, "explanation": "正确。波（bō）指物理中的波动，如声波、光波。"}, {"text": "博", "is_correct": false, "explanation": "博（bó）与波（bō）声调不同，意思是博大、博士。"}, {"text": "颇", "is_correct": false, "explanation": "颇（pō）与波（bō）的声母送气不同（p 与 b），意思是相当、很。"}, {"text": "泼", "is_correct": false, "explanation": "泼（pō）与波（bō）的声母送气不同（p 与 b），意思是泼洒。"}], "explanations": {"波": "正确。波（bō）指物理中的波动，如声波、光波。", "博": "博（bó）与波（bō）声调不同，意思是博大、博士。", "颇": "颇（pō）与波（bō）的声母送气不同（p 与 b），意思是相当、很。", "泼": "泼（pō）与波（bō）的声母送气不同（p 与 b），意思是泼洒。"}, "sentence_index": null, "correct_answer": "波"}, "level_3": {"options": [{"text": "波", "is_correct": true, "explanation": "正确。“声音是以波的形式传播的”是物理上的说法，符合句意。"}, {"text": "水", "is_correct": false, "explanation": "语义：声音不以“水”的形式传播，“以水的形式”与物理常识不符，句意不通。"}, {"text": "纸", "is_correct": false, "explanation": "语义：“纸”不是声音的传播形式，句子不通。"}, {"text": "线", "is_correct": false, "explanation": "搭配：“以线的形式”不能用来说明声音的传播方式，搭配不当。"}], "explanations": {"波": "正确。“声音是以波的形式传播的”是物理上的说法，符合句意。", "水": "语义：声音不以“水”的形式传播，“以水的形式”与物理常识不符，句意不通。", "纸": "语义：“纸”不是声音的传播形式，句子不通。", "线": "搭配：“以线的形式”不能用来说明声音的传播方式，搭配不当。"}, "sentence_index": 0, "correct_answer": "波"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根波的速度很快。", "explanation": "这里应该用〈种〉。“根”用于细长的条状物，不能修饰波，应说“这种波”。"}, {"text": "这块波的速度很快。", "explanation": "这里应该用〈种〉。“块”用于块状的东西，不能修饰波，应说“这种波”。"}, {"text": "这座波的速度很快。", "explanation": "这里应该用〈种〉。“座”用于山、楼等大型固定的东西，不能修饰波，应说“这种波”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91448, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "波", "is_correct": true, "explanation": "正确。波（bō）指物理中的波动，如声波、光波。"}, {"text": "伯", "is_correct": false, "explanation": "伯（bó）与波（bō）声调不同，意思是伯伯、父亲的哥哥。"}, {"text": "脖", "is_correct": false, "explanation": "脖（bó）与波（bō）声调不同，意思是脖子。"}, {"text": "坡", "is_correct": false, "explanation": "坡（pō）与波（bō）的声母送气不同（p 与 b），意思是山坡。"}], "explanations": {"波": "正确。波（bō）指物理中的波动，如声波、光波。", "伯": "伯（bó）与波（bō）声调不同，意思是伯伯、父亲的哥哥。", "脖": "脖（bó）与波（bō）声调不同，意思是脖子。", "坡": "坡（pō）与波（bō）的声母送气不同（p 与 b），意思是山坡。"}, "sentence_index": null, "correct_answer": "波"}, "level_3": {"options": [{"text": "波", "is_correct": true, "explanation": "正确。“水里的波和空气里的波都能传递能量”是物理上的说法，符合句意。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不能传递能量，“水里的鱼”与“传递能量”的语境冲突，句子不通。"}, {"text": "石", "is_correct": false, "explanation": "语义：石头不能传递能量，与句子所说的物理现象不符。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“水里的雨”不是常用说法，“雨”不在水中，搭配不当。"}], "explanations": {"波": "正确。“水里的波和空气里的波都能传递能量”是物理上的说法，符合句意。", "鱼": "语义：鱼不能传递能量，“水里的鱼”与“传递能量”的语境冲突，句子不通。", "石": "语义：石头不能传递能量，与句子所说的物理现象不符。", "雨": "搭配：“水里的雨”不是常用说法，“雨”不在水中，搭配不当。"}, "sentence_index": 6, "correct_answer": "波"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在木板上看到一道清楚的波。", "explanation": "这里应该用〈纹理〉。木板表面的纹理要用“纹理”，不用“波”。"}, {"text": "墙上有一只波，很显眼。", "explanation": "这里应该用〈道〉。“只”用于动物或成对的东西，不能修饰波，应说“一道波”。"}, {"text": "他在纸上画了一把波。", "explanation": "这里应该用〈列〉。“把”用于有柄的器具，不能修饰画出的波，应说“一列波”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91448, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这颗波的频率很高。", "corrected_sentence": "这列波的频率很高。", "error_description": "一连串的波用量词“列”，“颗”用于圆粒状的东西，不能修饰波，应改为“这列波”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91448, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种实验能测出很强地波。", "corrected_sentence": "这种实验能测出很强的波。", "error_description": "“很强”修饰名词“波”时应用“的”，用“地”是错误的，应改为“很强的波”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
