INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91455, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她生气了地关上了门。", "corrected_sentence": "她生气地关上了门。", "error_description": "体标位置错误：“生气了”后不能直接接状语“地”修饰动词，“了”表示完成，应去掉，说“她生气地关上了门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
