INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91456, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "因不满意而发怒。", "primary_collocate": null, "pronunciation": "shēng qì", "ipa": "ʂɤŋ˥ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "他对老板的话很不满意，生气地走了。", "target_word": "生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师因为学生迟到而生气。", "target_word": "生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为菜太咸，客人生气了。", "target_word": "生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟弄坏了我的手机，我很生气。", "target_word": "生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顾客对服务不满意，生气了。", "target_word": "生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为输了比赛，生气了一天。", "target_word": "生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对我的成绩不满意，有点生气。", "target_word": "生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不听话，爸爸生气了。", "target_word": "生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这个结果很不满，非常生气。", "target_word": "生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居吵到我睡觉，我真生气。", "target_word": "生气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生气了", "label": "体标（了）"}], "register": "口语", "sense_fingerprint": "生气：因为对人或事不满意而发怒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4bdefeb-1e1d-4048-a525-662a680312a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91456, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生气", "is_correct": true, "explanation": "生气指因不满而发怒，是本题的正确答案。"}, {"text": "升起", "is_correct": false, "explanation": "shēng qǐ（第三声）与 shēng qì（第四声）声调不同，意思是向上升。"}, {"text": "神气", "is_correct": false, "explanation": "shén（第二声）与 shēng（第一声）韵尾不同，意思是精神饱满或得意的样子。"}, {"text": "生机", "is_correct": false, "explanation": "jī（第一声）与 qì（第四声）声母和声调都不同，意思是生命力。"}], "explanations": {"生气": "生气指因不满而发怒，是本题的正确答案。", "升起": "shēng qǐ（第三声）与 shēng qì（第四声）声调不同，意思是向上升。", "神气": "shén（第二声）与 shēng（第一声）韵尾不同，意思是精神饱满或得意的样子。", "生机": "jī（第一声）与 qì（第四声）声母和声调都不同，意思是生命力。"}, "sentence_index": null, "correct_answer": "生气"}, "level_3": {"options": [{"text": "生气", "is_correct": true, "explanation": "生气指因不满而发怒，此处与“很不满意”前后一致，正确。"}, {"text": "快乐", "is_correct": false, "explanation": "语义：前文说“很不满意”，后面用“快乐地走了”，前后矛盾。"}, {"text": "欢笑", "is_correct": false, "explanation": "语义：欢笑表示快乐，与“很不满意”的语境矛盾。"}, {"text": "大量", "is_correct": false, "explanation": "搭配：“大量”修饰数量或规模，不能用来修饰“走”的样子，句子不通。"}], "explanations": {"生气": "生气指因不满而发怒，此处与“很不满意”前后一致，正确。", "快乐": "语义：前文说“很不满意”，后面用“快乐地走了”，前后矛盾。", "欢笑": "语义：欢笑表示快乐，与“很不满意”的语境矛盾。", "大量": "搭配：“大量”修饰数量或规模，不能用来修饰“走”的样子，句子不通。"}, "sentence_index": 0, "correct_answer": "生气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "生日那天，他很生气地吹灭了蜡烛。", "explanation": "这里应该用〈高兴〉。生气表示因不满而发怒，吹蜡烛许愿时的心情应说高兴。"}, {"text": "我的朋友帮我搬了家，我生气地向他道谢。", "explanation": "这里应该用〈感激〉。生气表示因不满而发怒，朋友帮忙后道谢应表示感激。"}, {"text": "他拿到了奖学金，心里很生气。", "explanation": "这里应该用〈骄傲〉。生气表示因不满而发怒，拿到奖学金应当骄傲，不能说生气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91456, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "生气", "is_correct": true, "explanation": "生气指因不满而发怒，是本题的正确答案。"}, {"text": "生意", "is_correct": false, "explanation": "yì（第四声）与 qì（第四声）声母不同，意思是买卖。"}, {"text": "生日", "is_correct": false, "explanation": "rì（第四声）与 qì（第四声）声母不同，意思是出生的那一天。"}, {"text": "生理", "is_correct": false, "explanation": "lǐ（第三声）与 qì（第四声）声母和声调都不同，意思是人体的生理机能。"}], "explanations": {"生气": "生气指因不满而发怒，是本题的正确答案。", "生意": "yì（第四声）与 qì（第四声）声母不同，意思是买卖。", "生日": "rì（第四声）与 qì（第四声）声母不同，意思是出生的那一天。", "生理": "lǐ（第三声）与 qì（第四声）声母和声调都不同，意思是人体的生理机能。"}, "sentence_index": null, "correct_answer": "生气"}, "level_3": {"options": [{"text": "生气", "is_correct": true, "explanation": "生气指因不满而发怒，与“不满意”前后一致，正确。"}, {"text": "兴奋", "is_correct": false, "explanation": "语义：前文说妈妈不满意，“有点兴奋”与之矛盾。"}, {"text": "得意", "is_correct": false, "explanation": "语义：得意表示自豪，前文说不满意，前后不合。"}, {"text": "开朗", "is_correct": false, "explanation": "搭配：“开朗”形容性格，不能用来说一时的心情。"}], "explanations": {"生气": "生气指因不满而发怒，与“不满意”前后一致，正确。", "兴奋": "语义：前文说妈妈不满意，“有点兴奋”与之矛盾。", "得意": "语义：得意表示自豪，前文说不满意，前后不合。", "开朗": "搭配：“开朗”形容性格，不能用来说一时的心情。"}, "sentence_index": 6, "correct_answer": "生气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听到这个好消息，他很生气地跳了起来。", "explanation": "这里应该用〈激动〉。生气表示因不满而发怒，听到好消息时的心情应说激动。"}, {"text": "全家人在一起吃饭，大家都很生气。", "explanation": "这里应该用〈愉快〉。生气表示因不满而发怒，全家团聚的场合不能用生气。"}, {"text": "看到孩子长大懂事，他很生气。", "explanation": "这里应该用〈欣慰〉。生气表示因不满而发怒，看到孩子懂事应感到欣慰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91456, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他生气着，一句话也没说。", "corrected_sentence": "他生着气，一句话也没说。", "error_description": "体标错误：“生气”是离合词，“着”应插在“生”和“气”之间，应说“生着气”，不能说“生气着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91456, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师生气了地批评了他。", "corrected_sentence": "老师生气地批评了他。", "error_description": "体标位置错误：“生气了”后不能直接接状语“地”修饰动词，“了”表示完成，应去掉，说“老师生气地批评了他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
