INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91471, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "经济发展是一个地方的钱和生意越来越多，人们越过越好。", "primary_collocate": null, "pronunciation": "jīng jì fā zhǎn", "ipa": "tɕiŋ˥ tɕi˥˩ fa˥ ʈʂan˨˩˦", "syllable_count": 4, "sentences": [{"text": "这个城市的经济发展很快。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济发展以后，人们的生活好多了。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的家乡经济发展得不错。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的经济发展让很多人有了工作。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路修好以后，小镇的经济发展快了。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了经济发展，这里开了很多新店。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济发展了，大家的钱也多了。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，经济发展带来了新生活。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个地方经济发展慢，年轻人都走了。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得家乡的经济发展怎么样？", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "经济发展：一个地方钱和生意变多，人们生活变好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4bdefeb-1e1d-4048-a525-662a680312a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91471, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气没有快慢，“很快”不能用来修饰天气。"}, {"text": "经济发展", "is_correct": true, "explanation": "正确：经济发展指一个城市钱和生意越来越多，可以说“发展很快”。"}, {"text": "历史", "is_correct": false, "explanation": "语义：历史是过去的事，没有“快”的说法，“这个城市的历史很快”说不通。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“很快”通常修饰“增长”，单说“人口很快”不成立。"}], "explanations": {"天气": "语义：天气没有快慢，“很快”不能用来修饰天气。", "经济发展": "正确：经济发展指一个城市钱和生意越来越多，可以说“发展很快”。", "历史": "语义：历史是过去的事，没有“快”的说法，“这个城市的历史很快”说不通。", "人口": "搭配：“很快”通常修饰“增长”，单说“人口很快”不成立。"}, "sentence_index": 0, "correct_answer": "经济发展"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个省的经济发展很漂亮。", "explanation": "语义：这里误把“经济发展”当成〈外貌〉来用。“经济发展”指地区或国家经济的壮大，不能用来形容外貌；说外表好看要用“漂亮”之类的词。"}, {"text": "我的小狗这几年经济发展得很快。", "explanation": "语义：这里误把“经济发展”当成〈成长〉来用。“经济发展”指地区或国家经济的壮大，小狗长大只能说“长得很快”。"}, {"text": "这把椅子的经济发展很好。", "explanation": "语义：这里误把“经济发展”当成〈状况〉来用。“经济发展”只指地区或国家经济的壮大，不能描述家具；椅子的状况好，应说“状况很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91471, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饥荒", "is_correct": false, "explanation": "语义：饥荒与后半句“大家的钱也多了”矛盾，不能接在这里。"}, {"text": "经济萧条", "is_correct": false, "explanation": "语义：萧条指经济不景气，与“钱也多了”相反。"}, {"text": "经济发展", "is_correct": true, "explanation": "正确：经济发展指经济规模扩大，与“大家的钱也多了”的结果一致。"}, {"text": "窘境", "is_correct": false, "explanation": "语域：窘境偏书面，且带困窘意味，与“钱也多了”不搭。"}], "explanations": {"饥荒": "语义：饥荒与后半句“大家的钱也多了”矛盾，不能接在这里。", "经济萧条": "语义：萧条指经济不景气，与“钱也多了”相反。", "经济发展": "正确：经济发展指经济规模扩大，与“大家的钱也多了”的结果一致。", "窘境": "语域：窘境偏书面，且带困窘意味，与“钱也多了”不搭。"}, "sentence_index": 6, "correct_answer": "经济发展"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你觉得同学的经济发展怎么样？", "explanation": "语义：经济发展指地区或国家的经济，不用于同学这样的个人，这里应该说“经济状况”。"}, {"text": "你觉得这首歌的经济发展怎么样？", "explanation": "语义：这里应该用〈人气〉。“经济发展”专指地区或国家的经济，不能用来评价歌曲受不受欢迎。"}, {"text": "你觉得我的书包的经济发展怎么样？", "explanation": "语义：这里应该用〈质量〉。“经济发展”只指地区或国家的经济，书包的好坏应说“质量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91471, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个地区的一只经济发展很快。", "corrected_sentence": "这个地区的经济发展很快。", "error_description": "错误：在“经济发展”前加了量词“只”。“只”用于动物，经济发展是抽象名词，应直接说“这个地区的经济发展很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91471, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们这个小镇的经济发展了很快。", "corrected_sentence": "我们这个小镇的经济发展得很快。", "error_description": "错误：“经济发展”后的补语要用“得”，不能用“了”。“经济发展了很快”不成立，应说“经济发展得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
