INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91472, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个国家或地区经济规模扩大、水平提高的过程。", "primary_collocate": null, "pronunciation": "jīng jì fā zhǎn", "ipa": "tɕiŋ˥ tɕi˥˩ fa˥ ʈʂan˨˩˦", "syllable_count": 4, "sentences": [{"text": "这个国家的经济发展速度很快。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济发展离不开科学技术。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近年来，该地区的经济发展水平不断提高。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府很重视经济发展和环境保护。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济发展给城市带来了新的机会。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国的经济发展并不一样。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济发展需要稳定的社会环境。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区的经济发展有了很大变化。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教育对经济发展有重要作用。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要保护环境，也要促进经济发展。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "经济发展：国家或地区经济规模扩大、水平提高的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4bdefeb-1e1d-4048-a525-662a680312a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91472, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人口", "is_correct": false, "explanation": "搭配：人口本身没有“速度”，应说“增长速度”。"}, {"text": "经济发展", "is_correct": true, "explanation": "正确：“经济发展速度”指经济规模扩大、水平提高的快慢，与“很快”搭配。"}, {"text": "历史", "is_correct": false, "explanation": "语义：历史是过去的事，没有快慢，“历史速度”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气没有速度，“天气速度很快”不成立。"}], "explanations": {"人口": "搭配：人口本身没有“速度”，应说“增长速度”。", "经济发展": "正确：“经济发展速度”指经济规模扩大、水平提高的快慢，与“很快”搭配。", "历史": "语义：历史是过去的事，没有快慢，“历史速度”说不通。", "天气": "语义：天气没有速度，“天气速度很快”不成立。"}, "sentence_index": 0, "correct_answer": "经济发展"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市的经济发展很漂亮。", "explanation": "语义：这里误把“经济发展”当成〈外貌〉来用。“经济发展”指国家或地区经济规模扩大、水平提高的过程，不能用来形容外貌。"}, {"text": "我的小狗今年经济发展得很好。", "explanation": "语义：这里误把“经济发展”当成〈成长〉来用。“经济发展”只用于国家或地区，小狗长大应说“长得很好”。"}, {"text": "这张桌子的经济发展很好。", "explanation": "语义：这里误把“经济发展”当成〈质量〉来用。“经济发展”指国家或地区经济的壮大，不能描述桌子，桌子的好坏应说“质量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91472, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花朵", "is_correct": false, "explanation": "语义：花朵不需要社会环境，这句话不成立。"}, {"text": "经济发展", "is_correct": true, "explanation": "正确：经济发展需要稳定的社会环境，符合常理。"}, {"text": "睡眠", "is_correct": false, "explanation": "语义：睡眠是个人的生理活动，不需要社会环境。"}, {"text": "语速", "is_correct": false, "explanation": "搭配：“需要稳定的社会环境”的主语应是事业或发展，“语速”与之不搭。"}], "explanations": {"花朵": "语义：花朵不需要社会环境，这句话不成立。", "经济发展": "正确：经济发展需要稳定的社会环境，符合常理。", "睡眠": "语义：睡眠是个人的生理活动，不需要社会环境。", "语速": "搭配：“需要稳定的社会环境”的主语应是事业或发展，“语速”与之不搭。"}, "sentence_index": 6, "correct_answer": "经济发展"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "要保护环境，也要促进这座桥的经济发展。", "explanation": "这里应该用〈建设〉。“经济发展”只用于国家或地区的经济，不能用于一座桥，桥的修建应说“建设”。"}, {"text": "要保护环境，也要促进猫的经济发展。", "explanation": "语义：这里误把“经济发展”当成〈成长〉来用。猫的成长应说“促进猫的成长”，“经济发展”只用于国家或地区。"}, {"text": "要保护环境，也要促进这台电脑的经济发展。", "explanation": "语义：这里误把“经济发展”当成〈性能〉来用。“经济发展”只用于国家或地区，电脑的能力应说“性能”，如“提高电脑的性能”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个省的一只经济发展水平提高了。", "corrected_sentence": "这个省的经济发展水平提高了。", "error_description": "错误：在“经济发展水平”前加了量词“只”。“只”用于动物，应直接说“这个省的经济发展水平提高了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个县的经济发展了很快。", "corrected_sentence": "这个县的经济发展得很快。", "error_description": "错误：补语标记应用“得”，不能用“了”。“经济发展了很快”不成立，应说“经济发展得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
