INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91476, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自己管理自己的事务。", "primary_collocate": null, "pronunciation": "zì zhì", "ipa": "ts˥˩ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这个城市有权自治。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方实行自治，当地人自己管理当地的事务。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个岛一直在自治，不受别人干预。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校让学生自治，由他们管理宿舍。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子实行自治，村务由村民自己决定。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去这里不能自治，现在可以了。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的村子已经自治了很多年。", "target_word": "自治", "complexity_tier": "T3", "furigana": "tāmen de cūnzi yǐjīng zìzhì le hěn duō nián", "sentence_source": "generated"}, {"text": "小区居民自己选人管理，这就是自治。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区希望自治，不愿受外部干预。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学实行自治，校内事务由学校自己管理。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自治了", "label": "体标"}, {"form": "自治过", "label": "体标"}, {"form": "自治县", "label": "复合"}], "register": "正式", "sense_fingerprint": "政治或社会上，地方、团体自行管理本身的事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27aa1c00-fc1e-4f9c-85cd-83e1806a40ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91476, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自治", "is_correct": true, "explanation": "自治是地方或团体自行管理本身的事务。"}, {"text": "资质", "is_correct": false, "explanation": "zī（第一声）与 zì（第四声）声调不同，意思是资质、素质。"}, {"text": "自知", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，意思是自己知道。"}, {"text": "字纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是写过字的纸，多指废纸。"}, {"text": "自指", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是指向自身，较少见。"}], "explanations": {"自治": "自治是地方或团体自行管理本身的事务。", "资质": "zī（第一声）与 zì（第四声）声调不同，意思是资质、素质。", "自知": "zhī（第一声）与 zhì（第四声）声调不同，意思是自己知道。", "字纸": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是写过字的纸，多指废纸。", "自指": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是指向自身，较少见。"}, "sentence_index": null, "correct_answer": "自治"}, "level_3": {"options": [{"text": "自治", "is_correct": true, "explanation": "正确。“这个城市有权”后接“自治”，指城市有权自行管理事务，符合句意。"}, {"text": "飞翔", "is_correct": false, "explanation": "语义：城市不会飞翔，“飞翔”只用于有翅膀的生物或飞行器。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：“生锈”指金属被氧化，与“城市”不搭。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：“发芽”多用于植物或种子，不能与“城市”搭配。"}], "explanations": {"自治": "正确。“这个城市有权”后接“自治”，指城市有权自行管理事务，符合句意。", "飞翔": "语义：城市不会飞翔，“飞翔”只用于有翅膀的生物或飞行器。", "生锈": "语义：“生锈”指金属被氧化，与“城市”不搭。", "发芽": "搭配：“发芽”多用于植物或种子，不能与“城市”搭配。"}, "sentence_index": 0, "correct_answer": "自治"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天自治地学习。", "explanation": "这里应该用〈自觉〉。个人主动做事用“自觉”，“自治”指地区或团体自己管理事务。"}, {"text": "他已经能自治生活了。", "explanation": "这里应该用〈自理〉。个人照顾自己的生活用“自理”，“自治”用于地区或团体。"}, {"text": "学校由校长自治。", "explanation": "这里应该用〈管理〉。“由……管理”表示外部人员负责；“自治”是自己管理自己的事，不能由外人负责。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91476, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自治", "is_correct": true, "explanation": "正确。“他们的村子已经……了很多年”后接“自治”，指村子自行管理事务，符合句意。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：“结冰”指液体变成固体，村子不会结冰。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”是人或动物的动作，村子不会睡觉。"}, {"text": "开花", "is_correct": false, "explanation": "搭配：“开花”多用于植物，不搭配“村子”。"}], "explanations": {"自治": "正确。“他们的村子已经……了很多年”后接“自治”，指村子自行管理事务，符合句意。", "结冰": "语义：“结冰”指液体变成固体，村子不会结冰。", "睡觉": "语义：“睡觉”是人或动物的动作，村子不会睡觉。", "开花": "搭配：“开花”多用于植物，不搭配“村子”。"}, "sentence_index": 6, "correct_answer": "自治"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他自治决定去北京工作。", "explanation": "这里应该用〈自主〉。个人自己做决定用“自主”，“自治”指地区或团体自行管理事务。"}, {"text": "他十八岁就自治了。", "explanation": "这里应该用〈自立〉。个人独立、不靠父母用“自立”，“自治”不用于个人。"}, {"text": "他自治留下来帮忙。", "explanation": "这里应该用〈自愿〉。个人主动做某事用“自愿”，“自治”指地区或团体管理自身事务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91476, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个岛曾经自治过过。", "corrected_sentence": "这个岛曾经自治过。", "error_description": "重复错误：错误形式“自治过过”，多写了一个“过”。表示经历的“过”只用一次，应说“曾经自治过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91476, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个镇正在自治过。", "corrected_sentence": "这个镇正在自治。", "error_description": "体标错误：“正在”表示动作进行中，不能与表示经历的“过”同用。应去掉“过”，说“这个镇正在自治”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91487, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "输出", "is_correct": true, "explanation": "反义：输出是把数据从电脑送出，与“输入”方向相反。"}, {"text": "保存", "is_correct": false, "explanation": "不构成反义：保存是把数据存起来，与“输入”不是相对的关系。"}, {"text": "打开", "is_correct": false, "explanation": "不构成反义：打开是启动文件或程序，与“输入”不是相对的关系。"}, {"text": "复制", "is_correct": false, "explanation": "不构成反义：复制是做出一份相同的内容，与“输入”不是相对的关系。"}], "correct_answer": "输出", "explanations": {"输出": "反义：输出是把数据从电脑送出，与“输入”方向相反。", "保存": "不构成反义：保存是把数据存起来，与“输入”不是相对的关系。", "打开": "不构成反义：打开是启动文件或程序，与“输入”不是相对的关系。", "复制": "不构成反义：复制是做出一份相同的内容，与“输入”不是相对的关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91487, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "输出", "is_correct": true, "explanation": "反义：输出是把数据从电脑送出，与“输入”方向相反。"}, {"text": "打印", "is_correct": false, "explanation": "不构成反义：打印是把内容印在纸上，与“输入”不是相对的关系。"}, {"text": "关闭", "is_correct": false, "explanation": "不构成反义：关闭是结束程序或窗口，与“输入”不是相对的关系。"}, {"text": "下载", "is_correct": false, "explanation": "不构成反义：下载是从网上取得文件，与“输入”不是相对的关系。"}], "correct_answer": "输出", "explanations": {"输出": "反义：输出是把数据从电脑送出，与“输入”方向相反。", "打印": "不构成反义：打印是把内容印在纸上，与“输入”不是相对的关系。", "关闭": "不构成反义：关闭是结束程序或窗口，与“输入”不是相对的关系。", "下载": "不构成反义：下载是从网上取得文件，与“输入”不是相对的关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91487, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "输入是把字或数字放进电脑里。", "primary_collocate": null, "pronunciation": "shū rù", "ipa": "ʂu˥ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "请在电脑上输入你的名字。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在输入一个很长的数字。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把电话号码输入了电脑。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她输入汉字很快，一分钟能打六十个。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把课文输入电脑里。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他输入错了一个数字，表格就不对了。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明用拼音输入汉字。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先输入这几个数字，再点一下确定。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电脑里输入过很多字。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天要输入几百个数字。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "输入了", "label": "体标"}, {"form": "输入过", "label": "体标"}, {"form": "输入法", "label": "复合"}, {"form": "輸入", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用键盘把字或数字打进电脑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a13f3c-7d80-4a9a-8407-2021ae5c1faf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91487, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "输入", "is_correct": true, "explanation": "正确：“输入”是用键盘把名字打进电脑，与句中的“在电脑上”搭配。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能用来处理名字。"}, {"text": "种", "is_correct": false, "explanation": "语义：“种”指栽种植物，与在电脑上写名字的动作无关。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”是切开东西，不能用于在电脑上输入名字。"}], "explanations": {"输入": "正确：“输入”是用键盘把名字打进电脑，与句中的“在电脑上”搭配。", "煮": "搭配：“煮”的对象是食物，不能用来处理名字。", "种": "语义：“种”指栽种植物，与在电脑上写名字的动作无关。", "切": "搭配：“切”是切开东西，不能用于在电脑上输入名字。"}, "sentence_index": 0, "correct_answer": "输入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电脑把结果输入到了打印机上。", "explanation": "这里应该用〈输出〉。结果从电脑送到打印机，方向是输出；输入是把数据送进电脑。"}, {"text": "妈妈把饼干输入了盒子里。", "explanation": "这里应该用〈放〉。输入只用于电脑等设备，把饼干放进盒子要用“放”。"}, {"text": "她把汉字输入到了纸上。", "explanation": "这里应该用〈写〉。输入的对象是电脑等设备，在纸上写字要用“写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91487, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "输入", "is_correct": true, "explanation": "正确：句中用拼音把汉字打进电脑，“输入”正合适。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是发出声音，不能用来输入汉字。"}, {"text": "刻", "is_correct": false, "explanation": "搭配：“刻”多用于刻在石头、木头上，不用于拼音输入。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洗的动作，与用拼音输入汉字无关。"}], "explanations": {"输入": "正确：句中用拼音把汉字打进电脑，“输入”正合适。", "唱": "语义：“唱”是发出声音，不能用来输入汉字。", "刻": "搭配：“刻”多用于刻在石头、木头上，不用于拼音输入。", "洗": "语义：“洗”是清洗的动作，与用拼音输入汉字无关。"}, "sentence_index": 6, "correct_answer": "输入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我从网上输入了一首歌。", "explanation": "这里应该用〈下载〉。从网上取得歌曲要用下载，输入是把字或数字送进电脑。"}, {"text": "工人把货物输入了仓库。", "explanation": "这里应该用〈搬〉。输入只用于电脑等系统，把货物搬进仓库要用“搬”。"}, {"text": "他把数字输入了那只猫。", "explanation": "这里应该用〈电脑〉。输入的对象是电脑等设备，动物不能接收数据。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91487, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我输入了过很多文章。", "corrected_sentence": "我输入过很多文章。", "error_description": "错误在“输入”后同时用了“了”和“过”。“了”和“过”不能同时用在同一个动词后，应只说“输入过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91487, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把名字输入给了电脑。", "corrected_sentence": "他把名字输入了电脑。", "error_description": "错误在“输入”后多加了“给”。输入的对象是电脑，直接接在动词后，应说“输入了电脑”，不能说“输入给了电脑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91488, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "输出", "is_correct": true, "explanation": "反义：输出是把内容从系统送出，与“输入”方向相反。"}, {"text": "打开", "is_correct": false, "explanation": "不构成反义：打开是启动或展开，与“送进内部”不是相对的关系。"}, {"text": "保存", "is_correct": false, "explanation": "不构成反义：保存是把内容存起来，与“输入”不是相对的关系。"}, {"text": "复制", "is_correct": false, "explanation": "不构成反义：复制是做出一份相同的内容，与“输入”不是相对的关系。"}], "correct_answer": "输出", "explanations": {"输出": "反义：输出是把内容从系统送出，与“输入”方向相反。", "打开": "不构成反义：打开是启动或展开，与“送进内部”不是相对的关系。", "保存": "不构成反义：保存是把内容存起来，与“输入”不是相对的关系。", "复制": "不构成反义：复制是做出一份相同的内容，与“输入”不是相对的关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91488, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "输出", "is_correct": true, "explanation": "反义：输出是把内容从系统送出，与“输入”方向相反。"}, {"text": "打印", "is_correct": false, "explanation": "不构成反义：打印是把内容印在纸上，与“输入”不是相对的关系。"}, {"text": "关闭", "is_correct": false, "explanation": "不构成反义：关闭是结束程序或窗口，与“送进内部”不是相对的关系。"}, {"text": "下载", "is_correct": false, "explanation": "不构成反义：下载是从网上取得文件，与“输入”不是相对的关系。"}], "correct_answer": "输出", "explanations": {"输出": "反义：输出是把内容从系统送出，与“输入”方向相反。", "打印": "不构成反义：打印是把内容印在纸上，与“输入”不是相对的关系。", "关闭": "不构成反义：关闭是结束程序或窗口，与“送进内部”不是相对的关系。", "下载": "不构成反义：下载是从网上取得文件，与“输入”不是相对的关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91488, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把外面的东西送进内部；用键盘等向计算机送入数据。", "primary_collocate": null, "pronunciation": "shū rù", "ipa": "ʂu˥ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "工人向机器输入了新的数据。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先输入密码，再打开手机。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生往病人身体里输入营养液。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这些数据输入了系统。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师向机器输入指令，机器就开始工作了。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器需要输入电流才能工作。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管子把水输入了水箱。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "输入错误的数据，电脑会给出错误的结果。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把考试成绩输入系统。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她输入了一串密码，门就开了。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "输入了", "label": "体标"}, {"form": "输入过", "label": "体标"}, {"form": "输入法", "label": "复合"}, {"form": "輸入", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把数据、指令等外面的东西送进机器或系统内部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a13f3c-7d80-4a9a-8407-2021ae5c1faf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91488, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "输入", "is_correct": true, "explanation": "正确：句中是把新数据送进机器内部，“输入”正合适。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是发声，不能用来向机器送入数据。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能用于向机器送数据。"}, {"text": "钓", "is_correct": false, "explanation": "语义：“钓”是用鱼竿捕鱼，与向机器送数据无关。"}], "explanations": {"输入": "正确：句中是把新数据送进机器内部，“输入”正合适。", "唱": "语义：“唱”是发声，不能用来向机器送入数据。", "煮": "搭配：“煮”的对象是食物，不能用于向机器送数据。", "钓": "语义：“钓”是用鱼竿捕鱼，与向机器送数据无关。"}, "sentence_index": 0, "correct_answer": "输入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "系统把结果输入到了屏幕上。", "explanation": "这里应该用〈输出〉。结果从系统送到屏幕上，方向是输出，不是输入。"}, {"text": "他把这些数据输入了桌子。", "explanation": "这里应该用〈系统〉。输入的对象是系统、机器等，桌子不能接收数据。"}, {"text": "他把文件输入给了朋友。", "explanation": "这里应该用〈发送〉。输入是送进机器或系统内部，送给别人要用发送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91488, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "输入", "is_correct": true, "explanation": "正确：管子把水送进水箱内部，“输入”正合适。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是用火加热，不能用来形容管子送水。"}, {"text": "织", "is_correct": false, "explanation": "搭配：“织”的对象是布、线等，不能与“把水”搭配。"}, {"text": "剪", "is_correct": false, "explanation": "语义：“剪”是剪断，与管子把水送进水箱无关。"}], "explanations": {"输入": "正确：管子把水送进水箱内部，“输入”正合适。", "烤": "语义：“烤”是用火加热，不能用来形容管子送水。", "织": "搭配：“织”的对象是布、线等，不能与“把水”搭配。", "剪": "语义：“剪”是剪断，与管子把水送进水箱无关。"}, "sentence_index": 6, "correct_answer": "输入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我从网上输入了一张照片。", "explanation": "这里应该用〈下载〉。从网上取得照片要用下载，输入是送进系统内部，方向相反。"}, {"text": "他把钱输入了口袋。", "explanation": "这里应该用〈装〉。输入只用于系统、机器等，把钱装进口袋要用“装”。"}, {"text": "他从保险箱里输入了钱。", "explanation": "这里应该用〈取出〉。从里面拿出来要用取出，输入是送进去，方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人正在把新数据输入了机器。", "corrected_sentence": "工人正在把新数据输入机器。", "error_description": "错误在“正在”和“了”不能同时用。表示正在进行的动作时，“输入”后不加“了”，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "管理员把考试成绩输入给了系统。", "corrected_sentence": "管理员把考试成绩输入了系统。", "error_description": "错误在“输入”后多加了“给”。输入的对象是系统，直接接在动词后，应说“输入了系统”，不能说“输入给了系统”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
