INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91504, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91504, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指所有人当中的每一个人。", "primary_collocate": null, "pronunciation": "měi ge rén", "ipa": "mei˨˩˦ kə ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "每个人都有自己的名字。", "target_word": "每个人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师给每个人一本书。", "target_word": "每个人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每个人的爱好都不一样。", "target_word": "每个人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生请每个人先量体温。", "target_word": "每个人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌上有五个杯子，每个人一个。", "target_word": "每个人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的作业，每个人要写一篇短文。", "target_word": "每个人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师叫每个人在黑板前说一句话。", "target_word": "每个人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班有三十个学生，每个人都有一把椅子。", "target_word": "每个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的房间里都放着一张小桌子。", "target_word": "每个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始前，每个人都拿到了自己的号码。", "target_word": "每个人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "逐一指代群体中的每一个人，强调个体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a11213-c341-4784-a79b-c98043c84b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91504, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每个人", "is_correct": true, "explanation": "“每个人”指所有人中的每一个，与“都”搭配，表示全体都有自己的名字，句意通顺。"}, {"text": "某人", "is_correct": false, "explanation": "语义：“某人”指某个不确定的人，与“都”要求的全体含义相矛盾。"}, {"text": "这个", "is_correct": false, "explanation": "语义：“这个”指单个的事物或人，不能表示人群中的全体，与“都有自己的名字”搭配不当。"}, {"text": "有人", "is_correct": false, "explanation": "搭配：“有人”表示存在的不定指人，不能与表示全体的“都”搭配，应说“每个人都……”。"}], "explanations": {"每个人": "“每个人”指所有人中的每一个，与“都”搭配，表示全体都有自己的名字，句意通顺。", "某人": "语义：“某人”指某个不确定的人，与“都”要求的全体含义相矛盾。", "这个": "语义：“这个”指单个的事物或人，不能表示人群中的全体，与“都有自己的名字”搭配不当。", "有人": "搭配：“有人”表示存在的不定指人，不能与表示全体的“都”搭配，应说“每个人都……”。"}, "sentence_index": 0, "correct_answer": "每个人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "有的人去了食堂，每个人留在了教室里。", "explanation": "这里应该用〈部分人〉。“每个人”指全体中的每一个，不能与表示部分人的“有的人”并列对照。"}, {"text": "教室里有每个人在打电话。", "explanation": "这里应该用〈有人〉。“每个人”指全体中的每一位，存在句“有……”要用不定指的〈有人〉。"}, {"text": "我想找每个人帮忙，可是一个人也没找到。", "explanation": "这里应该用〈某个人〉。“每个人”指全体，与后面“一个人也没找到”的全部否定矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每个人", "is_correct": true, "explanation": "“每个人”与“叫”搭配，表示老师让全班每一个人依次到黑板前说话，句意通顺。"}, {"text": "它", "is_correct": false, "explanation": "语义：“它”指物或动物，不能到黑板前说话，句意不通。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”回指句首的“老师”，句意变成老师叫自己上前说话，与“叫每个人”全班依次发言的情境不符。"}, {"text": "这里", "is_correct": false, "explanation": "语义：“这里”指地点，不能作“叫”的宾语去说话，句意不通。"}], "explanations": {"每个人": "“每个人”与“叫”搭配，表示老师让全班每一个人依次到黑板前说话，句意通顺。", "它": "语义：“它”指物或动物，不能到黑板前说话，句意不通。", "自己": "语义：“自己”回指句首的“老师”，句意变成老师叫自己上前说话，与“叫每个人”全班依次发言的情境不符。", "这里": "语义：“这里”指地点，不能作“叫”的宾语去说话，句意不通。"}, "sentence_index": 6, "correct_answer": "每个人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛的冠军是每个人。", "explanation": "这里应该用〈某个人〉或具体的人名。“每个人”指全体中的每一个，不能指代一个确定的人。"}, {"text": "这些箱子每个人重五十斤。", "explanation": "这里应该用〈每个箱子〉。“每个人”只指人，不能用来指称箱子。"}, {"text": "今天只来了每个人。", "explanation": "这里应该用〈只来了一个人〉。“只”表示限定，与“每个人”指全体的意思相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个人们都很努力。", "corrected_sentence": "每个人都很努力。", "error_description": "错误在“每个人们”。“每个人”中的“人”已经指一个个的人，后面不能再加“们”，应说“每个人都很努力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每个人都都在努力工作。", "corrected_sentence": "每个人都在努力工作。", "error_description": "错误在“都”重复。“都”只需用一次，应紧跟“每个人”表示全体，说“每个人都在努力工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91509, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91509, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91509, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "高校是大学，是人们长大后继续学习的学校。", "primary_collocate": null, "pronunciation": "gāo xiào", "ipa": "kaʊ˥ ɕi̯aʊ˥˩", "syllable_count": 2, "sentences": [{"text": "高中毕业后，她去了南方的高校。", "target_word": "高校", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在高校学了四年中文。", "target_word": "高校", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐已经在高校读书了。", "target_word": "高校", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这所高校有一座很老的钟楼。", "target_word": "高校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在高校里继续学习历史。", "target_word": "高校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高校的校园又大又漂亮。", "target_word": "高校", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我上的高校，食堂饭菜便宜。", "target_word": "高校", "complexity_tier": "T3", "furigana": "wǒ shàng de gāoxiào, shítáng fàncài piányi", "sentence_source": "generated"}, {"text": "她在高校认识了很多朋友。", "target_word": "高校", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大学生活从进入高校开始。", "target_word": "高校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暑假里，高校里的学生少了很多。", "target_word": "高校", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "高等学校", "label": "全称"}], "register": "中性", "sense_fingerprint": "人们长大后继续学习的大学：在高校读书、高校校园、高校生活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27aa1c00-fc1e-4f9c-85cd-83e1806a40ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91509, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高校", "is_correct": true, "explanation": "高校是高等学校的简称，指大学、专科等高等教育机构。"}, {"text": "搞笑", "is_correct": false, "explanation": "gǎo（第三声）与 gāo（第一声）声调不同，意思是引人发笑，与“高校”（gāo xiào）不同。"}, {"text": "该校", "is_correct": false, "explanation": "gāi 与 gāo 韵母不同（ai 与 ao），意思是“这所学校”，与“高校”不同。"}, {"text": "高小", "is_correct": false, "explanation": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是旧时的高等小学，较少用。"}, {"text": "考校", "is_correct": false, "explanation": "kǎo（第三声）与 gāo（第一声）声母送气不同、声调也不同，意思是考查、校核。"}], "explanations": {"高校": "高校是高等学校的简称，指大学、专科等高等教育机构。", "搞笑": "gǎo（第三声）与 gāo（第一声）声调不同，意思是引人发笑，与“高校”（gāo xiào）不同。", "该校": "gāi 与 gāo 韵母不同（ai 与 ao），意思是“这所学校”，与“高校”不同。", "高小": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是旧时的高等小学，较少用。", "考校": "kǎo（第三声）与 gāo（第一声）声母送气不同、声调也不同，意思是考查、校核。"}, "sentence_index": null, "correct_answer": "高校"}, "level_3": {"options": [{"text": "高校", "is_correct": true, "explanation": "正确。“去了南方的”后接高等学校，符合“高中毕业后继续读书”的语境。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：高中毕业后不会再去幼儿园，与句中的时间顺序矛盾。"}, {"text": "海洋", "is_correct": false, "explanation": "搭配：“去”后接“海洋”不自然，人去海边或下海，不说“去南方的海洋”。"}, {"text": "墓地", "is_correct": false, "explanation": "语义：墓地不是人去读书的地方，与“高中毕业后”去求学的语境矛盾。"}], "explanations": {"高校": "正确。“去了南方的”后接高等学校，符合“高中毕业后继续读书”的语境。", "幼儿园": "语义：高中毕业后不会再去幼儿园，与句中的时间顺序矛盾。", "海洋": "搭配：“去”后接“海洋”不自然，人去海边或下海，不说“去南方的海洋”。", "墓地": "语义：墓地不是人去读书的地方，与“高中毕业后”去求学的语境矛盾。"}, "sentence_index": 0, "correct_answer": "高校"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他五岁时进了高校。", "explanation": "这里应该用〈幼儿园〉。五岁的孩子进的是幼儿园，高校是高等学校，不能用于这里。"}, {"text": "我表妹五岁，每天要去一所高校上学前班。", "explanation": "这里应该用〈学前班〉。五岁的孩子上的是学前班，高校指大学、专科等高等学校。"}, {"text": "我弟弟十二岁，刚上高校。", "explanation": "这里应该用〈中学〉。十二岁的学生刚上的是中学，高校指大学、专科等高等学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91509, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高校", "is_correct": true, "explanation": "正确。“我上的”后接高等学校，指学生就读的学校，符合句意。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：动物园不设学生食堂，与“我上的”的语境矛盾。"}, {"text": "森林", "is_correct": false, "explanation": "语义：森林不是人“上”学的地方，与“食堂”的语境矛盾。"}, {"text": "游乐场", "is_correct": false, "explanation": "搭配：“上”一般接“学校、班”等，“上游乐场”不自然。"}], "explanations": {"高校": "正确。“我上的”后接高等学校，指学生就读的学校，符合句意。", "动物园": "语义：动物园不设学生食堂，与“我上的”的语境矛盾。", "森林": "语义：森林不是人“上”学的地方，与“食堂”的语境矛盾。", "游乐场": "搭配：“上”一般接“学校、班”等，“上游乐场”不自然。"}, "sentence_index": 6, "correct_answer": "高校"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我侄子初三毕业后，进了一所高校。", "explanation": "这里应该用〈中专〉。初三毕业后上的是中专或高中，高校指大学、专科等高等学校。"}, {"text": "我弟弟六岁，暑假就要进高校读书。", "explanation": "这里应该用〈小学〉。六岁的孩子升入的是小学，高校指大学、专科等高等学校。"}, {"text": "我妹妹十五岁，下学期要上高校。", "explanation": "这里应该用〈高中〉。十五岁的学生下学期上的是高中，高校指大学、专科等高等学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
