INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91510, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "高等学校的简称。", "primary_collocate": null, "pronunciation": "gāo xiào", "ipa": "kaʊ˥ ɕi̯aʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这座城市有很多高校。", "target_word": "高校", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在一所高校当老师。", "target_word": "高校", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "全国高校今年九月开学。", "target_word": "高校", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这所高校的图书馆很大。", "target_word": "高校", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她想考北京的高校。", "target_word": "高校", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "高校的学生可以住在学校里。", "target_word": "高校", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥去年进了一所高校。", "target_word": "高校", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多高校都有留学生。", "target_word": "高校", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这几所高校离我家很近。", "target_word": "高校", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他毕业后留在高校工作。", "target_word": "高校", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "高等学校", "label": "全称"}], "register": "中性", "sense_fingerprint": "高等学校的简称：一所高校、全国高校、高校的学生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27aa1c00-fc1e-4f9c-85cd-83e1806a40ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91510, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高校", "is_correct": true, "explanation": "高校是高等学校的简称，指大学、专科等高等教育机构。"}, {"text": "搞笑", "is_correct": false, "explanation": "gǎo（第三声）与 gāo（第一声）声调不同，意思是引人发笑，与“高校”（gāo xiào）不同。"}, {"text": "该校", "is_correct": false, "explanation": "gāi 与 gāo 韵母不同（ai 与 ao），意思是“这所学校”，与“高校”不同。"}, {"text": "高小", "is_correct": false, "explanation": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是旧时的高等小学，较少用。"}, {"text": "考校", "is_correct": false, "explanation": "kǎo（第三声）与 gāo（第一声）声母送气不同、声调也不同，意思是考查、校核。"}], "explanations": {"高校": "高校是高等学校的简称，指大学、专科等高等教育机构。", "搞笑": "gǎo（第三声）与 gāo（第一声）声调不同，意思是引人发笑，与“高校”（gāo xiào）不同。", "该校": "gāi 与 gāo 韵母不同（ai 与 ao），意思是“这所学校”，与“高校”不同。", "高小": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是旧时的高等小学，较少用。", "考校": "kǎo（第三声）与 gāo（第一声）声母送气不同、声调也不同，意思是考查、校核。"}, "sentence_index": null, "correct_answer": "高校"}, "level_3": {"options": [{"text": "高校", "is_correct": true, "explanation": "正确。“这座城市有很多”后接高等学校，语义通顺。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：城市里不会有很多沙漠，与“城市”的语境矛盾。"}, {"text": "太阳", "is_correct": false, "explanation": "搭配：太阳只有一个，不说“很多太阳”。"}, {"text": "宇宙", "is_correct": false, "explanation": "语义：“宇宙”指整个天地，不是城市里可以数的东西。"}], "explanations": {"高校": "正确。“这座城市有很多”后接高等学校，语义通顺。", "沙漠": "语义：城市里不会有很多沙漠，与“城市”的语境矛盾。", "太阳": "搭配：太阳只有一个，不说“很多太阳”。", "宇宙": "语义：“宇宙”指整个天地，不是城市里可以数的东西。"}, "sentence_index": 0, "correct_answer": "高校"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妹妹才十五岁，明年要上高校。", "explanation": "这里应该用〈高中〉。十五岁的学生上的是高中，高校指大学、专科等高等学校。"}, {"text": "我弟弟六岁，刚进高校。", "explanation": "这里应该用〈小学〉。六岁的孩子进的是小学，高校是高等教育机构，不指小学。"}, {"text": "我表弟今年刚从初中毕业，在一所高校学习。", "explanation": "这里应该用〈中专〉。初中毕业后上的是中专，高校指大学、专科等高等学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91510, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高校", "is_correct": true, "explanation": "正确。“进了一所”后接高等学校，符合句意。"}, {"text": "星球", "is_correct": false, "explanation": "语义：“星球”是天体，人不能“进”入一所星球，“所”也不用于星球。"}, {"text": "海洋", "is_correct": false, "explanation": "搭配：“进”后接“海洋”不自然，人入海要说“下海”。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”不是可以进入的机构或建筑，与“进了一所”不搭。"}], "explanations": {"高校": "正确。“进了一所”后接高等学校，符合句意。", "星球": "语义：“星球”是天体，人不能“进”入一所星球，“所”也不用于星球。", "海洋": "搭配：“进”后接“海洋”不自然，人入海要说“下海”。", "月亮": "语义：“月亮”不是可以进入的机构或建筑，与“进了一所”不搭。"}, "sentence_index": 6, "correct_answer": "高校"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他五岁时从高校毕业。", "explanation": "这里应该用〈幼儿园〉。五岁的孩子从幼儿园毕业，高校是高等学校，不能用于这里。"}, {"text": "我弟弟十二岁，明年就要升入高校。", "explanation": "这里应该用〈中学〉。十二岁的学生升入的是中学，高校指大学、专科等高等学校。"}, {"text": "她六岁，每天要去一所高校上学前班。", "explanation": "这里应该用〈学前班〉。六岁的孩子上的是学前班，高校指大学、专科等高等学校，学前班是学前教育。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们城市有几辆高校。", "corrected_sentence": "我们城市有几所高校。", "error_description": "量词错误：错误形式“几辆高校”，正确形式“几所高校”。“高校”是机构，量词用“所”，“辆”只用于车辆。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在一个高校学习。", "corrected_sentence": "我在一所高校学习。", "error_description": "量词错误：错误形式“一个高校”，正确形式“一所高校”。“高校”是机构，量词用“所”，不用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
