INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91511, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "叫人去别的地方做事。", "primary_collocate": null, "pronunciation": "pài qiǎn", "ipa": "pʰai˥˩ tɕʰjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "老板派遣我去北京。", "target_word": "派遣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校派遣老师去外地学习。", "target_word": "派遣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板想派遣一个人去送文件。", "target_word": "派遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司派遣我去广州出差一周。", "target_word": "派遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理派遣了两个同事去机场接客人。", "target_word": "派遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总公司准备派遣一位经理去分公司。", "target_word": "派遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板昨天派遣我去仓库检查货物。", "target_word": "派遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们公司常常派遣员工去国外学习新技术。", "target_word": "派遣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的助手派遣到另一个城市去开店。", "target_word": "派遣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为那边缺人，所以公司派遣了五个人过去帮忙。", "target_word": "派遣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "派遣了", "label": "体标"}, {"form": "派遣过", "label": "体标"}, {"form": "劳务派遣", "label": "复合"}], "register": "正式", "sense_fingerprint": "上级安排某人去别的地方做具体的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a11213-c341-4784-a79b-c98043c84b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91511, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "派遣", "is_correct": true, "explanation": "正确。“派遣”表示上级安排某人去别的地方做事，与“老板……我去北京”相符。"}, {"text": "解雇", "is_correct": false, "explanation": "语义：“解雇”是辞退员工，与“去北京”的安排意思相矛盾。"}, {"text": "挽留", "is_correct": false, "explanation": "语义：“挽留”是请人留下，与“去北京”的方向正好相反，句子读不通。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”的宾语是地点或事物，不能让“我”作宾语再带“去北京”这样的动作。"}], "explanations": {"派遣": "正确。“派遣”表示上级安排某人去别的地方做事，与“老板……我去北京”相符。", "解雇": "语义：“解雇”是辞退员工，与“去北京”的安排意思相矛盾。", "挽留": "语义：“挽留”是请人留下，与“去北京”的方向正好相反，句子读不通。", "参观": "配价：“参观”的宾语是地点或事物，不能让“我”作宾语再带“去北京”这样的动作。"}, "sentence_index": 0, "correct_answer": "派遣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸派遣我去超市买菜。", "explanation": "这里应该用〈带〉。派遣语体正式，派人办事的多是组织或上级，爸爸带孩子办家里的事要用带。"}, {"text": "公司派遣了很多宣传单给客户。", "explanation": "这里应该用〈派发〉。派遣的宾语是人员或队伍，发放宣传单这类物品要用派发。"}, {"text": "朋友派遣我去他家吃饭。", "explanation": "这里应该用〈邀请〉。派遣用于派人执行任务，去朋友家吃饭是私人往来，不能用派遣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91511, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "派遣", "is_correct": true, "explanation": "正确。“派遣”表示安排人去某地做事，与“老板昨天……我去仓库检查货物”相符。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打”是击打，与“去仓库检查货物”的安排意思毫不相关，句子荒谬。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”是斥责，老板骂我之后去仓库检查货物，与派遣的意思不符。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：“讨论”的对象是事情，不能带“我去仓库检查货物”这样的小句作宾语。"}], "explanations": {"派遣": "正确。“派遣”表示安排人去某地做事，与“老板昨天……我去仓库检查货物”相符。", "打": "语义：“打”是击打，与“去仓库检查货物”的安排意思毫不相关，句子荒谬。", "骂": "语义：“骂”是斥责，老板骂我之后去仓库检查货物，与派遣的意思不符。", "讨论": "配价：“讨论”的对象是事情，不能带“我去仓库检查货物”这样的小句作宾语。"}, "sentence_index": 6, "correct_answer": "派遣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生派遣班长去办公室交作业。", "explanation": "这里应该用〈让〉。派遣的施事必须是有权安排他人的组织或上级，学生无权派遣班长，安排班长办事要用让。"}, {"text": "我派遣自己去图书馆看书。", "explanation": "这里不能用派遣。派遣的宾语必须是他人，由派人的一方安排，不能用来说自己动身前往，应直接说“我去图书馆看书”。"}, {"text": "总部派遣经理从上海回来了。", "explanation": "这里应该用〈调回〉。派遣表示派人前往某地，不能表示让人从某地返回。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91511, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司会派遣了两名员工去外地出差。", "corrected_sentence": "公司派遣了两名员工去外地出差。", "error_description": "情态与体标冲突：“会”表示将来，不能与表示已完成的“了”同时用在动词“派遣”上。正确说法是“公司派遣了两名员工去外地出差”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91511, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板正在派遣了小李去仓库取货。", "corrected_sentence": "老板正在派遣小李去仓库取货。", "error_description": "体标冲突：“正在”表示动作进行中，与表示完成的“了”不能同时用在动词“派遣”上，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
