INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91512, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "命令或差遣人员前往执行任务。", "primary_collocate": null, "pronunciation": "pài qiǎn", "ipa": "pʰai˥˩ tɕʰjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "公司派遣他去上海工作。", "target_word": "派遣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "国家派遣医生去山区。", "target_word": "派遣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校派遣两位老师去参加比赛。", "target_word": "派遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府派遣了一支救援队去灾区。", "target_word": "派遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下个月，公司要派遣三个人去国外开会。", "target_word": "派遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理派遣小王去客户那里处理问题。", "target_word": "派遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报社派遣记者去前线，了解那里的情况。", "target_word": "派遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震以后，国家马上派遣军人到那里帮忙。", "target_word": "派遣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院曾经派遣过一队医生去农村看病。", "target_word": "派遣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了完成这个任务，公司派遣了最好的工程师。", "target_word": "派遣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "派遣了", "label": "体标"}, {"form": "派遣过", "label": "体标"}, {"form": "劳务派遣", "label": "复合"}], "register": "正式", "sense_fingerprint": "组织、政府或单位正式命令人员前往执行任务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a11213-c341-4784-a79b-c98043c84b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91512, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "派遣", "is_correct": true, "explanation": "正确。“派遣”指派人前往执行任务，与“公司……派遣他去上海工作”的意思相符。"}, {"text": "解雇", "is_correct": false, "explanation": "语义：“解雇”是辞退员工，与后面“去上海工作”的派任意思相矛盾。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”的宾语是地点或事物，不能带“他去上海工作”这样的小句作宾语。"}, {"text": "看望", "is_correct": false, "explanation": "语义：“看望”是探访某人，不能表示派人去某地工作，句子读不通。"}], "explanations": {"派遣": "正确。“派遣”指派人前往执行任务，与“公司……派遣他去上海工作”的意思相符。", "解雇": "语义：“解雇”是辞退员工，与后面“去上海工作”的派任意思相矛盾。", "参观": "配价：“参观”的宾语是地点或事物，不能带“他去上海工作”这样的小句作宾语。", "看望": "语义：“看望”是探访某人，不能表示派人去某地工作，句子读不通。"}, "sentence_index": 0, "correct_answer": "派遣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈派遣我去超市买菜。", "explanation": "这里应该用〈叫〉。派遣语体正式，派人执行任务的多是组织或上级，家人之间的日常差事要用叫。"}, {"text": "商场派遣了很多传单给路人。", "explanation": "这里应该用〈派发〉。派遣的宾语是人员或队伍，发放传单这类物品要用派发。"}, {"text": "老师派遣我去家里做客。", "explanation": "这里应该用〈邀请〉。派遣用于派人执行任务，去别人家做客是私人往来，不能用派遣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91512, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "派遣", "is_correct": true, "explanation": "正确。“派遣”表示派人前往，与“报社……派遣记者去前线”的意思相符。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：“讨论”的对象是事情或问题，不能带“记者去前线”这样的人加动作结构作宾语。"}, {"text": "报复", "is_correct": false, "explanation": "语义：“报复”是对伤害自己的人进行还击，与派记者去前线了解情况的意思完全不合。"}, {"text": "捉拿", "is_correct": false, "explanation": "语义：“捉拿”是抓捕，报社不能用捉拿来安排记者去前线，句子意思颠倒。"}], "explanations": {"派遣": "正确。“派遣”表示派人前往，与“报社……派遣记者去前线”的意思相符。", "讨论": "配价：“讨论”的对象是事情或问题，不能带“记者去前线”这样的人加动作结构作宾语。", "报复": "语义：“报复”是对伤害自己的人进行还击，与派记者去前线了解情况的意思完全不合。", "捉拿": "语义：“捉拿”是抓捕，报社不能用捉拿来安排记者去前线，句子意思颠倒。"}, "sentence_index": 6, "correct_answer": "派遣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生派遣老师去办公室。", "explanation": "这里应该用〈请〉。派遣的施事必须是有权安排他人的组织或上级，学生无权派遣老师，请老师去办公室要用请。"}, {"text": "我派遣自己去北京出差。", "explanation": "这里不能用派遣。派遣的宾语必须是他人，由派人的一方安排，不能用来说自己动身前往，应直接说“我去北京出差”。"}, {"text": "公司派遣我从广州回来了。", "explanation": "这里应该用〈调回〉。派遣表示派人前往某地，不能表示让人从某地返回。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91512, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医院会派遣了一支医疗队去农村。", "corrected_sentence": "医院派遣了一支医疗队去农村。", "error_description": "情态与体标冲突：“会”表示将来或能力，与表示已完成的“了”不能同时用在动词“派遣”上。正确说法是“医院派遣了一支医疗队去农村”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91512, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国家正在派遣了两名医生去边境。", "corrected_sentence": "国家正在派遣两名医生去边境。", "error_description": "体标冲突：“正在”表示动作进行中，与表示完成的“了”不能同时用在动词“派遣”上，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
