INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91528, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "获得奖励或奖品。", "primary_collocate": null, "pronunciation": "huò jiǎng", "ipa": "xwo˥˩ tɕjaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他在这次比赛中获奖了。", "target_word": "获奖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王的画获奖了，大家都很高兴。", "target_word": "获奖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影去年获奖，很多人去看。", "target_word": "获奖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "获奖的同学可以得到一本书。", "target_word": "获奖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她唱歌很好，常常获奖。", "target_word": "获奖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "哥哥去年获奖，得到一台电脑。", "target_word": "获奖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，获奖的作文会放在学校里。", "target_word": "获奖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小女孩第一次参加比赛就获奖了。", "target_word": "获奖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁获奖，谁就能去北京玩。", "target_word": "获奖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的小说获奖后，卖得更好了。", "target_word": "获奖", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "獲獎", "label": "繁体"}, {"form": "获奖者", "label": "复合"}, {"form": "获过奖", "label": "体标"}], "register": "中性", "sense_fingerprint": "获奖|动作|得到奖励或奖品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e70502b-b805-4b8c-a302-573ca6cc38cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91528, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "获奖", "is_correct": true, "explanation": "正确。「获奖」指比赛后得到奖项，与「在这次比赛中」相符。"}, {"text": "退休", "is_correct": false, "explanation": "语义：「退休」指离开工作岗位，与比赛的结果无关。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：「结婚」不能用于比赛场合，与「在这次比赛中」搭配不当。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：「睡觉」在比赛中发生不合常理，与比赛的结果无关。"}], "explanations": {"获奖": "正确。「获奖」指比赛后得到奖项，与「在这次比赛中」相符。", "退休": "语义：「退休」指离开工作岗位，与比赛的结果无关。", "结婚": "搭配：「结婚」不能用于比赛场合，与「在这次比赛中」搭配不当。", "睡觉": "语义：「睡觉」在比赛中发生不合常理，与比赛的结果无关。"}, "sentence_index": 0, "correct_answer": "获奖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中获奖得很高，大家都很佩服他。", "explanation": "这里应该用〈得分〉。「获奖」指得到奖项，不能用来说明分数高低，计分要用「得分」。"}, {"text": "我们昨天获奖了，今天才到比赛场地。", "explanation": "这里应该用〈参赛〉。「获奖」指比赛结束后得到奖项，不能表示还没参加比赛。"}, {"text": "他的病昨天获奖了，今天可以出院了。", "explanation": "这里应该用〈痊愈〉。「获奖」指得到奖项，不能用来说病好了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91528, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "获奖", "is_correct": true, "explanation": "正确。「获奖」作定语修饰「作文」，表示作文得过奖，与后句相符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：作文不会「生病」，修饰「作文」的说法不合常理。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：作文不会「失眠」，与后句「放在学校里」毫无关联。"}, {"text": "流血", "is_correct": false, "explanation": "语义：作文不会「流血」，修饰「作文」的说法不合常理。"}], "explanations": {"获奖": "正确。「获奖」作定语修饰「作文」，表示作文得过奖，与后句相符。", "生病": "语义：作文不会「生病」，修饰「作文」的说法不合常理。", "失眠": "语义：作文不会「失眠」，与后句「放在学校里」毫无关联。", "流血": "语义：作文不会「流血」，修饰「作文」的说法不合常理。"}, "sentence_index": 6, "correct_answer": "获奖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书获奖得很好，大家都爱看。", "explanation": "这里应该用〈卖〉。「获奖」不能说明销售情况，不能带「得很好」。"}, {"text": "这笔费用获奖了。", "explanation": "这里应该用〈报销〉。「获奖」指比赛得奖，不能用来说费用被批准退还。"}, {"text": "他去年办完离职手续，每天在家获奖。", "explanation": "这里应该用〈退休〉。「获奖」指得到奖项，不能用来说离开工作岗位后的生活。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91528, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在这次比赛中获奖着。", "corrected_sentence": "她在这次比赛中获奖了。", "error_description": "体标用错：「获奖」是已完成的动作，应用「了」表示完成，说「获奖了」；「着」表示持续的状态，不能用于已经结束的获奖。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91528, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是去年的一只获奖者。", "corrected_sentence": "他是去年的一个获奖者。", "error_description": "量词用错：「获奖者」指人，量词应用「个」，不能用「只」（「只」多用于动物等）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
