INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91533, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "就是那一天。", "primary_collocate": null, "pronunciation": "dāng rì", "ipa": "taŋ˥ ɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "结婚当日，他穿了一件白衬衫。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业当日，我们在学校门口照了相。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出发当日，下了一场大雨。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开业当日，店里来了很多客人。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了约好的当日，她却没来。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我永远记得当日的情景。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当日他说了什么，我已经忘了。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛当日，我的朋友也去看了。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当日的天气很冷，大家都穿着外套。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看书的时候，我想起了当日的事。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "当日：回头指说的那一天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2beb4a87-1356-4fca-8f26-67e841f14fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91533, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "闹钟", "is_correct": false, "explanation": "语义：“闹钟”不指日子，与“结婚”的时间限定不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”不能表示时间，不能限定“结婚”。"}, {"text": "当日", "is_correct": true, "explanation": "当日：就是那一天，指回头说的结婚那天，与句意相符。"}, {"text": "礼堂", "is_correct": false, "explanation": "搭配：“礼堂”指场所，不能作“结婚”的时间状语。"}], "explanations": {"闹钟": "语义：“闹钟”不指日子，与“结婚”的时间限定不通。", "书包": "语义：“书包”不能表示时间，不能限定“结婚”。", "当日": "当日：就是那一天，指回头说的结婚那天，与句意相符。", "礼堂": "搭配：“礼堂”指场所，不能作“结婚”的时间状语。"}, "sentence_index": 0, "correct_answer": "当日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天当日店里很忙，客人很多。", "explanation": "这里应该删去〈当日〉。“当日”指前文说到的那一天，不能用来指说话的当天，二者冲突。"}, {"text": "他一直当日都来店里买东西。", "explanation": "这里应该用〈每天〉。“当日”只指特定的一天，不能用来表示持续重复。"}, {"text": "我们开业当日准备了半年。", "explanation": "这里应该把时段放在“开业当日”之前来表达，“当日”只指一天，不能与“半年”这样的时段连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91533, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“天气”不指某一天，不能用来指代“他说了什么”的那一天。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”指场所，不能指说话的时间。"}, {"text": "讲台", "is_correct": false, "explanation": "搭配：“讲台”是处所，不能作时间状语。"}, {"text": "当日", "is_correct": true, "explanation": "当日：就是那一天，指前文说到的那天，与句意相符。"}], "explanations": {"天气": "语义：“天气”不指某一天，不能用来指代“他说了什么”的那一天。", "食堂": "语义：“食堂”指场所，不能指说话的时间。", "讲台": "搭配：“讲台”是处所，不能作时间状语。", "当日": "当日：就是那一天，指前文说到的那天，与句意相符。"}, "sentence_index": 6, "correct_answer": "当日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一个当日就想起了那件事。", "explanation": "这里应该删去〈一个〉，说“我当日就想起了那件事”。“当日”前不能直接加数量词。"}, {"text": "我们还没认识，他当日就来找我了。", "explanation": "这里应该用〈那天〉并交代前文的日子。“当日”需要承接前文已确定的日子，这里前文没有依托。"}, {"text": "我的同学当日很高，每天都打篮球。", "explanation": "这里应该用〈身材〉之类的词。“当日”只指日期，不能用来形容人的高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91533, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "结婚当日的，我们拍了很多照片。", "corrected_sentence": "结婚当日，我们拍了很多照片。", "error_description": "错误：“当日”后面多加了“的”。正确：“当日”作时间状语，直接说“结婚当日，……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91533, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他当日的就走了。", "corrected_sentence": "他当日就走了。", "error_description": "错误：“当日”后面多加了“的”。正确：“当日”作时间状语，直接说“他当日就走了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
