INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91534, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情发生的那一天；当天。", "primary_collocate": null, "pronunciation": "dāng rì", "ipa": "taŋ˥ ɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "活动当日，天气非常好。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张票只在当日有效。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当日就把信寄出去了。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店当日送货，不用等很久。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛当日，很多人来看。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事故当日，路上有很多车。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当日的会议很短。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你买的牛奶要当日喝完。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试当日，他早早起床了。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店可以当日取货。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "当日：事情发生的那一天，当天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2beb4a87-1356-4fca-8f26-67e841f14fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91534, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当年", "is_correct": false, "explanation": "语义：“当年”指那一年，与“活动”的具体日子不符。"}, {"text": "当初", "is_correct": false, "explanation": "语义：“当初”指起初、开始的时候，不指具体的某一天。"}, {"text": "当日", "is_correct": true, "explanation": "当日：事情发生的那一天，当天，与“活动”的日子相符。"}, {"text": "当地", "is_correct": false, "explanation": "搭配：“当地”指地方，不能作时间状语限定“活动”。"}], "explanations": {"当年": "语义：“当年”指那一年，与“活动”的具体日子不符。", "当初": "语义：“当初”指起初、开始的时候，不指具体的某一天。", "当日": "当日：事情发生的那一天，当天，与“活动”的日子相符。", "当地": "搭配：“当地”指地方，不能作时间状语限定“活动”。"}, "sentence_index": 0, "correct_answer": "当日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店当日营业了三天。", "explanation": "这里应该删去〈当日〉，说“这家店营业了三天”。“当日”只指一天，不能与“三天”这样的时段连用。"}, {"text": "我这周当日都很忙。", "explanation": "这里应该用〈每天〉。“当日”只指一天，不能用来概括一周。"}, {"text": "我花了两个当日才完成作业。", "explanation": "这里应该用〈两天〉。“当日”指某一天，本身不能计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是日期，不能用来限定“会议”。"}, {"text": "教材", "is_correct": false, "explanation": "语义：“教材”指学习用的书籍，不能指会议的时间。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“会议”不能用“心情”来限定。"}, {"text": "当日", "is_correct": true, "explanation": "当日：指事情发生的那一天，与“会议”搭配，表示那天的会议。"}], "explanations": {"天气": "语义：“天气”不是日期，不能用来限定“会议”。", "教材": "语义：“教材”指学习用的书籍，不能指会议的时间。", "心情": "搭配：“会议”不能用“心情”来限定。", "当日": "当日：指事情发生的那一天，与“会议”搭配，表示那天的会议。"}, "sentence_index": 6, "correct_answer": "当日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我花了半个当日才把作业做完。", "explanation": "这里应该用〈半天〉。“当日”指一整天，不能用“半个”计量。"}, {"text": "他当日的一生很长。", "explanation": "这里应该删去〈当日〉。“当日”只指一天，不能修饰“一生”这样的长时段。"}, {"text": "我当日的脚很大，所以鞋子买小了。", "explanation": "这里应该删去〈当日〉。“当日”只能用来指与日期相关的事，不能修饰身体部位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "展览当日的，馆里挤满了人。", "corrected_sentence": "展览当日，馆里挤满了人。", "error_description": "错误：“当日”后面多加了“的”。正确：“当日”作时间状语，直接说“展览当日，……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店可以把当日取货。", "corrected_sentence": "这家店可以当日取货。", "error_description": "错误：多加了“把”。“当日”是时间词，不能放在“把”后作宾语。正确：“这家店可以当日取货”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
