INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91537, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "内地是离海很远的地方。", "primary_collocate": null, "pronunciation": "nèi dì", "ipa": "nei˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "内地离海很远，夏天比海边热。", "target_word": "内地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家在内地，一年也看不到几次海。", "target_word": "内地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "内地的小城市很安静。", "target_word": "内地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从海边搬到了内地。", "target_word": "内地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种鱼在内地很少见到。", "target_word": "内地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "内地没有海，所以人们很少吃海鲜。", "target_word": "内地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从海边到内地要坐一天的车。", "target_word": "内地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "内地的冬天比沿海冷。", "target_word": "内地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "很多年轻人离开内地，去海边工作。", "target_word": "内地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "内地的孩子很少有机会看到大海。", "target_word": "内地", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "内地人", "label": "复合"}], "register": "中性", "sense_fingerprint": "内地：离海很远的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '476a3295-ccc1-45f7-ab1b-c537dc3fa42a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91537, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海岛", "is_correct": false, "explanation": "语义：海岛本身在海上，与“离海很远”矛盾。"}, {"text": "内地", "is_correct": true, "explanation": "正确。“内地”指离海很远的地方，与“离海很远”相符，夏天也比海边热。"}, {"text": "港口", "is_correct": false, "explanation": "语义：港口紧靠海边，与“离海很远”矛盾。"}, {"text": "海滨", "is_correct": false, "explanation": "语域：“海滨”偏书面，且指海边，与“离海很远”的语义矛盾。"}], "explanations": {"海岛": "语义：海岛本身在海上，与“离海很远”矛盾。", "内地": "正确。“内地”指离海很远的地方，与“离海很远”相符，夏天也比海边热。", "港口": "语义：港口紧靠海边，与“离海很远”矛盾。", "海滨": "语域：“海滨”偏书面，且指海边，与“离海很远”的语义矛盾。"}, "sentence_index": 0, "correct_answer": "内地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家在内地，走路五分钟就能到沙滩。", "explanation": "这里应该用〈海滨〉。“内地”指离海很远的地方，走路五分钟就到沙滩说明离海很近，应说“海滨”。"}, {"text": "我家在内地，每天清晨都能闻到海风的咸味。", "explanation": "这里应该用〈海边〉。“内地”指离海很远的地方，闻到海风与此矛盾，应说“海边”。"}, {"text": "我们每天傍晚都在内地的海边散步，听海浪的声音。", "explanation": "这里应该用〈沿海〉。“内地”指离海很远的地方，不能每天在海边散步、听海浪，应说“沿海”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91537, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "码头", "is_correct": false, "explanation": "搭配：码头是船只停靠的地方，不能说“坐一天的车”到码头去。"}, {"text": "近郊", "is_correct": false, "explanation": "语义：近郊靠近市区，路程不远，与“要坐一天的车”矛盾。"}, {"text": "内地", "is_correct": true, "explanation": "正确。从海边到离海很远的内地，路程长，需要坐一天的车。"}, {"text": "海边", "is_correct": false, "explanation": "语义：起点和终点都是海边，不需要坐一天的车。"}], "explanations": {"码头": "搭配：码头是船只停靠的地方，不能说“坐一天的车”到码头去。", "近郊": "语义：近郊靠近市区，路程不远，与“要坐一天的车”矛盾。", "内地": "正确。从海边到离海很远的内地，路程长，需要坐一天的车。", "海边": "语义：起点和终点都是海边，不需要坐一天的车。"}, "sentence_index": 6, "correct_answer": "内地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座小城的内地每天清晨都很热闹，渔船满载而归。", "explanation": "这里应该用〈渔港〉。“内地”离海很远，渔船满载而归需要靠海的渔港，与句意矛盾。"}, {"text": "这个内地每天有很多货船进出。", "explanation": "这里应该用〈港口〉。货船需要靠海停靠，内地离海很远，与句意矛盾。"}, {"text": "渔船在内地靠岸，卸下了一天的鱼。", "explanation": "这里应该用〈码头〉。渔船靠岸卸鱼要在水边，内地离海远，与句意矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91537, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我舅舅年轻时就内地工作。", "corrected_sentence": "我舅舅年轻时就在内地工作。", "error_description": "漏掉介词“在”。表示地点的“内地”前应加“在”，应为“在内地工作”，不能直接说“就内地工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91537, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是内地的一个小镇上班。", "corrected_sentence": "他在内地的一个小镇上班。", "error_description": "“是”不能引出表示地点的成分，地点要用介词“在”；“是内地的一个小镇上班”不通，应改为“在内地的一个小镇上班”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
