INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91538, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "与香港、澳门、台湾相对的中国大陆地区。", "primary_collocate": null, "pronunciation": "nèi dì", "ipa": "nei˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "他在香港工作，周末回内地看家人。", "target_word": "内地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多香港人喜欢到内地旅游。", "target_word": "内地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影下个月在内地上映。", "target_word": "内地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "内地和澳门之间有一座大桥。", "target_word": "内地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从台湾来内地读书。", "target_word": "内地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "内地的手机支付很方便。", "target_word": "内地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她在内地长大，后来去了香港。", "target_word": "内地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司在内地有二十家店。", "target_word": "内地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去内地的火车票已经卖完了。", "target_word": "内地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我朋友在内地上大学，现在住在香港。", "target_word": "内地", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "内地人", "label": "复合"}], "register": "中性", "sense_fingerprint": "内地：与港澳台相对，指中国大陆", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '476a3295-ccc1-45f7-ab1b-c537dc3fa42a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91538, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公司", "is_correct": false, "explanation": "语义：周末回公司看家人，家人并不在公司，句意不通。"}, {"text": "内地", "is_correct": true, "explanation": "正确。“内地”指与香港相对的中国大陆，此句说他周末回大陆看家人。"}, {"text": "宿舍", "is_correct": false, "explanation": "语义：宿舍是住处而非家人所在之地，“回宿舍看家人”不合句意。"}, {"text": "学府", "is_correct": false, "explanation": "语域：“学府”偏书面，且指学校，与“周末回……看家人”的口语语境不协调。"}], "explanations": {"公司": "语义：周末回公司看家人，家人并不在公司，句意不通。", "内地": "正确。“内地”指与香港相对的中国大陆，此句说他周末回大陆看家人。", "宿舍": "语义：宿舍是住处而非家人所在之地，“回宿舍看家人”不合句意。", "学府": "语域：“学府”偏书面，且指学校，与“周末回……看家人”的口语语境不协调。"}, "sentence_index": 0, "correct_answer": "内地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "香港是内地的一个大城市，每天都有很多游客。", "explanation": "这里不能用〈内地〉指香港。香港与“内地”相对，不属于内地。"}, {"text": "澳门是内地的一个小镇，风景很美。", "explanation": "这里不能用〈内地〉指澳门。澳门与“内地”相对，不属于内地。"}, {"text": "台北是内地的一个城市，我们常去那里玩。", "explanation": "这里不能用〈内地〉指台北。台北属台湾，与“内地”相对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91538, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：人不会在厨房里长大，与“后来去了香港”的成长叙述不合。"}, {"text": "医院", "is_correct": false, "explanation": "语义：人不会在医院里长大，此句说的是正常的成长经历。"}, {"text": "内地", "is_correct": true, "explanation": "正确。“内地”指中国大陆，“在内地长大，后来去了香港”符合句意。"}, {"text": "车站", "is_correct": false, "explanation": "搭配：“在……长大”通常指居住之地，车站不宜作为居住地点。"}], "explanations": {"厨房": "语义：人不会在厨房里长大，与“后来去了香港”的成长叙述不合。", "医院": "语义：人不会在医院里长大，此句说的是正常的成长经历。", "内地": "正确。“内地”指中国大陆，“在内地长大，后来去了香港”符合句意。", "车站": "搭配：“在……长大”通常指居住之地，车站不宜作为居住地点。"}, "sentence_index": 6, "correct_answer": "内地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个渔村属于香港，却算是内地的一部分，每天清晨都有渔船靠岸。", "explanation": "这里不能说〈内地〉。香港的渔村与“内地”相对，不能算作内地的一部分。"}, {"text": "这座小城在澳门，是内地最大的渔港。", "explanation": "这里不能说〈内地〉。澳门与“内地”相对，澳门的小城不能算内地的渔港。"}, {"text": "这支船队在澳门登记，却是内地的渔船。", "explanation": "这里不能说〈内地〉。在澳门登记的渔船不属于内地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的朋友内地上大学。", "corrected_sentence": "我的朋友在内地上大学。", "error_description": "漏掉介词“在”。表示地点的“内地”前应加“在”，应为“在内地上大学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的老师是内地教书。", "corrected_sentence": "我的老师在内地教书。", "error_description": "“是”不能引出表示地点的成分，地点要用介词“在”；“是内地教书”不通，应改为“在内地教书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
