INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91545, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用刀用力切下去。", "primary_collocate": null, "pronunciation": "kǎn", "ipa": "kʰan˨˩˦", "syllable_count": 1, "sentences": [{"text": "他拿起刀，用力砍在骨头上。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师用刀把大骨头砍成两段。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你小心，别砍到自己的手。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了一块肉，我帮她砍开。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一刀砍下去，西瓜就开了。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把刀很重，砍肉很方便。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点，我昨天砍到了手指。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力砍了几刀，鱼头掉了。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板正在案板上砍鸡。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着刀，一下一下砍着骨头。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "砍了", "label": "体标"}, {"form": "砍过", "label": "体标"}, {"form": "砍着", "label": "体标"}], "register": "中性", "sense_fingerprint": "用刀用力向下切骨头、肉等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a11213-c341-4784-a79b-c98043c84b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91545, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "砍", "is_correct": true, "explanation": "正确。“砍”（kǎn）指用刀用力切下去。"}, {"text": "看", "is_correct": false, "explanation": "kàn（第四声）与 kǎn（第三声）声调不同，意思是看。"}, {"text": "敢", "is_correct": false, "explanation": "gǎn（第三声）与 kǎn 声母不同（g 与 k），意思是敢。"}, {"text": "刊", "is_correct": false, "explanation": "kān（第一声）与 kǎn（第三声）声调不同，意思是刊登。"}], "explanations": {"砍": "正确。“砍”（kǎn）指用刀用力切下去。", "看": "kàn（第四声）与 kǎn（第三声）声调不同，意思是看。", "敢": "gǎn（第三声）与 kǎn 声母不同（g 与 k），意思是敢。", "刊": "kān（第一声）与 kǎn（第三声）声调不同，意思是刊登。"}, "sentence_index": null, "correct_answer": "砍"}, "level_3": {"options": [{"text": "砍", "is_correct": true, "explanation": "正确。“砍”指用刀用力切下去，与“拿起刀，用力……在骨头上”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能说用力吃在骨头上。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是物件或身体，不能与“用力……在骨头上”这样的动作搭配。"}, {"text": "舔", "is_correct": false, "explanation": "语义：“舔”是用舌头接触，与拿刀用力的动作完全不符。"}], "explanations": {"砍": "正确。“砍”指用刀用力切下去，与“拿起刀，用力……在骨头上”相符。", "吃": "搭配：“吃”的宾语是食物，不能说用力吃在骨头上。", "洗": "搭配：“洗”的对象是物件或身体，不能与“用力……在骨头上”这样的动作搭配。", "舔": "语义：“舔”是用舌头接触，与拿刀用力的动作完全不符。"}, "sentence_index": 0, "correct_answer": "砍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用刀砍了苹果皮。", "explanation": "这里应该用〈削〉。削苹果皮是薄薄地去皮，砍是用力切断，不能这样用。"}, {"text": "他把火腿砍成了很薄的片。", "explanation": "这里应该用〈切〉。切薄片要轻而均匀地下刀；砍是用刀猛力切断，切不出很薄的片，不能这样用。"}, {"text": "她用剪刀砍断了线。", "explanation": "这里应该用〈剪〉。剪线要用剪刀，砍需要刀斧等有刃工具猛力切断，不能用剪刀来砍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91545, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "砍", "is_correct": true, "explanation": "正确。“砍”（kǎn）指用刀用力切下去。"}, {"text": "赶", "is_correct": false, "explanation": "gǎn（第三声）与 kǎn 声母不同（g 与 k），意思是追赶。"}, {"text": "款", "is_correct": false, "explanation": "读音：“款”（kuǎn）与“砍”（kǎn）声调相同，只差介音 u，意思是款项，不是近义词。"}, {"text": "感", "is_correct": false, "explanation": "gǎn（第三声）与 kǎn 声母不同（g 与 k），意思是感觉。"}], "explanations": {"砍": "正确。“砍”（kǎn）指用刀用力切下去。", "赶": "gǎn（第三声）与 kǎn 声母不同（g 与 k），意思是追赶。", "款": "读音：“款”（kuǎn）与“砍”（kǎn）声调相同，只差介音 u，意思是款项，不是近义词。", "感": "gǎn（第三声）与 kǎn 声母不同（g 与 k），意思是感觉。"}, "sentence_index": null, "correct_answer": "砍"}, "level_3": {"options": [{"text": "砍", "is_correct": true, "explanation": "正确。“砍”指用刀猛力切下去，与“我昨天……到了手指”的意外伤害相符。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”的宾语是商品，不能说买到了手指。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”是递交或护送，与被刀伤的意思完全不符。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字或纸张，写到手指不成立。"}], "explanations": {"砍": "正确。“砍”指用刀猛力切下去，与“我昨天……到了手指”的意外伤害相符。", "买": "搭配：“买”的宾语是商品，不能说买到了手指。", "送": "语义：“送”是递交或护送，与被刀伤的意思完全不符。", "写": "搭配：“写”的对象是文字或纸张，写到手指不成立。"}, "sentence_index": 6, "correct_answer": "砍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用手指砍了桌子。", "explanation": "这里应该用〈敲〉。敲是用手或器物轻轻击打，砍必须用刀斧等有刃工具猛力切断，徒手不能砍。"}, {"text": "妈妈砍了一个橘子的皮。", "explanation": "这里应该用〈剥〉。剥橘子皮是把皮扯下来，砍是用力切断，不能这样说。"}, {"text": "她砍了一点牙膏。", "explanation": "这里应该用〈挤〉。牙膏要靠挤压才能出来，砍是用有刃工具切断，不能用来形容牙膏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91545, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用刀把木板砍到了三块。", "corrected_sentence": "他用刀把木板砍成了三块。", "error_description": "补语错误：“砍……成”表示结果，“到”不能表示分成几块，应该用“成”。正确说法是“砍成了三块”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91545, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一刀一刀砍了着骨头。", "corrected_sentence": "他一刀一刀砍着骨头。", "error_description": "体标错误：“着”表示动作持续，“了”表示动作完成，两者不能同时用在动词后。这里应去掉“了”，保留“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
