INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91546, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用刀、斧等猛力把物体断开。", "primary_collocate": null, "pronunciation": "kǎn", "ipa": "kʰan˨˩˦", "syllable_count": 1, "sentences": [{"text": "爷爷拿着斧子去山上砍树。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们砍了一天的柴。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树太粗，一把斧子砍不断。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用斧头砍断了老树根。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，爸爸去树林里砍柴。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力砍，大树终于倒了。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没砍过树。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在路边砍着竹子。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要乱砍山上的树。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把门前的那棵老树砍了。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "砍了", "label": "体标"}, {"form": "砍过", "label": "体标"}, {"form": "砍着", "label": "体标"}], "register": "中性", "sense_fingerprint": "用斧、刀猛力砍断树木、柴、竹子等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a11213-c341-4784-a79b-c98043c84b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
